window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s6-654","number":654,"surah":6,"verses":[90],"verseLabel":"الأنعام: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿لا أسألكم عليه أجرًا﴾ بعد الأمر بالاقتداء؟","answer":"لما كان من هدي الأنبياء تبليغ الدين بلا طلب عوض، جاء نفي الأجر تطبيقًا للأمر بالاقتداء، ودليلًا على صدق الرسول وتجرده في البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص333–345.","url":""}]},{"id":"s6-655","number":655,"surah":6,"verses":[90],"verseLabel":"الأنعام: 90","question":"لماذا حصر القرآن أو الهدى في قوله: ﴿إن هو إلا ذكرى للعالمين﴾؟","answer":"القصر بالنفي والاستثناء قصر إضافي: مهمة الرسول والقرآن تجاه المخاطبين التذكير لا طلب الأجر. ولا ينفي ما للقرآن من هداية وتشريع ووظائف أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص333–345.","url":""}]},{"id":"s6-656","number":656,"surah":6,"verses":[90],"verseLabel":"الأنعام: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿ذكرى﴾ لا: ذكر؟","answer":"أُخبر بالمصدر ﴿ذكرى﴾ للمبالغة، فكأن القرآن هو التذكير نفسه لا مجرد كلام يذكّر أحيانًا، وإضافته للعالمين تدل على عموم الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص333–345.","url":""}]},{"id":"s6-657","number":657,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وما قدروا الله حق قدره﴾، فعبّر عن المعرفة بالتقدير؟","answer":"القدر معرفة مقدار الشيء ومنزلته وتعظيمه؛ فمن نفى أن ينزل الله وحيًا على بشر لم يعرف حكمته ورحمته وصفة كلامه حق المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-658","number":658,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"لماذا أضيف ﴿حق﴾ إلى ﴿قدره﴾؟","answer":"إضافة ﴿حق﴾ إلى ﴿قدره﴾ تؤكد المقدار الواجب من المعرفة والتعظيم، وتفظع جهلهم؛ إذ لم ينقصوا بعض حقه فحسب، بل نفوا أصل ما يليق به من إرسال الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-659","number":659,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"لماذا جُعل قولهم ﴿ما أنزل الله على بشر من شيء﴾ دليلًا على عدم تعظيم الله؟","answer":"إنكار الوحي جهل بصفة كلام الله، وبحكمته في هداية الناس، وبرحمته ولطفه بإبلاغ مراده إليهم بواسطة الرسل؛ لذلك عُدّ نقصًا في تعظيمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-660","number":660,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"ما سرّ اختيارهم لفظ ﴿بشر﴾ في قولهم: ﴿ما أنزل الله على بشر من شيء﴾، دون لفظ «رسول»؟","answer":"قالوا ﴿على بشر﴾ ليعمموا نفي الوحي عن جنس الإنسان كله، لا عن رسول معين؛ ولو قالوا «على رسول» لكان في اللفظ إقرار بأصل الرسالة التي ينكرونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-661","number":661,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"لماذا اجتمع النفي و﴿من﴾ في ﴿من شيء﴾؟","answer":"دخول ﴿من﴾ على النكرة في سياق النفي يؤكد الاستغراق؛ فهم زعموا أن الله لم ينزل على أي بشر شيئًا قط، ولو كان أدنى شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-662","number":662,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"لماذا كان الرد سؤالًا: ﴿قل من أنزل الكتاب الذي جاء به موسى﴾؟","answer":"جاء الرد سؤالًا ليُلزمهم بما يقرون به من كتاب موسى: إن أنكروا كل وحي فمن أنزل التوراة؟ فالدليل مأخوذ من أصل مسلم عندهم، ولا يسعهم دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-663","number":663,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"لماذا وُصف كتاب موسى بأنه ﴿نورًا وهدى للناس﴾؟","answer":"النور يكشف الحقائق ويبدد ظلمات الجهل، والهدى يرشد إلى الطريق والعمل؛ فجمع الوصفان بين الكشف النظري والدلالة العملية، وعم نفع الكتاب الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-664","number":664,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿تجعلونه قراطيس﴾، فجعل الكتاب نفسه أوراقًا متفرقة؟","answer":"ليس الذم لمجرد كتابة الكتاب في أوراق، بل لأنهم جزؤوه قراطيس متفرقة ليظهروا ما وافق أغراضهم ويخفوا كثيرًا؛ فالتجزئة وسيلة للتلاعب بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-665","number":665,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"لماذا جُمعت ﴿قراطيس﴾؟","answer":"جُمعت ﴿قراطيس﴾ للدلالة على تفريق الكتاب الواحد في صحائف كثيرة، بما يمكّنهم من إبداء بعضها وإخفاء بعضها بدل عرضه كاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-666","number":666,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿تبدونها وتخفون كثيرًا﴾، فحذف مفعول ﴿تخفون﴾ ووصفه بالكثرة؟","answer":"التقدير: تخفون كثيرًا منها أو من الكتاب. وحذف المتعلق إيجاز، ووصف المحذوف بالكثرة يبرز أن الظاهر قليل وأن الجزء الأكبر مما عندهم مستور.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-667","number":667,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وعلمتم ما لم تعلموا أنتم ولا آباؤكم﴾، وأظهر ﴿أنتم﴾؟","answer":"أُظهر ضمير ﴿أنتم﴾ مع دلالة الفعل عليه لتوكيد اختصاص المخاطبين بالامتنان، ثم عطف الآباء لنفي أن يكون هذا العلم موروثًا عنهم؛ فهو من تعليم الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-668","number":668,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"لماذا جاء الجواب كلمة واحدة: ﴿قل الله﴾؟","answer":"اقتُصر على ﴿الله﴾ لأن الجواب لا يحتمل غيره، وفي إيجازه حسم للحجة وتعجيل بالفائدة، ثم ترك لهم مجال التفكر في لازم اعترافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-669","number":669,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"ما دلالة الانتقال بعد إقامة الحجة إلى قوله تعالى: ﴿ثم ذرهم في خوضهم يلعبون﴾؟","answer":"جاء ﴿ثم﴾ للترتيب الرتبي: بعد إقامة الحجج وقطع المعاذير لا يبقى إلا تركهم وتهديدهم بعاقبة خوضهم، وليس المقصود ترك دعوتهم قبل البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-670","number":670,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"لماذا جُمع بين ﴿خوضهم﴾ و﴿يلعبون﴾؟","answer":"الخوض دخول في الباطل كما يخوض المرء في الماء، واللعب فعل بلا غاية نافعة؛ فالأول يصور مجال كلامهم الباطل، والثاني يكشف عبثهم وعدم جدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص346–375.","url":""}]},{"id":"s6-671","number":671,"surah":6,"verses":[91],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى عن أهل الكتاب: ﴿تخفون كثيرًا﴾، ويعبّر القرآن في مواضع أخرى عن صنيعهم بالكتمان؟","answer":"الكتمان يختص غالبًا بالمعاني والأخبار، وهو السكوت عما يطلب إظهاره؛ أما الإخفاء فأعم، يقع في المعاني والمحسوسات. ولما صُورت التوراة قراطيس محسوسة قيل ﴿تخفون كثيرًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص445؛ ج7، ص161.","url":""}]},{"id":"s6-672","number":672,"surah":6,"verses":[92],"verseLabel":"الأنعام: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿وهذا كتاب أنزلناه مبارك﴾ باسم الإشارة؟","answer":"اسم الإشارة للقريب يستحضر القرآن كأنه حاضر مشاهد، ولا سيما بعد جدالهم في نزول الوحي، ويزيد المشار إليه تمييزًا وتفخيمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص376–395.","url":""}]},{"id":"s6-673","number":673,"surah":6,"verses":[92],"verseLabel":"الأنعام: 92","question":"لماذا نُكّر ﴿كتاب﴾ ووصف بـ﴿مبارك﴾؟","answer":"نُكر ﴿كتاب﴾ للتعظيم، ووصفه بـ﴿مبارك﴾ لثبوت الخير الكثير ونمائه منه؛ فالبركة صفة ملازمة لما أنزله الله، وصرح بها تأكيدًا لعظيم نفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص376–395.","url":""}]},{"id":"s6-674","number":674,"surah":6,"verses":[92],"verseLabel":"الأنعام: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿مصدق الذي بين يديه﴾، فجعل الكتب السابقة بين يدي القرآن؟","answer":"التعبير بـ﴿بين يديه﴾ استعارة تجعل الكتب السابقة كأنها حاضرة أمام القرآن ومتقدمة عليه، وهو يأتي مصدقًا لأصولها وشاهدًا عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص376–395.","url":""}]},{"id":"s6-675","number":675,"surah":6,"verses":[92],"verseLabel":"الأنعام: 92","question":"لماذا أفرد الموصول: ﴿الذي بين يديه﴾؟","answer":"أُفرد ﴿الذي﴾ لأن المراد جنس الكتاب أو الوحي السابق كله، فجمع التوراة والإنجيل وسائر ما تقدم في معنى واحد هو الوحي الذي بين يدي القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص376–395.","url":""}]},{"id":"s6-676","number":676,"surah":6,"verses":[92],"verseLabel":"الأنعام: 92","question":"لماذا سُميت مكة ﴿أم القرى﴾؟","answer":"سميت مكة أم القرى لأنها أصلها وأعظمها شأنًا، وفيها أول بيت وضع للناس، وهي قبلة أهل القرى ومحجهم؛ فالأم مستعارة للأصل والمرجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص376–395.","url":""}]},{"id":"s6-677","number":677,"surah":6,"verses":[92],"verseLabel":"الأنعام: 92","question":"لماذا عطف ﴿ومن حولها﴾ على أم القرى؟","answer":"عطف ﴿ومن حولها﴾ لتوسيع دائرة الإنذار من مركز الرسالة إلى سائر البلاد، ولا يقتضي حصرها في المحيط القريب؛ فالمكان مبدأ البلاغ لا غاية عمومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص376–395.","url":""}]},{"id":"s6-678","number":678,"surah":6,"verses":[92],"verseLabel":"الأنعام: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين يؤمنون بالآخرة يؤمنون به﴾، فجعل الإيمان بالآخرة سببًا للإيمان بالقرآن؟","answer":"من أيقن بالبعث والجزاء عظمت رغبته في الثواب ورهبته من العقاب، فحمله ذلك على النظر في دلائل النبوة والإيمان بالقرآن الذي أبرز مشاهد الآخرة وقررها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص376–395.","url":""}]},{"id":"s6-679","number":679,"surah":6,"verses":[92],"verseLabel":"الأنعام: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم على صلاتهم يحافظون﴾ بتقديم ﴿على صلاتهم﴾؟","answer":"قُدم ﴿على صلاتهم﴾ للاختصاص والعناية؛ فالمحافظة على الصلاة علامة ظاهرة لأهل الإيمان، واختصاصها بهذه العناية يقود إلى حفظ سائر الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص376–395.","url":""}]},{"id":"s6-680","number":680,"surah":6,"verses":[92],"verseLabel":"الأنعام: 92","question":"لماذا اختير ﴿يحافظون﴾ بصيغة المفاعلة؟","answer":"المحافظة أبلغ من مجرد الفعل؛ فهي عهد مستمر يقتضي التعاهد والمداومة وحفظ الأركان والأوقات، لا أداء الصلاة مرة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص376–395.","url":""}]},{"id":"s6-681","number":681,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"لماذا تكرر: ﴿ومن أظلم ممن افترى على الله كذبًا﴾ بعد الآية 21؟","answer":"تكرر التركيب لأن الآية 21 قرنت الافتراء بتكذيب الآيات، أما هنا ففصلت صورًا جديدة من الافتراء: ادعاء الوحي وادعاء الإتيان بمثله، ثم صورت عاقبتها عند الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-682","number":682,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"لماذا عطف: ﴿أو قال أوحي إلي ولم يوح إليه شيء﴾ على الافتراء؟","answer":"العطف بـ﴿أو﴾ يفصل نوعًا خاصًا من الافتراء العام: أن يدعي الإنسان أن الوحي نزل عليه مع انتفائه. فهو داخل في الافتراء، لكنه أفرد لغلظ ادعاء النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-683","number":683,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"لماذا بُني ﴿أوحي﴾ و﴿يوح﴾ للمجهول؟","answer":"بُني الفعلان للمجهول لأن موضع الإنكار هو وقوع الوحي أو انتفاؤه، لا تعيين الموحي؛ فالفاعل معلوم وهو الله، وذكره لا يضيف إلى مقصد تكذيب المدعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-684","number":684,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"لماذا زيد ﴿شيء﴾ في ﴿ولم يوح إليه شيء﴾؟","answer":"زِيدت ﴿شيء﴾ في سياق النفي لتوكيد العموم؛ فلم يوح إليه شيء أصلًا، لا وحي كثير ولا قليل، وفي ذلك قطع لكل دعوى محتملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-685","number":685,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"ما دلالة نسبة المفتري الإنزال إلى نفسه في قوله: ﴿سأنزل مثل ما أنزل الله﴾؟","answer":"استعمل المفتري لفظ الإنزال ادعاء لمماثلة فعل الله والتعالي على القرآن؛ فهو يزعم أنه سيأتي بكلام منزل مثله، وفي العبارة كشف لعظم جرأته واستكباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-686","number":686,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"لماذا حُذف جواب ﴿لو﴾ في ﴿ولو ترى إذ الظالمون في غمرات الموت﴾؟","answer":"حُذف جواب ﴿لو﴾ لتهويل المشهد وترك النفس تقدر ما لا يحيط به وصف، وتقديره: لرأيت أمرًا عظيمًا أو فظيعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-687","number":687,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"لماذا صُورت شدائد الموت بـ﴿غمرات﴾ جمعًا؟","answer":"الغَمرة ما يغمر ويغطي، وجُمعت لتعدد شدائد الموت وسكراته وتتابعها؛ فصور الظالمين مغمورين بطبقات من الكرب لا بشدة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-688","number":688,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿والملائكة باسطو أيديهم﴾ بالاسم؟","answer":"اسم الفاعل ﴿باسطو﴾ يستحضر هيئة الملائكة ثابتة مستمرة وقت النزع، كأن المشهد قائم أمام السامع، وبسط الأيدي كناية عن الأخذ أو الضرب والتعذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-689","number":689,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"ما سرّ التعبير بقوله تعالى: لهم: ﴿أخرجوا أنفسكم﴾ مع أن إخراج الروح ليس بأيديهم؟","answer":"الأمر للتعنيف والإهانة والتعجيز: أخرجوا أرواحكم إن استطعتم، وهم لا يملكون ذلك؛ فتتجلى دعوى استقلالهم وعجزهم عند قبض الأرواح.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-690","number":690,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"لماذا اختير ﴿عذاب الهون﴾، لا: العذاب المهين؟","answer":"الهُون هو الذل والخزي؛ فـ﴿عذاب الهون﴾ عذاب ملازم للإهانة، يجمع ألم العقوبة وإذلال المستكبر، وهو أنسب بما قابلوا به آيات الله من استكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-691","number":691,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كنتم تقولون على الله غير الحق﴾، دون أن يقال: بالكذب؟","answer":"﴿غير الحق﴾ أعم من لفظ الكذب؛ فهو يشمل ادعاء الوحي ونسبة الكلام إلى الله وادعاء مماثلة تنزيله، ويقيم مقابلة بين كل قول باطل والحق الواجب في شأن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-692","number":692,"surah":6,"verses":[93],"verseLabel":"الأنعام: 93","question":"لماذا عطف الاستكبار عن الآيات على القول غير الحق؟","answer":"عطف الاستكبار لأنه سبب مستقل للعذاب غير الافتراء: الأول فساد في القول على الله، والثاني رفض عملي لقبول آياته. وتكرار ﴿كنتم﴾ يثبت استقلال كل سبب باستحقاق الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص396–424.","url":""}]},{"id":"s6-693","number":693,"surah":6,"verses":[94],"verseLabel":"الأنعام: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد جئتمونا فرادى﴾، مع أن الخلق يُحشرون جميعًا؟","answer":"مع أنهم مجموعون في المحشر، يجيئون فرادى من كل مال وولد ونصير، وكل نفس منفردة بتبعتها؛ فالجمع في المكان لا ينفي الانفراد عن أسباب الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–442.","url":""}]},{"id":"s6-694","number":694,"surah":6,"verses":[94],"verseLabel":"الأنعام: 94","question":"لماذا جُمعت ﴿فرادى﴾؟","answer":"﴿فرادى﴾ جمع لأن الخطاب لجماعة كبيرة، لكن أفرادها يأتون واحدًا واحدًا؛ فصيغة الجمع تجمع أحوال الانفراد المتكررة في كل شخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–442.","url":""}]},{"id":"s6-695","number":695,"surah":6,"verses":[94],"verseLabel":"الأنعام: 94","question":"لماذا شُبه الحشر بالخلق الأول: ﴿كما خلقناكم أول مرة﴾؟","answer":"التشبيه بالخلق الأول يثبت إمكان الإعادة، ويبين أنهم يعودون كما بدأوا منفردين مجردين مما اكتسبوه من مال وجاه وشركاء، فلا يبقى إلا العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–442.","url":""}]},{"id":"s6-696","number":696,"surah":6,"verses":[94],"verseLabel":"الأنعام: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿وتركتم ما خولناكم وراء ظهوركم﴾، فجعل النعم وراء الظهر؟","answer":"التعبير كناية عن مفارقة النعم مفارقةً تامة؛ فما كان محيطًا بهم وفي أيديهم صار متروكًا خلفهم لا يملكون الرجوع إليه ولا الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–442.","url":""}]},{"id":"s6-697","number":697,"surah":6,"verses":[94],"verseLabel":"الأنعام: 94","question":"لماذا اختير ﴿خولناكم﴾، لا: أعطيناكم؟","answer":"التخويل ليس مجرد العطاء؛ أصله إعطاء الشيء مع تمكين صاحبه منه وتعهده له، وفيه تذكير بأن المال والنعمة عارية خوّلهم الله إياها ثم فارقوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–442.","url":""}]},{"id":"s6-698","number":698,"surah":6,"verses":[94],"verseLabel":"الأنعام: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿وما نرى معكم شفعاءكم﴾ مع أن الله يعلم غيابهم؟","answer":"جيء بنفي الرؤية في مقام التهكم وإظهار خيبة زعمهم؛ فهؤلاء الذين ادعوا شفاعتهم لا أثر لهم في المشهد. والمضارع ﴿نرى﴾ يستحضر غيابهم ويجدّد تقريع المشركين به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–442.","url":""}]},{"id":"s6-699","number":699,"surah":6,"verses":[94],"verseLabel":"الأنعام: 94","question":"لماذا وصف الشفعاء بأنهم ﴿الذين زعمتم أنهم فيكم شركاء﴾؟","answer":"وصفهم بالصلة لفضح أصل الدعوى: لم تثبت لهم شركة، وإنما كان ذلك زعمًا من المشركين، و﴿فيكم﴾ تشير إلى ما ادعوه لهم من نصيب في شؤونهم وعبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–442.","url":""}]},{"id":"s6-700","number":700,"surah":6,"verses":[94],"verseLabel":"الأنعام: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد تقطع بينكم﴾، فجعل ما بينهم شيئًا يتقطع؟","answer":"صوّر الروابط التي توهموها شيئًا موصولًا ثم قُطع قطعًا شديدًا؛ فتبددت الصلات والأسباب بين العابدين ومعبوداتهم، وفي التشديد مبالغة في تمام الانقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–442.","url":""}]},{"id":"s6-701","number":701,"surah":6,"verses":[94],"verseLabel":"الأنعام: 94","question":"لماذا خُتم بقوله: ﴿وضل عنكم ما كنتم تزعمون﴾؟","answer":"الخاتمة تقرر مآل مزاعمهم: غاب عنهم كل ما كانوا يدّعونه من شفاعة وشركة، فكأن ذلك المزعوم ضل طريقه إليهم ولم يجدوه عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–442.","url":""}]},{"id":"s6-702","number":702,"surah":6,"verses":[95],"verseLabel":"الأنعام: 95","question":"لماذا وصف الله نفسه بـ﴿فالق الحب والنوى﴾، لا: خالق النبات؟","answer":"الفلق هو الشق الذي يظهر منه المكنون؛ فالتعبير يصوّر خروج النبات الحي من الحب والنوى الجامدين، ويجعل في المشهد المتكرر دليلًا محسوسًا على القدرة والإحياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–456.","url":""}]},{"id":"s6-703","number":703,"surah":6,"verses":[95],"verseLabel":"الأنعام: 95","question":"لماذا جمع بين ﴿الحب﴾ و﴿النوى﴾؟","answer":"الحب أصل الزروع، والنوى أصل كثير من الأشجار؛ فجمعهما ليستوعب نوعي النبات اللذين تقوم عليهما أقوات الناس وثمارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–456.","url":""}]},{"id":"s6-704","number":704,"surah":6,"verses":[95],"verseLabel":"الأنعام: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿يخرج الحي من الميت ومخرج الميت من الحي﴾، فعبّر مرة بالفعل ومرة بالاسم؟","answer":"قُرئ ﴿ومخرج﴾ اسم فاعل، فدلّ مع ﴿يخرج﴾ على تجدّد الفعل وثبوت الصفة لله. والجمع بين إخراج الحي من الميت وعكسه يستوعب وجهي القدرة على التحويل والإحياء والإماتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–456.","url":""}]},{"id":"s6-705","number":705,"surah":6,"verses":[95],"verseLabel":"الأنعام: 95","question":"ما سرّ تقديم إخراج الحي من الميت؟","answer":"قُدّم إخراج الحي من الميت لأنه الأنسب بما قبله من فلق الحب والنوى وخروج النبات منهما، ولأنه أوضح في الاستدلال على البعث الذي ينكره المخاطبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–456.","url":""}]},{"id":"s6-706","number":706,"surah":6,"verses":[95],"verseLabel":"الأنعام: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكم الله﴾ بعد عرض ظاهرة النبات؟","answer":"اسم الإشارة يلخّص الدليل ويعين صاحبه: الفاعل لهذه الخوارق المشاهدة هو الله وحده، وفي البعد تعظيم لشأنه ورفع لمنزلته عن الشركاء المزعومين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–456.","url":""}]},{"id":"s6-707","number":707,"surah":6,"verses":[95],"verseLabel":"الأنعام: 95","question":"لماذا خُتمت الآية بـ﴿فأنى تؤفكون﴾، ولم يقل: فلم تشركون؟","answer":"﴿تؤفكون﴾ تعني تُصرفون عن الحق؛ فهي لا تكتفي بإثبات وقوع الشرك، بل تعجّب من الجهة والحال التي صُرفوا بها عن عبادة من ظهرت دلائل قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–456.","url":""}]},{"id":"s6-708","number":708,"surah":6,"verses":[96],"verseLabel":"الأنعام: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿فالق الإصباح﴾، لا: خالق الصباح؟","answer":"الفلق شقّ الشيء بعد انضمامه؛ فصوّر انبثاق ضوء الصباح من ظلمة الليل كشقّ يكشف النور، ووصل هذا المشهد بفلق الحب والنوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص457–467.","url":""}]},{"id":"s6-709","number":709,"surah":6,"verses":[96],"verseLabel":"الأنعام: 96","question":"لماذا اختير ﴿الإصباح﴾، لا: الصبح؟","answer":"الإصباح مصدر يدل على حدوث الصبح ودخوله وتجدد انكشافه، فناسب مقام عرض الفعل الكوني المتكرر، بخلاف «الصبح» الذي يغلب فيه اسم الوقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص457–467.","url":""}]},{"id":"s6-710","number":710,"surah":6,"verses":[96],"verseLabel":"الأنعام: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿وجعل الليل سكنًا﴾، دون أن يقال: ساكنًا؟","answer":"﴿سكنًا﴾ مصدر يفيد أن الليل نفسه موطن سكون وراحة، لا مجرد زمن يوصف بالسكون؛ وفيه امتنان بما هيئ للخلق من انقطاع الحركة واستعادة القوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص457–467.","url":""}]},{"id":"s6-711","number":711,"surah":6,"verses":[96],"verseLabel":"الأنعام: 96","question":"لماذا عُدل من فعل ﴿فالق﴾ إلى ﴿جعل﴾؟","answer":"ناسب ﴿فالق﴾ ظهور الصباح بشق الظلمة، أما الليل فجاء فيه ﴿جعل﴾ لأنه جُعل على هيئة مخصوصة ووظيفة هي السكون، وكذلك سُخرت الشمس والقمر للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص457–467.","url":""}]},{"id":"s6-712","number":712,"surah":6,"verses":[96],"verseLabel":"الأنعام: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿والشمس والقمر حسبانًا﴾، فأفرد الخبر لاثنين؟","answer":"﴿حسبانًا﴾ مصدر بمعنى الحساب، فالإفراد راجع إلى الوظيفة الواحدة التي يشترك فيها الشمس والقمر: ضبط الأزمنة والحساب، لا إلى عدد المذكورين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص457–467.","url":""}]},{"id":"s6-713","number":713,"surah":6,"verses":[96],"verseLabel":"الأنعام: 96","question":"لماذا خُتمت الآية بـ﴿ذلك تقدير العزيز العليم﴾؟","answer":"﴿العزيز﴾ يناسب القدرة التي لا يعجزها ضبط هذه الأجرام، و﴿العليم﴾ يناسب إحكام مقاديرها ومساراتها؛ فالنظام الكوني تقدير صادر عن قوة وعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص457–467.","url":""}]},{"id":"s6-714","number":714,"surah":6,"verses":[97],"verseLabel":"الأنعام: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿جعل لكم النجوم﴾، فقدم منفعتها للناس؟","answer":"تقديم ﴿لكم﴾ يبرز الامتنان وتسخير النجوم لمصلحة الناس، ويهيئ لبيان منفعتها العملية في الاهتداء، مع بقاء سائر حكم خلقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص468–474.","url":""}]},{"id":"s6-715","number":715,"surah":6,"verses":[97],"verseLabel":"الأنعام: 97","question":"لماذا خُص الاهتداء بالنجوم في ﴿ظلمات البر والبحر﴾؟","answer":"خُص الاهتداء لأنه المنفعة الملائمة للسياق والمشاهدة، ولا سيما عند اشتباه الطرق في ظلمة البر والبحر؛ وليس في الآية حصر جميع منافع النجوم في ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص468–474.","url":""}]},{"id":"s6-716","number":716,"surah":6,"verses":[97],"verseLabel":"الأنعام: 97","question":"لماذا جُمعت ﴿ظلمات﴾ وقُدّم البر على البحر؟","answer":"جُمعت الظلمات لتعدد أسبابها وأحوالها وشدة التباس الطرق فيها، وقُدّم البر لأنه أقرب إلى خبرة المخاطبين وأكثر مباشرةً لهم، ثم عطف البحر استكمالًا لجهات السفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص468–474.","url":""}]},{"id":"s6-717","number":717,"surah":6,"verses":[97],"verseLabel":"الأنعام: 97","question":"لماذا خُتمت الآية بـ﴿لقوم يعلمون﴾؟","answer":"خُتمت بالعلم لأن الاهتداء بالنجوم يقوم على معرفة مواقعها ومساراتها ودلالتها على الجهات؛ فمن يعلم ذلك يدرك دقة هذا التسخير ودلالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص468–474.","url":""}]},{"id":"s6-718","number":718,"surah":6,"verses":[98],"verseLabel":"الأنعام: 98","question":"ما سرّ التعبير في قوله تعالى: ﴿أنشأكم من نفس واحدة﴾، لا: خلقكم؟","answer":"الإنشاء يدل على الإيجاد مع التربية والتنمية والانتقال في أطوار الخلق، وهو أنسب بتفصيل نشأة البشر من نفس واحدة ثم اختلاف مستقرهم ومستودعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص475–485.","url":""}]},{"id":"s6-719","number":719,"surah":6,"verses":[98],"verseLabel":"الأنعام: 98","question":"لماذا نُكّرت ﴿نفس﴾ ووُصفت بالوحدة؟","answer":"التنكير لإفراد أصل البشرية نفسًا واحدة غير متعددة، ووصفها بالوحدة يقرر وحدة المنشأ مع كثرة الذرية وتنوع أحوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص475–485.","url":""}]},{"id":"s6-720","number":720,"surah":6,"verses":[98],"verseLabel":"الأنعام: 98","question":"ما سرّ التعبير في قوله تعالى: ﴿فمستقر ومستودع﴾ من غير بيان صريح لما يستقر ويستودع؟","answer":"حُذف المتعلَّق ليعم وجوه الاستقرار والاستيداع التي ذكرها المفسرون: في الأصلاب والأرحام، أو في الحياة والقبر، أو في الأرض وما يودع فيها؛ فالإيجاز يتسع لهذه الأطوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص475–485.","url":""}]},{"id":"s6-721","number":721,"surah":6,"verses":[98],"verseLabel":"الأنعام: 98","question":"ما سرّ تقديم ﴿مستقر﴾ على ﴿مستودع﴾؟","answer":"قُدّم المستقر لأنه المقصود الذي ينتهي إليه الإنسان أو يثبت فيه، ثم ذُكر المستودع بوصفه مقامًا مؤقتًا يسبق ذلك أو ينتقل عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص475–485.","url":""}]},{"id":"s6-722","number":722,"surah":6,"verses":[98],"verseLabel":"الأنعام: 98","question":"لماذا خُتمت هنا بـ﴿لقوم يفقهون﴾، وفي آية النجوم ﴿لقوم يعلمون﴾؟","answer":"آية النجوم تتعلق بعلامات ظاهرة تُعرف بالمشاهدة والحساب فناسب ﴿يعلمون﴾؛ أما نشأة الإنسان وتقلبه بين المستقر والمستودع فتحتاج إلى تدبر أعمق في خفايا التكوين فناسب ﴿يفقهون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص475–485.","url":""}]},{"id":"s6-723","number":723,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿أنزل من السماء ماء﴾، دون أن يقال: المطر؟","answer":"الماء هو ذات النعمة وسبب الحياة والإنبات، أما المطر فاسم لحال نزوله؛ فذكر الماء أعلق بالأثر الذي ستفصله الآية في النبات والثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-724","number":724,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"لماذا تكرر الانتقال من الغيبة إلى التكلم: ﴿أنزل... فأخرجنا... نخرج﴾؟","answer":"بدأ بالغيبة موافقةً لما قبلها: ﴿وهو الذي﴾، ثم انتقل إلى ضمير التعظيم في ﴿فأخرجنا﴾ لإبراز العناية بالفعل وتعداد آثاره، واستمر المضارع ﴿نخرج﴾ لاستحضار تجدده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-725","number":725,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"كيف يخرج بالماء ﴿نبات كل شيء﴾؟","answer":"المعنى: أخرج بالماء نبات كل صنف مما ينبت، أو النبات الذي تتعلق به حاجات المخلوقات؛ فلا يراد أن كل موجود نبات، بل عموم أجناس النبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-726","number":726,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"لماذا وصف النبات بـ﴿خضرًا﴾؟","answer":"الخَضِر هو النبات الغضّ الأخضر الخارج أولًا، وذكره يصوّر طور الحياة والنماء الذي يتولد منه الحب والثمر بعد نزول الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-727","number":727,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿نخرج منه حبًّا متراكبًا﴾ بالمضارع؟","answer":"المضارع يستحضر أمام السامع عملية إخراج الحب من النبات متجددةً في كل موسم، بعد أن ذُكر أصل الإنزال والإخراج بالماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-728","number":728,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"لماذا وصف الحب بـ﴿متراكبًا﴾؟","answer":"﴿متراكبًا﴾ يصوّر حبات السنبل وقد ركب بعضها بعضًا في نظام محكم وكثرة ظاهرة؛ فيجمع المشهد بين وفرة الرزق ودقة الصنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-729","number":729,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن النخل من طلعها قنوان دانية﴾، وكرر ﴿من﴾؟","answer":"﴿من﴾ الأولى تبعيضية متعلقة بما يخرج من النبات أو مستأنفة لذكر صنف، والثانية لابتداء الغاية: من طلع النخل تخرج القنوان؛ فتكرارها يبين الأصل ثم موضع الخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-730","number":730,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"لماذا اختير لفظ ﴿قنوان﴾، ووُصفت بـ﴿دانية﴾؟","answer":"القنوان هي عذوق النخل الحاملة للتمر، ووصفت بالدنو لقربها وسهولة تناولها؛ فذكرها إدماج للامتنان بجمال الصنعة ومنفعة الثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-731","number":731,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير في قوله تعالى في الأعناب ﴿جنات﴾، ثم عطف الزيتون والرمان مفردين؟","answer":"عُبّر عن الأعناب بـ﴿جنات﴾ لأنها تنشأ في بساتين معروشة وتنتظم أشجارها، ثم عُطف الزيتون والرمان بوصفهما جنسين من الشجر والثمر لا على هيئة الجنات نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-732","number":732,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿مشتبهًا وغير متشابه﴾، فجمع بين الإثبات والنفي من مادة واحدة؟","answer":"الصيغتان متقاربتان؛ ﴿مشتبهًا﴾ و﴿متشابهًا﴾ تدلان على تقارب الثمار في بعض الصفات مع اختلافها في أخرى. وجاء الأخف بناءً أولًا، ثم الأثقل في الموضع اللاحق مراعاةً للترتيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-733","number":733,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"لماذا أمر بالنظر مرتين ضمنًا إلى ﴿ثمره إذا أثمر وينعه﴾؟","answer":"الأمر يتناول النظر إلى الثمر عند بدء ظهوره، ثم إلى ينعه ونضجه؛ لأن الانتقال من الضعف إلى الاكتمال آية أخرى تكشف التدبير والقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-734","number":734,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"لماذا أفرد ﴿ثمره﴾ مع تعدد الأنواع؟","answer":"أُفرد ﴿ثمره﴾ على إرادة الجنس، أي ثمر كل واحد من المذكورات، فالإفراد يوزع النظر على كل نوع ونبات دون حاجة إلى تكرار الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-735","number":735,"surah":6,"verses":[99],"verseLabel":"الأنعام: 99","question":"لماذا خُتمت الآية بـ﴿لقوم يؤمنون﴾ بعد ﴿يعلمون﴾ و﴿يفقهون﴾؟","answer":"تدرجت الخواتيم بحسب الأدلة: معرفة النجوم علم، وتدبر نشأة الإنسان فقه، والنظر في إحياء الأرض وتنوع الثمر يقود إلى التصديق بالمنعم والبعث؛ فناسب ﴿يؤمنون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–504.","url":""}]},{"id":"s6-736","number":736,"surah":6,"verses":[99,141],"verseLabel":"الأنعام: 99، 141","question":"ما سرّ التعبير في قوله تعالى في الآية 99: ﴿مشتبهًا وغير متشابه﴾، وفي الآية 141: ﴿متشابهًا وغير متشابه﴾؟","answer":"الصيغتان عند المصدر متقاربتان في المعنى؛ فجاء ﴿مشتبهًا﴾، وهو أخف بناءً، في الموضع الأول، ثم ﴿متشابهًا﴾، وهو أثقل، في الموضع المتأخر مراعاةً للترتيب من الأخف إلى الأثقل.","sources":[{"label":"الويب: إسلام ويب، «متشابهًا وغير متشابه»، 2024.","url":""}]},{"id":"s6-737","number":737,"surah":6,"verses":[99,141],"verseLabel":"الأنعام: 99، 141","question":"ما سرّ التعبير في قوله تعالى في الآية 99: ﴿انظروا إلى ثمره﴾، وفي الآية 141: ﴿كلوا من ثمره﴾ مع تشابه المذكورات؟","answer":"آية 99 في سياق نصب دلائل الوحدانية والقدرة، فناسبها الأمر بالنظر والاعتبار. وآية 141 في سياق إبطال تحريم الأطعمة وبيان أحكامها وحقها، فناسبها ﴿كلوا﴾ و﴿آتوا حقه﴾.","sources":[{"label":"الويب: إسلام ويب، «متشابهًا وغير متشابه»، 2024.","url":""}]},{"id":"s6-738","number":738,"surah":6,"verses":[100],"verseLabel":"الأنعام: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿وجعلوا لله شركاء الجن﴾، وما موقع ﴿الجن﴾ من التركيب؟","answer":"﴿الجن﴾ مفعول أول مؤخر، و﴿شركاء﴾ مفعول ثان مقدم؛ والأصل: جعلوا الجن شركاء لله. وتقديم ﴿شركاء﴾ يعجل بالتشنيع على أصل الشرك، ثم يكشف أن المجعولين شركاء هم الجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص505–515.","url":""}]},{"id":"s6-739","number":739,"surah":6,"verses":[100],"verseLabel":"الأنعام: 100","question":"ما سرّ تقديم ﴿لله﴾ على ﴿شركاء﴾؟","answer":"قُدّم ﴿لله﴾ للاهتمام بمن جُعل له الشريك ولزيادة التشنيع؛ إذ يظهر من أول التركيب أنهم سوّوا مخلوقًا بالله الذي انفرد بالخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص505–515.","url":""}]},{"id":"s6-740","number":740,"surah":6,"verses":[100],"verseLabel":"الأنعام: 100","question":"ما دلالة مجيء قوله تعالى: ﴿وخلقهم﴾ عقب اتخاذهم الجن شركاء؟","answer":"جملة ﴿وخلقهم﴾ حال أو اعتراض يقرر التناقض: جعلوا الجن شركاء لله مع أن الله خالقهم وخالق من عبدهم، والمخلوق لا يكون شريكًا لخالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص505–515.","url":""}]},{"id":"s6-741","number":741,"surah":6,"verses":[100],"verseLabel":"الأنعام: 100","question":"لماذا اختير ﴿خرقوا له بنين وبنات﴾، لا: زعموا؟","answer":"﴿خرقوا﴾ تدل على اختلاق الكذب وافتعاله بجرأة، وفي صيغة التفعيل مبالغة؛ فهي أبلغ من مجرد الزعم في تصوير افترائهم نسبة البنين والبنات إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص505–515.","url":""}]},{"id":"s6-742","number":742,"surah":6,"verses":[100],"verseLabel":"الأنعام: 100","question":"لماذا جُمِع البنون والبنات في سياق واحد؟","answer":"جُمع الصنفان لاستيعاب أباطيل الطوائف: من نسبوا إليه البنين ومن نسبوا إليه البنات، فجاء الرد شاملًا لكل دعوى ولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص505–515.","url":""}]},{"id":"s6-743","number":743,"surah":6,"verses":[100],"verseLabel":"الأنعام: 100","question":"لماذا قُيّد الافتراء بـ﴿بغير علم﴾؟","answer":"﴿بغير علم﴾ تفضح أن دعواهم لا تقوم على وحي ولا برهان، بل هي خرق وافتراء محض، وتزيد تقبيح القول في الله بلا علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص505–515.","url":""}]},{"id":"s6-744","number":744,"surah":6,"verses":[100],"verseLabel":"الأنعام: 100","question":"لماذا جمع بين ﴿سبحانه وتعالى﴾؟","answer":"﴿سبحانه﴾ تنزيه له عن أصل النقص والشريك والولد، و﴿تعالى﴾ إثبات لعلوه وارتفاعه عن كل ما يصفونه؛ فجمع النفي عن الباطل وإثبات كمال العلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص505–515.","url":""}]},{"id":"s6-745","number":745,"surah":6,"verses":[100],"verseLabel":"الأنعام: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿عما يصفون﴾، دون أن يقال: عما يقولون؟","answer":"الوصف أثبت وأبلغ من القول العابر؛ فهو يدل على أنهم جعلوا تلك الدعاوى صفات ينسبونها إلى الله، فجاء التنزيه عما يثبتونه له من أوصاف باطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص505–515.","url":""}]},{"id":"s6-746","number":746,"surah":6,"verses":[101],"verseLabel":"الأنعام: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿بديع السماوات والأرض﴾، لا: خالقهما؟","answer":"البديع هو المنشئ على غير مثال سابق ومن غير أصل يحتذيه؛ فالوصف أبلغ في نفي الولد، لأن من أبدع السماوات والأرض لا يحتاج إلى تولد أو معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص516–523.","url":""}]},{"id":"s6-747","number":747,"surah":6,"verses":[101],"verseLabel":"الأنعام: 101","question":"لماذا جاء نفي الولد في صورة سؤال: ﴿أنى يكون له ولد﴾؟","answer":"﴿أنى﴾ استفهام إنكاري تعجبي ينفي كل وجه يمكن أن يتوهم لوجود الولد؛ كيف ومن أين يكون له ولد وهو بديع الخلق ولم تكن له صاحبة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص516–523.","url":""}]},{"id":"s6-748","number":748,"surah":6,"verses":[101],"verseLabel":"الأنعام: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿ولم تكن له صاحبة﴾، لا: زوجة؟","answer":"الصاحبة هي الملازمة المصاحبة، واللفظ أنسب بمقام نفي كل مماثل أو قرين لله، وهو يشمل نفي الزوجة من أصلها لا مجرد عقد الزوجية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص516–523.","url":""}]},{"id":"s6-749","number":749,"surah":6,"verses":[101],"verseLabel":"الأنعام: 101","question":"لماذا عطف ﴿وخلق كل شيء﴾ على نفي الصاحبة والولد؟","answer":"عطف ﴿وخلق كل شيء﴾ برهانًا جامعًا: كل ما سواه مخلوق له، والولد لو وُجد لكان من جملة الخلق، فلا يصح أن يكون جزءًا من الخالق أو شريكًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص516–523.","url":""}]},{"id":"s6-750","number":750,"surah":6,"verses":[101],"verseLabel":"الأنعام: 101","question":"لماذا خُتمت الآية بـ﴿وهو بكل شيء عليم﴾؟","answer":"العلم بكل شيء يثبت كمال تدبيره واستغناءه، وينفي لوازم الولد من الحاجة إلى معين أو امتداد؛ فالذي أحاط علمه بكل خلقه لا يخفى عليه شيء ولا يحتاج إلى صاحبة أو ولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص516–523.","url":""}]},{"id":"s6-751","number":751,"surah":6,"verses":[102],"verseLabel":"الأنعام: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكم الله ربكم﴾ باسم الإشارة للبعيد؟","answer":"الإشارة للبعيد للتعظيم، وتعود إلى الموصوف بالخلق والإبداع والعلم في الآيات السابقة؛ أي ذلك المتفرد بهذه الصفات العظيمة هو الله ربكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص524–532.","url":""}]},{"id":"s6-752","number":752,"surah":6,"verses":[102],"verseLabel":"الأنعام: 102","question":"لماذا جمع بين ﴿الله﴾ و﴿ربكم﴾ و﴿خالق كل شيء﴾؟","answer":"﴿الله﴾ علم على المعبود الحق، و﴿ربكم﴾ يقرر رعايته وتدبيره لكم، و﴿خالق كل شيء﴾ يقيم برهان انفراده؛ فاجتمعت الألوهية والربوبية والخلق لإبطال الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص524–532.","url":""}]},{"id":"s6-753","number":753,"surah":6,"verses":[102],"verseLabel":"الأنعام: 102","question":"لماذا فُرعت العبادة بالفاء: ﴿فاعبدوه﴾؟","answer":"الفاء تفيد أن العبادة نتيجة لازمة لما ثبت من وحدانيته وربوبيته وخلقه كل شيء؛ فمن كان كذلك استحق أن يعبد وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص524–532.","url":""}]},{"id":"s6-754","number":754,"surah":6,"verses":[102],"verseLabel":"الأنعام: 102","question":"لماذا خُتمت الآية بـ﴿وهو على كل شيء وكيل﴾، لا: قدير؟","answer":"الوكيل هو القائم على الأشياء حفظًا وتدبيرًا ورعايةً، وهو الأنسب بعد ذكر الربوبية والخلق والأمر بالعبادة؛ أما القدرة وحدها فلا تؤدي معنى استمرار القيام على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص524–532.","url":""}]},{"id":"s6-755","number":755,"surah":6,"verses":[103],"verseLabel":"الأنعام: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تدركه الأبصار﴾، دون أن يقال: لا تراه العيون؟","answer":"الإدراك هو بلوغ الشيء والإحاطة به، وهو أخص من مطلق الرؤية؛ فنفت الآية إحاطة الأبصار بالله، وقابلتها بإحاطته بكل بصر، ولا يلزم من ذلك نفي رؤيته في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص533–541.","url":""}]},{"id":"s6-756","number":756,"surah":6,"verses":[103],"verseLabel":"الأنعام: 103","question":"لماذا جُمعت ﴿الأبصار﴾؟","answer":"جُمعت الأبصار لاستغراق أبصار الخلق كلها؛ فلا يحيط به بصر مهما تعدد أصحابه أو اختلفت قواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص533–541.","url":""}]},{"id":"s6-757","number":757,"surah":6,"verses":[103],"verseLabel":"الأنعام: 103","question":"لماذا قابل نفي إدراك الأبصار له بقوله: ﴿وهو يدرك الأبصار﴾؟","answer":"المقابلة تظهر انفراده بكمال العلم والإحاطة: أبصار الخلق تقصر عن الإحاطة به، وهو يحيط بها وبأصحابها وبما تبصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص533–541.","url":""}]},{"id":"s6-758","number":758,"surah":6,"verses":[103],"verseLabel":"الأنعام: 103","question":"لماذا خُتمت الآية بـ﴿وهو اللطيف الخبير﴾؟","answer":"﴿اللطيف﴾ يناسب خفاء ذاته عن إحاطة الأبصار ودقة نفاذ علمه، و﴿الخبير﴾ يناسب إحاطته ببواطن الأشياء ودقائقها؛ فختمت الآية بما يعلل طرفيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص533–541.","url":""}]},{"id":"s6-759","number":759,"surah":6,"verses":[104],"verseLabel":"الأنعام: 104","question":"لماذا سمّى دلائل القرآن ﴿بصائر﴾ لا أبصارًا؟","answer":"البصائر جمع بصيرة، وهي الحجج والهدايات التي تُبصر بها القلوب مواقع الحق؛ فالمقصود إدراك القلب لا مجرد رؤية العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص541–553.","url":""}]},{"id":"s6-760","number":760,"surah":6,"verses":[104],"verseLabel":"الأنعام: 104","question":"لماذا جُمعت ﴿بصائر﴾ مع وحدة القرآن؟","answer":"جُمعت لتعدد الآيات والحجج ووجوه الدلالة التي جاء بها القرآن، وإن كان الكتاب واحدًا؛ فكل حجة بصيرة تهدي إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص541–553.","url":""}]},{"id":"s6-761","number":761,"surah":6,"verses":[104],"verseLabel":"الأنعام: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن أبصر فلنفسه ومن عمي فعليها﴾؟","answer":"جعل قبول الحجة إبصارًا والإعراض عنها عمًى؛ فمن انتفع بالبصائر عاد نفعه إلى نفسه، ومن أعرض حمل وحده ضرر عماه، وفي المقابلة تصوير وتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص541–553.","url":""}]},{"id":"s6-762","number":762,"surah":6,"verses":[104],"verseLabel":"الأنعام: 104","question":"لماذا عُدّيت منفعة الإبصار باللام وضرر العمى بـ﴿على﴾؟","answer":"اللام في ﴿فلنفسه﴾ للاختصاص والنفع، و﴿على﴾ في ﴿فعليها﴾ للاستعلاء المجازي والضرر؛ فكأن تبعة العمى حمل واقع عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص541–553.","url":""}]},{"id":"s6-763","number":763,"surah":6,"verses":[104],"verseLabel":"الأنعام: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أنا عليكم بحفيظ﴾؟","answer":"المعنى أن مهمة الرسول البلاغ والبيان، وليس موكلًا بحفظ أعمالهم أو إجبارهم على الهدى أو تحمل تبعتهم؛ ولذلك أعقب مسؤولية كل نفس عن اختيارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص541–553.","url":""}]},{"id":"s6-764","number":764,"surah":6,"verses":[105],"verseLabel":"الأنعام: 105","question":"لماذا تكرر قوله: ﴿وكذلك نصرف الآيات﴾؟","answer":"التصريف هو تنويع عرض الآيات والحجج من وجوه مختلفة. وتكرر المعنى هنا لأنه انتقل من دلائل التوحيد السابقة إلى بيان موقف المتلقين المتباين منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص554–567.","url":""}]},{"id":"s6-765","number":765,"surah":6,"verses":[105],"verseLabel":"الأنعام: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿وليقولوا درست﴾، فجعل قول المعاندين غاية لتصريف الآيات؟","answer":"اللام للعاقبة لا لأن قولهم غرض محبوب؛ فتصريف الآيات يؤدي، مع عنادهم، إلى أن يقولوا ﴿درست﴾، بينما يؤدي عند أهل العلم إلى البيان والهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص554–567.","url":""}]},{"id":"s6-766","number":766,"surah":6,"verses":[105],"verseLabel":"الأنعام: 105","question":"لماذا اختيرت كلمة ﴿درست﴾، وما وجوه قراءتها؟","answer":"على قراءة ﴿درست﴾ قالوا: تعلمت من أهل الكتاب؛ وقُرئت ﴿دارست﴾ أي ذاكرت غيرك، و﴿دَرَسَت﴾ أي قدمت وتكررت. وتعدد القراءات يكشف وجوه تهمهم للوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص554–567.","url":""}]},{"id":"s6-767","number":767,"surah":6,"verses":[105],"verseLabel":"الأنعام: 105","question":"لماذا قابل قولهم ﴿درست﴾ بقوله: ﴿ولنبينه لقوم يعلمون﴾؟","answer":"قابل اتهام المعاندين للرسول بأنه درس بما هو حقيقة التصريف: أن الله يبين الآيات لقوم يعلمون؛ فالمادة الواحدة تصير عند العناد شبهة، وعند العلم بيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص554–567.","url":""}]},{"id":"s6-768","number":768,"surah":6,"verses":[106],"verseLabel":"الأنعام: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿اتبع ما أوحي إليك﴾، دون أن يقال: اتبع القرآن؟","answer":"الوحي أعم من اسم القرآن من جهة ما يبلغه الله لنبيه، وفي التعبير تأكيد مصدر التكليف ووجوب اتباع كل ما أوحاه ربه، لا التعامل معه بوصفه كلامًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص568–576.","url":""}]},{"id":"s6-769","number":769,"surah":6,"verses":[106],"verseLabel":"الأنعام: 106","question":"لماذا كرر التوحيد: ﴿لا إله إلا هو﴾ بين الأمرين؟","answer":"جاء التوحيد بين الأمر باتباع الوحي والإعراض عن المشركين تعليلًا للأمرين: لأن المعبود واحد، فيتبع وحيه وحده ولا يلتفت إلى شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص568–576.","url":""}]},{"id":"s6-770","number":770,"surah":6,"verses":[106],"verseLabel":"الأنعام: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿وأعرض عن المشركين﴾ بعد الأمر باتباع الوحي؟","answer":"الإعراض هنا ترك الالتفات إلى عنادهم ومطالبهم التعنتية بعد البيان، لا ترك دعوتهم؛ فهو يثبت الرسول على الوحي ولا يجعله تابعًا لأهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص568–576.","url":""}]},{"id":"s6-771","number":771,"surah":6,"verses":[107],"verseLabel":"الأنعام: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو شاء الله ما أشركوا﴾ مع محاسبته لهم على الشرك؟","answer":"المعنى أن الله قادر على منع الشرك لو شاء أن يخلقهم مجبرين على الإيمان، لكنه شاء التكليف والاختيار؛ فشركهم واقع باختيارهم تحت مشيئته الكونية ولا يسقط مسؤوليتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص577–584.","url":""}]},{"id":"s6-772","number":772,"surah":6,"verses":[107],"verseLabel":"الأنعام: 107","question":"لماذا نُفي عن النبي أولًا أن يكون ﴿حفيظًا﴾ ثم ﴿وكيلًا﴾؟","answer":"الحفيظ يراقب الأعمال ويحفظ أصحابها من المخالفة، والوكيل يتولى شؤونهم ويتصرف عنهم؛ فنُفيت عن الرسول الوظيفتان لبيان أن عليه البلاغ لا الإكراه ولا ضمان النتائج.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص577–584.","url":""}]},{"id":"s6-773","number":773,"surah":6,"verses":[107],"verseLabel":"الأنعام: 107","question":"لماذا تكرر ﴿عليهم﴾ في الجملتين؟","answer":"تكرار ﴿عليهم﴾ يثبت استقلال النفيين ويقوي تعلق كل من الحفظ والوكالة بالمشركين؛ فلا هو حفيظ عليهم، ولا هو وكيل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص577–584.","url":""}]},{"id":"s6-774","number":774,"surah":6,"verses":[108],"verseLabel":"الأنعام: 108","question":"لماذا نهى القرآن عن سب معبودات المشركين مع بطلانها؟","answer":"نُهي المسلمون لأن سب المعبودات يفضي إلى مفسدة أعظم هي سب الله بجهل وعدوان؛ فالآية تؤصل ترك الوسيلة المباحة أو المحتملة إذا جرّت إلى محرم أكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص585–604.","url":""}]},{"id":"s6-775","number":775,"surah":6,"verses":[108],"verseLabel":"الأنعام: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين يدعون من دون الله﴾، فعبر عن المعبودات بـ﴿الذين﴾؟","answer":"عُبر بـ﴿الذين﴾ على طريقة المشركين الذين عاملوها معاملة العقلاء وعبدوها، أو لأن المدعوين يشملون من يعقل كالملائكة والجن؛ وفيه مجاراة للخطاب دون إقرار بألوهيتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص585–604.","url":""}]},{"id":"s6-776","number":776,"surah":6,"verses":[108],"verseLabel":"الأنعام: 108","question":"لماذا كانت النتيجة: ﴿فيسبوا الله عدوًا بغير علم﴾؟","answer":"الفاء تبين سرعة ترتب المفسدة على السبب: إذا سُبت معبوداتهم حملهم التعصب والجهل على مقابلة السب بسب الله، فالنهي يسد هذا الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص585–604.","url":""}]},{"id":"s6-777","number":777,"surah":6,"verses":[108],"verseLabel":"الأنعام: 108","question":"لماذا اختير ﴿عدوًا﴾، لا: ظلمًا؟","answer":"العَدْو هو تجاوز الحد مع القصد والجرأة، فاختير لأنه يصور تعديهم إلى مقام الله بالسب، أما الظلم فأعم ولا يبرز معنى المجاوزة نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص585–604.","url":""}]},{"id":"s6-778","number":778,"surah":6,"verses":[108],"verseLabel":"الأنعام: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿كذلك زينا لكل أمة عملهم﴾، وأسند التزيين إلى الله؟","answer":"التزيين هنا جريان سنة الله في أن تستحسن كل أمة ما ألفته واختارته، أو جزاء الضالين بتركهم لما زينوه لأنفسهم؛ وليس معناه أن الله أمرهم بالباطل أو رضيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص585–604.","url":""}]},{"id":"s6-779","number":779,"surah":6,"verses":[108],"verseLabel":"الأنعام: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم إلى ربهم مرجعهم﴾ بتقديم ﴿إلى ربهم﴾؟","answer":"تقديم ﴿إلى ربهم﴾ يفيد الاختصاص والتهديد: لا مرجع لهم في النهاية إلا إلى ربهم الذي يعلم أعمالهم ويحكم بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص585–604.","url":""}]},{"id":"s6-780","number":780,"surah":6,"verses":[108],"verseLabel":"الأنعام: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿فينبئهم بما كانوا يعملون﴾ بعد رجوعهم؟","answer":"الإنباء ليس مجرد الإخبار، بل إخبار يظهر حقيقة أعمالهم ونتائجها عند الحساب؛ فبعد الرجوع يكشف لهم ما خفي عليهم من قبحها ويجازيهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص585–604.","url":""}]},{"id":"s6-781","number":781,"surah":6,"verses":[109],"verseLabel":"الأنعام: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿وأقسموا بالله جهد أيمانهم﴾، وما صورة بذل الجهد في اليمين؟","answer":"الجهد غاية الطاقة والمبالغة؛ أي بالغوا في توكيد أيمانهم حتى بذلوا أقصى ما يعرفونه من الحلف، مع أن امتناعهم لم يكن لنقص الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص605–618.","url":""}]},{"id":"s6-782","number":782,"surah":6,"verses":[109],"verseLabel":"الأنعام: 109","question":"لماذا أكدوا: ﴿لئن جاءتهم آية ليؤمنن بها﴾ مع علم الله بكذبهم؟","answer":"التوكيد يصور شدة ادعائهم واستعدادهم الظاهر للإيمان، ثم يكشف السياق كذب هذا الادعاء؛ فالعائق عن الإيمان عناد القلب لا غياب الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص605–618.","url":""}]},{"id":"s6-783","number":783,"surah":6,"verses":[109],"verseLabel":"الأنعام: 109","question":"لماذا جاء الرد: ﴿إنما الآيات عند الله﴾؟","answer":"القصر بـ﴿إنما﴾ يرد طلبهم إلى صاحبه: إنزال الآيات الخارقة ليس بيد الرسول، وإنما هو عند الله ينزلها وفق حكمته لا وفق اقتراح المعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص605–618.","url":""}]},{"id":"s6-784","number":784,"surah":6,"verses":[109],"verseLabel":"الأنعام: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يشعركم﴾، دون أن يقال: وما يعلمكم؟","answer":"الإشعار إدراك دقيق قد يكون من أمارة خفية؛ فنفى أن يكون عند المخاطبين حتى ما يشعرهم بأن الآية المقترحة ستثمر إيمانهم، فضلًا عن العلم بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص605–618.","url":""}]},{"id":"s6-785","number":785,"surah":6,"verses":[109],"verseLabel":"الأنعام: 109","question":"ما دلالة التركيب المحتمل في قوله تعالى: ﴿أنها إذا جاءت لا يؤمنون﴾؟","answer":"التركيب يحتمل خطاب المؤمنين: وما يدريكم أنها إذا جاءت لا يؤمنون، ويحتمل قراءة الفتح بمعنى لعلها إذا جاءت لا يؤمنون. وهذا الاحتمال يلائم التردد الذي أراد السياق قطعه عن جدوى اقتراحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص605–618.","url":""}]},{"id":"s6-786","number":786,"surah":6,"verses":[110],"verseLabel":"الأنعام: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ونقلب أفئدتهم وأبصارهم﴾، فجعل القلب والبصر يقلبان؟","answer":"التقليب تحويل الشيء عن وجهه؛ فصور اضطراب قلوبهم وأبصارهم وصرفها عن الانتفاع بالحق، جزاءً على رفضهم الإيمان أول مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص619–631.","url":""}]},{"id":"s6-787","number":787,"surah":6,"verses":[110],"verseLabel":"الأنعام: 110","question":"ما سرّ تقديم الأفئدة على الأبصار؟","answer":"قُدّمت الأفئدة لأنها محل الفهم والقصد والتصديق، ثم الأبصار لأنها طريق مشاهدة الآيات؛ ففساد الباطن أصلٌ في عدم الانتفاع بالمشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص619–631.","url":""}]},{"id":"s6-788","number":788,"surah":6,"verses":[110],"verseLabel":"الأنعام: 110","question":"إلى ماذا يعود الضمير في ﴿كما لم يؤمنوا به أول مرة﴾؟","answer":"الضمير في ﴿به﴾ يعود إلى القرآن أو الرسول، وقيل إلى ما طلبوه من الآيات؛ ويجمع الوجوه أنهم لم يؤمنوا بالدليل حين جاءهم أول مرة، فكان ذلك سبب حرمانهم الانتفاع بما بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص619–631.","url":""}]},{"id":"s6-789","number":789,"surah":6,"verses":[110],"verseLabel":"الأنعام: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ونذرهم في طغيانهم يعمهون﴾، فجعل الطغيان ظرفًا؟","answer":"جُعل الطغيان ظرفًا محيطًا بهم لتصوير استغراقهم فيه، فهم متروكون داخله يتحيرون لا يهتدون إلى مخرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص619–631.","url":""}]},{"id":"s6-790","number":790,"surah":6,"verses":[110],"verseLabel":"الأنعام: 110","question":"لماذا اختير ﴿يعمهون﴾، لا: يضلون؟","answer":"العمه تحير واضطراب مع عمى القلب، فهو أدق من مطلق الضلال؛ إذ يصور من يتردد في طغيانه لا يبصر وجه الصواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص619–631.","url":""}]},{"id":"s6-791","number":791,"surah":6,"verses":[111],"verseLabel":"الأنعام: 111","question":"لماذا افترض نزول الملائكة وكلام الموتى وحشر كل شيء معًا؟","answer":"جُمعت أقصى المقترحات: نزول الملائكة، وكلام الموتى، ومواجهة المحشورات؛ للمبالغة في بيان أن العناد المستحكم لا يزول حتى لو أحاطت بهم الآيات من كل جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص632–651.","url":""}]},{"id":"s6-792","number":792,"surah":6,"verses":[111],"verseLabel":"الأنعام: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿نزلنا إليهم الملائكة﴾ بتشديد الفعل؟","answer":"التشديد في ﴿نزّلنا﴾ يفيد التكثير أو التدرج؛ أي لو أنزلت الملائكة إنزالًا ظاهرًا متكررًا كما اقترحوا، لما حملهم ذلك على الإيمان مع عنادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص632–651.","url":""}]},{"id":"s6-793","number":793,"surah":6,"verses":[111],"verseLabel":"الأنعام: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿وكلمهم الموتى﴾، لا: وأحيا لهم الموتى؟","answer":"ذكر كلام الموتى أبلغ في إقامة الحجة من مجرد إحيائهم؛ لأنه يحقق ما طلبوه من شهادة الموتى لهم بصدق الرسول ومشافهتهم بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص632–651.","url":""}]},{"id":"s6-794","number":794,"surah":6,"verses":[111],"verseLabel":"الأنعام: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿وحشرنا عليهم كل شيء قبلًا﴾، وما معنى ﴿قبلًا﴾؟","answer":"﴿حشرنا عليهم﴾ يصور جمع كل شيء في مواجهتهم وإحاطته بهم لإقامة الحجة. و﴿قُبُلًا﴾ بضم القاف والباء تحتمل: مقابلةً ومعاينة، أو جماعات، أو كفلاء؛ وقرئت ﴿قِبَلًا﴾ أي عيانًا ومقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص632–651؛ باحث، تفريغ د. فاضل السامرائي: «وحشرنا عليهم كل شيء قبلًا».","url":""}]},{"id":"s6-795","number":795,"surah":6,"verses":[111],"verseLabel":"الأنعام: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كانوا ليؤمنوا﴾ باللام؟","answer":"لام الجحود بعد ﴿ما كانوا﴾ تفيد شدة انتفاء الإيمان وعدم استقامتِه منهم مع رسوخ العناد؛ أي لم يكن من شأنهم أن يؤمنوا بهذه المقترحات إلا أن يشاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص632–651.","url":""}]},{"id":"s6-796","number":796,"surah":6,"verses":[111],"verseLabel":"الأنعام: 111","question":"لماذا استثنى: ﴿إلا أن يشاء الله﴾؟","answer":"الاستثناء يرد الأمر كله إلى مشيئة الله النافذة؛ فنفي إيمانهم معلق بحال عنادهم، ولا يعجز الله أن يخلق الإيمان فيهم أو يوفق من يشاء منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص632–651.","url":""}]},{"id":"s6-797","number":797,"surah":6,"verses":[111],"verseLabel":"الأنعام: 111","question":"لماذا خُتمت بـ﴿ولكن أكثرهم يجهلون﴾، لا يعلمون؟","answer":"الجهل هنا ليس مجرد فقد المعلومة، بل سوء إدراكهم سنن الهداية واعتقادهم أن الآيات المقترحة تلزمهم بالإيمان؛ فناسب وصفهم بالجهل الذي أوقعهم في هذا التوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص632–651.","url":""}]},{"id":"s6-798","number":798,"surah":6,"verses":[112],"verseLabel":"الأنعام: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك جعلنا لكل نبي عدوًا﴾، وأسند جعل العدو إلى الله؟","answer":"الجعل هنا جارٍ على سنة الابتلاء؛ فقد قضت حكمة الله أن يكون لكل نبي أعداء ليتميز الحق ويعظم أجر الدعاة، ولا يعني أنه أحب عداوتهم أو أجبرهم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص652–670.","url":""}]},{"id":"s6-799","number":799,"surah":6,"verses":[112],"verseLabel":"الأنعام: 112","question":"لماذا أُفرد ﴿عدوًا﴾ ثم بُيّن بجمع ﴿شياطين الإنس والجن﴾؟","answer":"أُفرد ﴿عدوًا﴾ لأنه اسم جنس يشمل جماعة الأعداء أو لاتحادهم في العداوة، ثم بينت الجملة أن هذا الجنس يتكون من شياطين الإنس والجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص652–670.","url":""}]},{"id":"s6-800","number":800,"surah":6,"verses":[112],"verseLabel":"الأنعام: 112","question":"ما سرّ تقديم شياطين الإنس على الجن؟","answer":"قُدّم شياطين الإنس لأن عداوتهم أشد ظهورًا ومباشرةً للرسل، ولأن السياق يتحدث عن مجرمي البشر الذين يصدون عن الدعوة، ثم أُلحق بهم شياطين الجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص652–670.","url":""}]},{"id":"s6-801","number":801,"surah":6,"verses":[112],"verseLabel":"الأنعام: 112","question":"لماذا عبّر عن تواصلهم بقوله: ﴿يوحي بعضهم إلى بعض﴾؟","answer":"الوحي إلقاء خفي سريع؛ فاستعير لتناقلهم الباطل سرًا، بعضهم يمد بعضًا بوسائل التضليل كما يوحى الكلام الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص652–670.","url":""}]},{"id":"s6-802","number":802,"surah":6,"verses":[112],"verseLabel":"الأنعام: 112","question":"لماذا سُمي باطلهم ﴿زخرف القول﴾؟","answer":"الزخرف هو الزينة الظاهرة؛ فسمي قولهم زخرفًا لأنه مزين الأسلوب يخفي باطل المعنى، فيغتر به من لا ينفذ إلى حقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص652–670.","url":""}]},{"id":"s6-803","number":803,"surah":6,"verses":[112],"verseLabel":"الأنعام: 112","question":"لماذا نُصب ﴿غرورًا﴾ بعد زخرف القول؟","answer":"﴿غرورًا﴾ منصوب على أنه مفعول لأجله، أي يوحي بعضهم إلى بعض ليغروا الناس، أو حال من زخرف القول؛ وفي الوجهين يكشف الغاية من تزيين الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص652–670.","url":""}]},{"id":"s6-804","number":804,"surah":6,"verses":[112],"verseLabel":"الأنعام: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو شاء ربك ما فعلوه﴾ باسم الرب؟","answer":"ذكر ﴿ربك﴾ تسلية للرسول: الذي يربيه ويحفظ دعوته قادر على منع أعدائه، لكنه أمهلهم لحكمة الابتلاء؛ فلا يضيق صدره بأذاهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص652–670.","url":""}]},{"id":"s6-805","number":805,"surah":6,"verses":[112],"verseLabel":"الأنعام: 112","question":"لماذا جمع: ﴿فذرهم وما يفترون﴾؟","answer":"المعنى: اتركهم واترك ما يفترونه إلى جزاء الله بعد إقامة الحجة؛ فالجمع بين ذواتهم وافترائهم تهديد لهم وللباطل الذي يصنعونه، لا أمر بترك البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص652–670.","url":""}]},{"id":"s6-806","number":806,"surah":6,"verses":[113],"verseLabel":"الأنعام: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتصغى إليه أفئدة﴾، فصوّر القلوب تميل؟","answer":"أصل الصغو الميل؛ فصوّر القلوب مائلة نحو زخرف القول لاستحسانه وقبوله، وفي الصورة كشف لانحرافها عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص671–682.","url":""}]},{"id":"s6-807","number":807,"surah":6,"verses":[113],"verseLabel":"الأنعام: 113","question":"لماذا اختيرت ﴿الأفئدة﴾، لا: القلوب؟","answer":"الأفئدة جمع فؤاد، وهو القلب حين يتقد ويتأثر؛ فناسب مقام الانجذاب إلى القول المزخرف وما يصاحبه من رغبة وهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص671–682.","url":""}]},{"id":"s6-808","number":808,"surah":6,"verses":[113],"verseLabel":"الأنعام: 113","question":"لماذا قُيدوا بـ﴿الذين لا يؤمنون بالآخرة﴾؟","answer":"خُصوا لأن الإيمان بالآخرة يردع القلب عن الاغترار بالباطل خوف الحساب؛ فمن أنكرها خلا من هذا الرادع فمال إلى الزخرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص671–682.","url":""}]},{"id":"s6-809","number":809,"surah":6,"verses":[113],"verseLabel":"الأنعام: 113","question":"لماذا ترتبت الأفعال: ﴿لتصغى... وليرضوه... وليقترفوا﴾ بهذا الترتيب؟","answer":"التدرج يرسم طريق الضلال: تميل القلوب أولًا إلى الزخرف، ثم ترضاه بعد الميل، ثم تتحول القناعة إلى اقتراف فعلي للذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص671–682.","url":""}]},{"id":"s6-810","number":810,"surah":6,"verses":[113],"verseLabel":"الأنعام: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿وليقترفوا ما هم مقترفون﴾، فكرر مادة الاقتراف؟","answer":"جاء ﴿ما هم مقترفون﴾ من مادة الفعل لتأكيد رسوخهم في الاقتراف، ولإبهام المفعول بما يعم كل ما يكتسبونه من الإثم بعد رضاهم بالباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص671–682.","url":""}]},{"id":"s6-811","number":811,"surah":6,"verses":[114],"verseLabel":"الأنعام: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿أفغير الله أبتغي حكمًا﴾ بتقديم ﴿غير الله﴾؟","answer":"قُدّم ﴿غير الله﴾ ليقع عليه الإنكار والحصر: أأطلب سواه حكمًا؟ فالمقصود نفي التحاكم إلى غيره مع قيام الدليل على انفراده بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص683–701.","url":""}]},{"id":"s6-812","number":812,"surah":6,"verses":[114],"verseLabel":"الأنعام: 114","question":"لماذا اختير ﴿حكمًا﴾، لا: حاكمًا؟","answer":"الحَكَم أبلغ من الحاكم؛ فهو من رسخت فيه أهلية الفصل وصار مرجعًا مرضيًا في الخصومات، لا مجرد من يصدر حكمًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص683–701.","url":""}]},{"id":"s6-813","number":813,"surah":6,"verses":[114],"verseLabel":"الأنعام: 114","question":"لماذا احتج بإنزال الكتاب ﴿مفصلًا﴾ على انفراد الله بالحكم؟","answer":"إنزال الكتاب مفصلًا يعني أنه بيّن الحق والأحكام وميزها، فمن أنزل هذا البيان الكامل هو الجدير أن يُرد إليه الحكم، ولا حاجة إلى حكم يناقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص683–701.","url":""}]},{"id":"s6-814","number":814,"surah":6,"verses":[114],"verseLabel":"الأنعام: 114","question":"ما دلالة شهادة أهل الكتاب في قوله تعالى: ﴿يعلمون أنه منزل من ربك بالحق﴾؟","answer":"ذُكر علم أهل الكتاب حجة إضافية على صدق التنزيل؛ فهم يجدون في كتبهم ما يشهد أن القرآن منزل من رب النبي ملتبسًا بالحق لا بالباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص683–701.","url":""}]},{"id":"s6-815","number":815,"surah":6,"verses":[114],"verseLabel":"الأنعام: 114","question":"لماذا خُتم النهي بـ﴿فلا تكونن من الممترين﴾ مع يقين النبي؟","answer":"الخطاب للنبي والمراد تثبيته وزيادة يقينه، وفيه تعريض بمن يصح منه الامتراء وتحذير للأمة؛ فالنهي لا يقتضي وقوع الشك منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص683–701.","url":""}]},{"id":"s6-816","number":816,"surah":6,"verses":[114],"verseLabel":"الأنعام: 114","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فلا تكونن من الممترين﴾ بنون التوكيد، وفي البقرة: ﴿فلا تكون من الممترين﴾ بلا نون؟","answer":"زاد التوكيد بالنون في الأنعام لأن السياق اشتد في محاجة المشركين وطلب التحاكم مع تمام الكتاب وشهادة أهل الكتاب، فناسب تأكيد الثبات؛ أما موضع البقرة فجاء عقب خبر يعرفه أهل الكتاب فاقتصر على أصل النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص479.","url":""}]},{"id":"s6-817","number":817,"surah":6,"verses":[115],"verseLabel":"الأنعام: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿وتمت كلمة ربك صدقًا وعدلًا﴾، فجعل الكلمة تتم؟","answer":"تمام الكلمة كمالها وثبوتها بحيث لا يلحقها نقص ولا خلف؛ فكلمات الله في الخبر والوعد صدق، وفي الحكم والأمر عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص702–714.","url":""}]},{"id":"s6-818","number":818,"surah":6,"verses":[115],"verseLabel":"الأنعام: 115","question":"لماذا نُصب ﴿صدقًا وعدلًا﴾؟","answer":"﴿صدقًا وعدلًا﴾ منصوبتان على الحال أو التمييز؛ أي تمت كلمة ربك حال كونها صادقة عادلة، أو تمّ صدقها وعدلها، فبيّنتا جهتي الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص702–714.","url":""}]},{"id":"s6-819","number":819,"surah":6,"verses":[115],"verseLabel":"الأنعام: 115","question":"ما سرّ تقديم الصدق على العدل؟","answer":"قُدّم الصدق لأن الخبر سابق في التلقي على امتثال الحكم، ولأن السياق قبله في صدق تنزيل الكتاب، ثم جاء العدل في أحكامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص702–714.","url":""}]},{"id":"s6-820","number":820,"surah":6,"verses":[115],"verseLabel":"الأنعام: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿لا مبدل لكلماته﴾ بالجمع بعد ﴿كلمة ربك﴾ بالإفراد؟","answer":"أُفردت ﴿كلمة﴾ باعتبار الجنس الجامع أو القرآن والوعد الواحد، ثم جُمعت ﴿كلماته﴾ لاستغراق جميع أخباره وأحكامه ووعوده التي لا يملك أحد تبديلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص702–714.","url":""}]},{"id":"s6-821","number":821,"surah":6,"verses":[115],"verseLabel":"الأنعام: 115","question":"لماذا خُتمت بـ﴿وهو السميع العليم﴾؟","answer":"﴿السميع﴾ يناسب أقوال المكذبين ومحاولات التحريف، و﴿العليم﴾ يحيط بأحوالهم ونياتهم وبصدق كلماته؛ فلا يخفى عليه قول ولا باعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص702–714.","url":""}]},{"id":"s6-822","number":822,"surah":6,"verses":[116],"verseLabel":"الأنعام: 116","question":"لماذا حذّر من طاعة ﴿أكثر من في الأرض﴾؟","answer":"حذّر من الأكثرية لأن كثرة أهل الأرض ليست معيارًا للحق؛ فالغالب يومئذ يتبع الشرك والعادات، وطاعته تصرف عن سبيل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص715–729.","url":""}]},{"id":"s6-823","number":823,"surah":6,"verses":[116],"verseLabel":"الأنعام: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿يضلوك عن سبيل الله﴾، فعُدّي الإضلال بـ﴿عن﴾؟","answer":"تعدية الإضلال بـ﴿عن﴾ تفيد الصرف والإبعاد؛ فكأن سبيل الله طريق مستقيم يحاولون تحويل السائر عنه إلى جهة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص715–729.","url":""}]},{"id":"s6-824","number":824,"surah":6,"verses":[116],"verseLabel":"الأنعام: 116","question":"لماذا حصر اتباعهم في ﴿الظن﴾؟","answer":"القصر يبين أن مستندهم ليس علمًا ولا وحيًا، وإنما ظنون موروثة لا تغني من الحق شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص715–729.","url":""}]},{"id":"s6-825","number":825,"surah":6,"verses":[116],"verseLabel":"الأنعام: 116","question":"لماذا عطف قصرًا ثانيًا: ﴿وإن هم إلا يخرصون﴾؟","answer":"القصر الثاني يضيف أنهم لا يقفون عند الظن، بل يخرصون أحكامًا وادعاءات بلا دليل؛ فالأول فساد المستند، والثاني فساد ما يبنون عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص715–729.","url":""}]},{"id":"s6-826","number":826,"surah":6,"verses":[116],"verseLabel":"الأنعام: 116","question":"لماذا اختير ﴿يخرصون﴾، لا: يكذبون؟","answer":"الخرص تقدير الشيء بلا يقين، وأصله تقدير الثمر؛ فهو أدق من الكذب لأنه يصور تخمينهم الذي يصوغونه في صورة علم، وقد ينتهي إلى الكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص715–729.","url":""}]},{"id":"s6-827","number":827,"surah":6,"verses":[117],"verseLabel":"الأنعام: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ربك هو أعلم من يضل﴾ بضمير الفصل؟","answer":"ضمير الفصل ﴿هو﴾ يقصر كمال العلم على الله ويؤكد أن الحكم على الضال والمهتدي ليس للأكثرية ولا للظنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص730–735.","url":""}]},{"id":"s6-828","number":828,"surah":6,"verses":[117],"verseLabel":"الأنعام: 117","question":"لماذا جاء ﴿من يضل﴾ محتملًا للفاعل والمفعول؟","answer":"اللفظ يحتمل: من يضل بنفسه، ومن يضله غيره؛ فيشمل علم الله بالتابعين الضالين وبالقادة المضلين، فلا يخرج فريق من الإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص730–735.","url":""}]},{"id":"s6-829","number":829,"surah":6,"verses":[117],"verseLabel":"الأنعام: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿عن سبيله﴾ وأضاف السبيل إلى الله؟","answer":"إضافة السبيل إلى الله تشرفه وتعينه طريقًا واحدًا موصلًا إليه، فيقابل سبل الظن والخرص المتعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص730–735.","url":""}]},{"id":"s6-830","number":830,"surah":6,"verses":[117],"verseLabel":"الأنعام: 117","question":"لماذا عُدّي العلم في الأولى بلا باء وفي الثانية ﴿بالمهتدين﴾؟","answer":"جاء ﴿أعلم من يضل﴾ على تضمين العلم معنى التمييز أو لكون ﴿من﴾ مفعولًا به، ثم عدي بالباء في ﴿بالمهتدين﴾ على الأصل في تعلق العلم بالمعلوم؛ والتنوع يتسع لوجهي الضال والمضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص730–735.","url":""}]},{"id":"s6-831","number":831,"surah":6,"verses":[118],"verseLabel":"الأنعام: 118","question":"لماذا فُرع الأمر بالأكل بالفاء: ﴿فكلوا مما ذكر اسم الله عليه﴾؟","answer":"الفاء تفرع الأمر على ثبوت علم الله بالمهتدين وعلى إبطال ظنون المشركين؛ فإذا كان حكمه هو الحق فكلوا مما أباحه وذُكر اسمه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص736–741.","url":""}]},{"id":"s6-832","number":832,"surah":6,"verses":[118],"verseLabel":"الأنعام: 118","question":"ما سرّ تقديم ذكر اسم الله معيارًا للحل؟","answer":"ذِكر اسم الله علامة توحيد الذبح وإخلاصه له، فجُعل فارقًا بين ما أذن به وما ذُبح للأوثان أو تُركت عليه التسمية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص736–741.","url":""}]},{"id":"s6-833","number":833,"surah":6,"verses":[118],"verseLabel":"الأنعام: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿إن كنتم بآياته مؤمنين﴾ بتقديم ﴿بآياته﴾؟","answer":"تقديم ﴿بآياته﴾ للاهتمام والقصر الإضافي؛ إن كنتم مؤمنين بآيات الله حقًا فامتثلوا حكمها، لا أحكام المشركين في التحليل والتحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص736–741.","url":""}]},{"id":"s6-834","number":834,"surah":6,"verses":[119],"verseLabel":"الأنعام: 119","question":"لماذا جاء العتاب: ﴿وما لكم ألا تأكلوا﴾ في صورة سؤال؟","answer":"الاستفهام إنكاري يزيل ترددهم في أكل الحلال: أي مانع لكم وقد ذُكر اسم الله وفُصلت المحرمات؟","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص742–760.","url":""}]},{"id":"s6-835","number":835,"surah":6,"verses":[119],"verseLabel":"الأنعام: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿وقد فصل لكم ما حرم عليكم﴾ بالبناء للمجهول؟","answer":"بُني ﴿فُصّل﴾ للمجهول لأن المفصِّل معلوم من السياق وهو الله، ولتوجيه العناية إلى نفس البيان المفصل الذي تقوم به الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص742–760.","url":""}]},{"id":"s6-836","number":836,"surah":6,"verses":[119],"verseLabel":"الأنعام: 119","question":"لماذا استثنى: ﴿إلا ما اضطررتم إليه﴾؟","answer":"الاستثناء يقرر رخصة الضرورة؛ فما حُرم يبقى محرمًا إلا إذا ألجأت الحاجة الملحة إلى قدر يدفع الهلاك، رحمةً بالمكلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص742–760.","url":""}]},{"id":"s6-837","number":837,"surah":6,"verses":[119],"verseLabel":"الأنعام: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿ليضلون بأهوائهم بغير علم﴾، فجمع الأهواء؟","answer":"جُمعت الأهواء لتعدد شهواتهم ومذاهبهم الباطلة في التحليل والتحريم، وكلها صادرة بلا علم ولا وحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص742–760.","url":""}]},{"id":"s6-838","number":838,"surah":6,"verses":[119],"verseLabel":"الأنعام: 119","question":"لماذا خُتمت بـ﴿إن ربك هو أعلم بالمعتدين﴾؟","answer":"الخاتمة تهدد من تجاوز حدود الله في الحلال والحرام؛ وضمير الفصل يؤكد اختصاص الله بكمال العلم بالمعتدين وإن خفي اعتداؤهم على الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص742–760.","url":""}]},{"id":"s6-839","number":839,"surah":6,"verses":[120],"verseLabel":"الأنعام: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وذروا ظاهر الإثم وباطنه﴾؟","answer":"الأمر يشمل ترك كل إثم ظاهر للجوارح أو معلن، وكل إثم باطن في القلب أو مستتر؛ فلا تنحصر التقوى في الصورة الخارجية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص761–770.","url":""}]},{"id":"s6-840","number":840,"surah":6,"verses":[120],"verseLabel":"الأنعام: 120","question":"ما سرّ تقديم ظاهر الإثم على باطنه؟","answer":"قُدّم الظاهر لأنه الأسبق إلى الحس والأوضح في النهي، ثم أُلحق الباطن لإتمام الشمول والتنبيه إلى أن خفاء الذنب لا يخرجه من الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص761–770.","url":""}]},{"id":"s6-841","number":841,"surah":6,"verses":[120],"verseLabel":"الأنعام: 120","question":"لماذا عبّر عن ارتكاب الإثم بـ﴿يكسبون﴾؟","answer":"الكسب يدل على تحصيل الفعل وتحمّل تبعته؛ فالإثم ليس عارضًا منفصلًا عن صاحبه، بل شيء اكتسبه بإرادته وسيجازى عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص761–770.","url":""}]},{"id":"s6-842","number":842,"surah":6,"verses":[120],"verseLabel":"الأنعام: 120","question":"ما سرّ التعبير في قوله تعالى في الجزاء: ﴿بما كانوا يقترفون﴾، لا: بما كانوا يكسبون؟","answer":"الاقتراف أخص في اكتساب الذنب وتعمده؛ فناسب مقام الجزاء والتشنيع، بعد أن جاء الكسب أعم في بيان تحمل المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص761–770.","url":""}]},{"id":"s6-843","number":843,"surah":6,"verses":[121],"verseLabel":"الأنعام: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تأكلوا مما لم يذكر اسم الله عليه﴾، فبنى الفعل للمجهول؟","answer":"بُني ﴿لم يُذكر﴾ للمجهول لأن العناية بانتفاء التسمية نفسها، بصرف النظر عن الذابح، ولأن اسم الله هو المعيار المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص771–781.","url":""}]},{"id":"s6-844","number":844,"surah":6,"verses":[121],"verseLabel":"الأنعام: 121","question":"لماذا أكد: ﴿وإنه لفسق﴾؟","answer":"أكدت الجملة بـ﴿إن﴾ واللام لرد جدال المشركين وتثبيت أن الأكل مما لم يذكر اسم الله عليه خروج عن طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص771–781.","url":""}]},{"id":"s6-845","number":845,"surah":6,"verses":[121],"verseLabel":"الأنعام: 121","question":"إلى ماذا يعود الضمير في ﴿وإنه لفسق﴾؟","answer":"الضمير يعود إلى الأكل المفهوم من النهي، أو إلى ما لم يذكر اسم الله عليه؛ والمعنى في الوجهين أن تناول هذه الذبيحة فسق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص771–781.","url":""}]},{"id":"s6-846","number":846,"surah":6,"verses":[121],"verseLabel":"الأنعام: 121","question":"لماذا وصف وسوسة الشياطين بأنها ﴿يوحون إلى أوليائهم﴾؟","answer":"سميت وسوستهم وحيًا لأنها إلقاء خفي سريع إلى أوليائهم، يمدونهم بحجج باطلة ليجادلوا المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص771–781.","url":""}]},{"id":"s6-847","number":847,"surah":6,"verses":[121],"verseLabel":"الأنعام: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿ليجادلوكم﴾، لا: ليقنعوكم؟","answer":"الجدال يراد به المغالبة والخصومة ودفع الحق بالشبهة، لا طلب الاقتناع؛ فهم يريدون إرباك المؤمنين في حكم الذبائح.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص771–781.","url":""}]},{"id":"s6-848","number":848,"surah":6,"verses":[121],"verseLabel":"الأنعام: 121","question":"لماذا كانت طاعتهم في هذا الحكم شركًا: ﴿إنكم لمشركون﴾؟","answer":"لأن طاعتهم في استحلال ما حرم الله تجعل لهم حق التشريع والتحليل والتحريم من دون الله، وهذا من معنى اتخاذ الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص771–781.","url":""}]},{"id":"s6-849","number":849,"surah":6,"verses":[122],"verseLabel":"الأنعام: 122","question":"لماذا شبّه الكافر بالميت والمؤمن بمن أحياه الله؟","answer":"شُبه الكفر بالموت لأنه يعطل القلب عن إدراك الحق والانتفاع به، وشُبه الإيمان بالإحياء لأنه يعيد إليه البصيرة والحركة في طريق الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص782–792.","url":""}]},{"id":"s6-850","number":850,"surah":6,"verses":[122],"verseLabel":"الأنعام: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿وجعلنا له نورًا يمشي به في الناس﴾؟","answer":"النور هو الوحي والإيمان الذي يهتدي به المؤمن في معاملاته بين الناس؛ وصورة المشي به تدل على أثره العملي المتجدد لا المعرفة المجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص782–792.","url":""}]},{"id":"s6-851","number":851,"surah":6,"verses":[122],"verseLabel":"الأنعام: 122","question":"لماذا عُدّي المشي بالنور بالباء؟","answer":"الباء للاستعانة أو الملابسة؛ فهو يمشي مستعينًا بالنور ومصاحبًا له، فتكون هدايته حاضرة في خطواته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص782–792.","url":""}]},{"id":"s6-852","number":852,"surah":6,"verses":[122],"verseLabel":"الأنعام: 122","question":"ما سرّ التعبير في قوله تعالى في المقابل: ﴿كمن مثله في الظلمات﴾، وزاد ﴿مثله﴾؟","answer":"زيادة ﴿مثله﴾ تبرز هيئةً عجيبة تستحق أن تضرب مثلًا: شخص مستقر في الظلمات لا يخرج منها، وتقابلها صورة من يمشي بالنور.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص782–792.","url":""}]},{"id":"s6-853","number":853,"surah":6,"verses":[122],"verseLabel":"الأنعام: 122","question":"لماذا جُمعت ﴿الظلمات﴾ وأُفرد ﴿نورًا﴾؟","answer":"أُفرد النور لأن الحق واحد متسق، وجُمعت الظلمات لتعدد طرق الكفر والجهل والشهوة والشبهات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص782–792.","url":""}]},{"id":"s6-854","number":854,"surah":6,"verses":[122],"verseLabel":"الأنعام: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿ليس بخارج منها﴾ بالباء والجملة الاسمية؟","answer":"الجملة الاسمية تثبت دوام حاله، والباء في ﴿بخارج﴾ تؤكد النفي؛ فهو مستقر في الظلمات لا يبدو منه خروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص782–792.","url":""}]},{"id":"s6-855","number":855,"surah":6,"verses":[123],"verseLabel":"الأنعام: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك جعلنا في كل قرية أكابر مجرميها﴾؟","answer":"هذا الجعل سنة ابتلاء وتمكين مؤقت؛ يكون في كل مجتمع رؤساء في الإجرام يمكرون بالحق، فيظهر فسادهم وتقوم عليهم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص793–807.","url":""}]},{"id":"s6-856","number":856,"surah":6,"verses":[123],"verseLabel":"الأنعام: 123","question":"ما سرّ تقديم ﴿في كل قرية﴾ على ﴿أكابر مجرميها﴾؟","answer":"قُدّم الظرف لإفادة العموم والاهتمام بانتشار السنة: في كل قرية يوجد هذا الصنف، لا في قرية مخصوصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص793–807.","url":""}]},{"id":"s6-857","number":857,"surah":6,"verses":[123],"verseLabel":"الأنعام: 123","question":"لماذا أضيف الأكابر إلى المجرمين: ﴿أكابر مجرميها﴾؟","answer":"الإضافة تعني أكابر المجرمين فيها، أي أكبرهم جرمًا أو أصحاب المكانة من أهل الإجرام؛ فلا ذم لكل كبير، بل للكبراء الذين اتصفوا بالإجرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص793–807.","url":""}]},{"id":"s6-858","number":858,"surah":6,"verses":[123],"verseLabel":"الأنعام: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿ليمكروا فيها﴾، فجعل المكر غاية لمكانتهم؟","answer":"اللام للعاقبة أو الصيرورة، لا أن الله أحب مكرهم؛ فتمكينهم الذي اختاروا فيه الإجرام آل إلى استعمال نفوذهم في المكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص793–807.","url":""}]},{"id":"s6-859","number":859,"surah":6,"verses":[123],"verseLabel":"الأنعام: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يمكرون إلا بأنفسهم﴾ بطريق القصر؟","answer":"القصر يقلب أثر المكر عليهم: يظنون أنهم يضرون الدعوة، والحقيقة أن وباله وعقوبته لا يعودان إلا إلى أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص793–807.","url":""}]},{"id":"s6-860","number":860,"surah":6,"verses":[123],"verseLabel":"الأنعام: 123","question":"لماذا خُتمت بـ﴿وما يشعرون﴾، لا يعلمون؟","answer":"نُفي عنهم الشعور، وهو أدنى مراتب الإدراك، للمبالغة في غفلتهم عن رجوع المكر عليهم؛ فهم لا يحسون حتى أمارات عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص793–807.","url":""}]},{"id":"s6-861","number":861,"surah":6,"verses":[124],"verseLabel":"الأنعام: 124","question":"ما دلالة بناء الفعل للمجهول في قولهم: ﴿لن نؤمن حتى نؤتى مثل ما أوتي رسل الله﴾؟","answer":"البناء للمجهول يعكس قصر نظرهم على نيل العطاء الحسي والمنزلة، دون التفكر في واهب الرسالة وحكمته؛ فجعلوا غايتهم أن يُؤتوا مثل الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص10–24.","url":""}]},{"id":"s6-862","number":862,"surah":6,"verses":[124],"verseLabel":"الأنعام: 124","question":"ما دلالة الرد بقوله تعالى: ﴿الله أعلم حيث يجعل رسالته﴾؟","answer":"الرد يبين أن الرسالة اصطفاء إلهي قائم على العلم بمن يصلح لحملها، لا مرتبة تُنال بالزعامة أو المال أو الحسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص10–24.","url":""}]},{"id":"s6-863","number":863,"surah":6,"verses":[124],"verseLabel":"الأنعام: 124","question":"لماذا اختير ﴿صغار عند الله﴾ لعقوبتهم؟","answer":"الصغار ذلة يقترن بها الإقرار بالهوان؛ فجزاء استكبارهم وطلبهم منزلة الرسل أن تصيبهم عند الله حقارة تناقض تطاولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص10–24.","url":""}]},{"id":"s6-864","number":864,"surah":6,"verses":[124],"verseLabel":"الأنعام: 124","question":"لماذا عُلّل العذاب بـ﴿بما كانوا يمكرون﴾؟","answer":"لأن طلبهم لم يصدر عن بحث عن الحق، بل كان مكرًا وحسدًا وصدًا عن الدعوة؛ فجاء العذاب من جنس السبب الذي داوموا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص10–24.","url":""}]},{"id":"s6-865","number":865,"surah":6,"verses":[125],"verseLabel":"الأنعام: 125","question":"لماذا صُورت الهداية بـ﴿يشرح صدره للإسلام﴾؟","answer":"شرح الصدر كناية واستعارة عن توسيعه وتهيئته لقبول الحق؛ فالمهتدي يجد في الإسلام انفساحًا وطمأنينة ورغبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص25–41.","url":""}]},{"id":"s6-866","number":866,"surah":6,"verses":[125],"verseLabel":"الأنعام: 125","question":"لماذا صُور الضلال بضيق الصدر وحرجه؟","answer":"ضيق الصدر وحرجه يصوران امتناعه عن قبول الإيمان وشدة نفوره منه؛ فالحرج غاية الضيق كالمكان المتشابك الذي لا منفذ فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص25–41.","url":""}]},{"id":"s6-867","number":867,"surah":6,"verses":[125],"verseLabel":"الأنعام: 125","question":"لماذا شُبه الضال بمن ﴿يصعد في السماء﴾؟","answer":"التصعد في السماء يورث ضيق النفس ومشقة التنفس؛ فشُبهت معاناة المعرض عن الإسلام ومكابدته لقبول الحق بمن يصعد صعودًا شاقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص25–41.","url":""}]},{"id":"s6-868","number":868,"surah":6,"verses":[125],"verseLabel":"الأنعام: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿يجعل الله الرجس على الذين لا يؤمنون﴾؟","answer":"الرجس ما يستقذر من العذاب أو الضلال؛ وجعله عليهم يصور لزومه وإحاطته بهم جزاءً لإصرارهم على عدم الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص25–41.","url":""}]},{"id":"s6-869","number":869,"surah":6,"verses":[126],"verseLabel":"الأنعام: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿وهذا صراط ربك مستقيمًا﴾، فنصب ﴿مستقيمًا﴾؟","answer":"﴿مستقيمًا﴾ حال من ﴿صراط ربك﴾؛ أي هذا الطريق حال كونه مستقيمًا لا اعوجاج فيه، فنصبه يصف هيئته عند الإشارة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص42–50.","url":""}]},{"id":"s6-870","number":870,"surah":6,"verses":[126],"verseLabel":"الأنعام: 126","question":"لماذا أضيف الصراط إلى ﴿ربك﴾؟","answer":"إضافته إلى ﴿ربك﴾ تشريف له وتطمين للنبي بأن هذا الطريق من عند ربه الذي يتولاه بالتربية والنصر، لا من وضع البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص42–50.","url":""}]},{"id":"s6-871","number":871,"surah":6,"verses":[126],"verseLabel":"الأنعام: 126","question":"لماذا خُتمت بـ﴿لقوم يذكرون﴾؟","answer":"الآيات قد فُصلت، فلا يحتاج المنتفع إلى دليل جديد بل إلى تذكر ما تقرر والعمل به؛ لذلك خُص بها قوم يتذكرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص42–50.","url":""}]},{"id":"s6-872","number":872,"surah":6,"verses":[127],"verseLabel":"الأنعام: 127","question":"لماذا سُميت الجنة ﴿دار السلام﴾؟","answer":"سميت الجنة دار السلام لأنها دار السلامة من الموت والآفات والحزن، ولأن تحيتهم فيها سلام، وقيل السلام اسم الله وإضافتها إليه للتشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص51–58.","url":""}]},{"id":"s6-873","number":873,"surah":6,"verses":[127],"verseLabel":"الأنعام: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿عند ربهم﴾؟","answer":"﴿عند ربهم﴾ تفيد القرب المعنوي والتكريم والضمان؛ فدار السلام ثابتة لهم في جوار رحمته وتحت رعايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص51–58.","url":""}]},{"id":"s6-874","number":874,"surah":6,"verses":[127],"verseLabel":"الأنعام: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿وهو وليهم بما كانوا يعملون﴾؟","answer":"ولايتُه لهم نصرٌ ورعاية ومحبة، وهي جزاء أعمالهم الصالحة؛ فالباء للسببية مع أن العمل نفسه بتوفيقه وفضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص51–58.","url":""}]},{"id":"s6-875","number":875,"surah":6,"verses":[128],"verseLabel":"الأنعام: 128","question":"لماذا نادى الجن وحدهم أولًا: ﴿يا معشر الجن قد استكثرتم من الإنس﴾؟","answer":"بدأ بالجن لأنهم أصل الإغواء في هذا السياق، ولأن الخطاب السابق تناول استكثارهم من إضلال الإنس الذين اتخذوهم أولياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص59–79.","url":""}]},{"id":"s6-876","number":876,"surah":6,"verses":[128],"verseLabel":"الأنعام: 128","question":"لماذا عبّر عن علاقة الجن والإنس بـ﴿استمتع بعضنا ببعض﴾؟","answer":"الاستمتاع تبادل المنافع والأغراض: انتفع الجن بطاعة الإنس وتعظيمهم، وانتفع الإنس بما توهموه من خبر أو حماية وخدمة؛ فاشترك الفريقان في علاقة الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص59–79.","url":""}]},{"id":"s6-877","number":877,"surah":6,"verses":[128],"verseLabel":"الأنعام: 128","question":"ما دلالة قولهم: ﴿وبلغنا أجلنا الذي أجلت لنا﴾؟","answer":"اعترفوا بأنهم استمروا في ذلك الاستمتاع حتى انتهت مدة حياتهم وجاء الأجل الذي وقته الله لهم؛ فلا حجة لهم بعد استيفاء زمن الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص59–79.","url":""}]},{"id":"s6-878","number":878,"surah":6,"verses":[128],"verseLabel":"الأنعام: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿النار مثواكم﴾، لا: مأواكم؟","answer":"المثوى مقام الإقامة الطويلة المستقرة، وهو أنسب بخلودهم في النار من لفظ المأوى الذي قد يطلق على مجرد موضع اللجوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص59–79.","url":""}]},{"id":"s6-879","number":879,"surah":6,"verses":[128],"verseLabel":"الأنعام: 128","question":"ما دلالة الاستثناء ﴿إلا ما شاء الله﴾ بعد ﴿خالدين فيها﴾؟","answer":"الاستثناء يثبت أن الخلود واقع تحت مشيئة الله لا خارجًا عنها، وقيل يعود إلى مدة المقام قبل دخول النار أو إلى من شاء الله إخراجه ممن لم يخلد خلود الكفار؛ فلا يدل على انقطاع عذاب الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص59–79.","url":""}]},{"id":"s6-880","number":880,"surah":6,"verses":[129],"verseLabel":"الأنعام: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك نولي بعض الظالمين بعضًا﴾؟","answer":"التولية جعل بعض الظالمين أولياء بعض أو تسليط بعضهم على بعض؛ فمن اختار الظلم قُرن بنظيره وجوزي به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص80–85.","url":""}]},{"id":"s6-881","number":881,"surah":6,"verses":[129],"verseLabel":"الأنعام: 129","question":"لماذا كرر ﴿بعض﴾؟","answer":"تكرار ﴿بعض﴾ يبين تبادل الولاية بين فريقين من جنس الظالمين: بعضهم يتولى بعضًا، فلا تختص العلاقة بطرف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص80–85.","url":""}]},{"id":"s6-882","number":882,"surah":6,"verses":[129],"verseLabel":"الأنعام: 129","question":"لماذا عُللت الولاية بـ﴿بما كانوا يكسبون﴾؟","answer":"الباء سببية؛ فتولي الظالمين بعضهم بعضًا وتسليطهم نتيجة لما كانوا يداومون على اكتسابه من الظلم، والجزاء من جنس العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص80–85.","url":""}]},{"id":"s6-883","number":883,"surah":6,"verses":[130],"verseLabel":"الأنعام: 130","question":"لماذا نودي ﴿معشر الجن والإنس﴾ مع أن الرسل من الإنس؟","answer":"نودي الفريقان لأنهما مكلفان محاسبان وقد بلغتهما الرسالة، وإن كان الرسل من الإنس؛ فالخطاب يجمع من اشتركوا في التكذيب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص86–100.","url":""}]},{"id":"s6-884","number":884,"surah":6,"verses":[130],"verseLabel":"الأنعام: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿رسل منكم﴾؟","answer":"﴿منكم﴾ تصح باعتبار أن الإنس والجن جماعتان مجموعتان في الخطاب والرسل من أحدهما، أو لأن رسل الإنس بلغوا الفريقين وقام من الجن نذر ينقلون دعوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص86–100.","url":""}]},{"id":"s6-885","number":885,"surah":6,"verses":[130],"verseLabel":"الأنعام: 130","question":"لماذا جمع بين ﴿يقصون عليكم آياتي﴾ و﴿ينذرونكم لقاء يومكم﴾؟","answer":"قص الآيات بيان للحجة والهداية، والإنذار بلقاء اليوم بيان لعاقبة الإعراض؛ فجمع بين إقامة الدليل والتحذير من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص86–100.","url":""}]},{"id":"s6-886","number":886,"surah":6,"verses":[130],"verseLabel":"الأنعام: 130","question":"ما دلالة اعترافهم في قوله تعالى: ﴿شهدنا على أنفسنا﴾؟","answer":"اعترفوا على أنفسهم لأن الحجة أحاطت بهم ولم يبق مجال للإنكار؛ فصار المقر والمشهود عليه واحدًا، وهو أبلغ في الإلزام.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص86–100.","url":""}]},{"id":"s6-887","number":887,"surah":6,"verses":[130],"verseLabel":"الأنعام: 130","question":"لماذا تكرر: ﴿وشهدوا على أنفسهم أنهم كانوا كافرين﴾؟","answer":"الجملة الأولى جوابهم عند السؤال وإقرارهم بقيام الحجة، والثانية حكاية من الله تثبت حقيقة شهادتهم وكفرهم بعد أن غرتهم الحياة الدنيا؛ فليست تكرارًا خاليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص86–100.","url":""}]},{"id":"s6-888","number":888,"surah":6,"verses":[131],"verseLabel":"الأنعام: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك أن لم يكن ربك مهلك القرى بظلم﴾؟","answer":"المعنى أن إرسال الرسل والإنذار لأجل أن سنة الله لم تكن إهلاك القرى بسبب ظلمها وأهلها غافلون لم تبلغهم الحجة؛ فالآية تقرر عدله قبل العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص101–113.","url":""}]},{"id":"s6-889","number":889,"surah":6,"verses":[131],"verseLabel":"الأنعام: 131","question":"لماذا اختير اسم الفاعل ﴿مهلك﴾؟","answer":"اسم الفاعل ﴿مهلك﴾ يدل على ثبوت الشأن والصفة في المقام، وينفي أن يكون من سنته إهلاك القرى على تلك الحال دون إنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص101–113.","url":""}]},{"id":"s6-890","number":890,"surah":6,"verses":[131],"verseLabel":"الأنعام: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿وأهلها غافلون﴾ لا جاهلون؟","answer":"الغفلة ذهول عن الحق مع عدم التنبيه إليه، وهي الأنسب لعدم بلوغ الرسالة؛ أما الجهل فقد يبقى بعد البيان بسبب الإعراض، فلا يمنع استحقاق العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص101–113.","url":""}]},{"id":"s6-891","number":891,"surah":6,"verses":[132],"verseLabel":"الأنعام: 132","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكل درجات مما عملوا﴾، فجمع الدرجات للفريقين؟","answer":"الدرجات تشمل مراتب الثواب والعقاب صعودًا وهبوطًا تغليبًا، فلكل من الإنس والجن منزلة تناسب عمله، ولا يستوي المحسن والمسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص114–125.","url":""}]},{"id":"s6-892","number":892,"surah":6,"verses":[132],"verseLabel":"الأنعام: 132","question":"ما سرّ التعبير في قوله تعالى: ﴿مما عملوا﴾، لا: بحسب أعمالهم؟","answer":"﴿مما عملوا﴾ تجعل الأعمال نفسها منشأً لبعض الدرجات وسببًا لها، وتدل ﴿من﴾ على أن الجزاء بقدر العمل من غير ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص114–125.","url":""}]},{"id":"s6-893","number":893,"surah":6,"verses":[132],"verseLabel":"الأنعام: 132","question":"لماذا خُتمت بـ﴿وما ربك بغافل عما يعملون﴾؟","answer":"الخاتمة ضمان للجزاء الدقيق وتهديد للمعرضين؛ فربهم لا يغيب عنه عمل ظاهر أو خفي، والباء في ﴿بغافل﴾ تؤكد نفي الغفلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص114–125.","url":""}]},{"id":"s6-894","number":894,"surah":6,"verses":[133],"verseLabel":"الأنعام: 133","question":"لماذا جمع بين ﴿الغني﴾ و﴿ذو الرحمة﴾؟","answer":"الغنى ينفي حاجته إلى الخلق وطاعتهم، والرحمة تثبت إحسانه إليهم مع استغنائه؛ فلا يعاجلهم بالإزالة، ويمهلهم ويفتح لهم باب الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص126–147.","url":""}]},{"id":"s6-895","number":895,"surah":6,"verses":[133],"verseLabel":"الأنعام: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿إن يشأ يذهبكم﴾، لا: يهلككم؟","answer":"الإذهاب أعم من الإهلاك؛ فقد يكون بالإفناء أو الإبعاد وإزالة السلطان، وهو الأنسب مع قوله بعده ﴿ويستخلف من بعدكم﴾: يزيلكم ويأت بغيركم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص126–147.","url":""}]},{"id":"s6-896","number":896,"surah":6,"verses":[133],"verseLabel":"الأنعام: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿ويستخلف من بعدكم ما يشاء﴾، واستعمل ﴿ما﴾؟","answer":"استُعملت ﴿ما﴾ لتعميم المستخلَف وإبهام جنسه وصفته؛ فالله قادر أن يأتي بعدهم بما يشاء من خلق لا يحيطون به، وفي ذلك تهديد أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص126–147.","url":""}]},{"id":"s6-897","number":897,"surah":6,"verses":[133],"verseLabel":"الأنعام: 133","question":"لماذا شبّه الاستخلاف بإنشائهم ﴿من ذرية قوم آخرين﴾؟","answer":"ذكّرهم أن وجودهم نفسه جاء باستخلاف ذرية بعد قوم سبقوهم؛ فما وقع في نشأتهم دليل محسوس على إمكان إذهابهم والإتيان بغيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص126–147.","url":""}]},{"id":"s6-898","number":898,"surah":6,"verses":[134],"verseLabel":"الأنعام: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ما توعدون لآت﴾ باسم الفاعل؟","answer":"اسم الفاعل ﴿لآت﴾ يثبت تحقق الموعود واستقراره حتى كأنه متجه إليهم لا محالة، وأكد بـ﴿إن﴾ واللام لمواجهة إنكارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص148–155.","url":""}]},{"id":"s6-899","number":899,"surah":6,"verses":[134],"verseLabel":"الأنعام: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أنتم بمعجزين﴾، دون أن يقال: ولن تفلتوا؟","answer":"المعجز هو الذي يفوت طالبه ويجعله عاجزًا عن إدراكه؛ فنفى أن يستطيعوا الإفلات من قدرة الله أينما كانوا، وهو أبلغ من مجرد نفي الفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص148–155.","url":""}]},{"id":"s6-900","number":900,"surah":6,"verses":[135],"verseLabel":"الأنعام: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿اعملوا على مكانتكم إني عامل﴾؟","answer":"الأمر للتهديد لا للإباحة: اثبتوا على غاية تمكنكم وطريقتكم، وأنا ماض في عملي؛ وستكشف العاقبة صدق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص156–175.","url":""}]},{"id":"s6-901","number":901,"surah":6,"verses":[135],"verseLabel":"الأنعام: 135","question":"لماذا كرر مادة العمل بين الفريقين؟","answer":"تكرار مادة العمل يقابل طريقهم بطريق الرسول ويبين أن الجزاء ثمرة العمل: هم يعملون على الكفر وهو يعمل على الوحي، ثم تظهر عاقبة كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص156–175.","url":""}]},{"id":"s6-902","number":902,"surah":6,"verses":[135],"verseLabel":"الأنعام: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿فسوف تعلمون من تكون له عاقبة الدار﴾، ولم يصرح بالفائز؟","answer":"أبهم صاحب العاقبة تهويلًا وتشويقًا، ولأن الخاتمة التالية تكشفه بطريق البرهان: الظالمون لا يفلحون، فثبت أن العاقبة لغيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص156–175.","url":""}]},{"id":"s6-903","number":903,"surah":6,"verses":[135],"verseLabel":"الأنعام: 135","question":"لماذا خُتمت بـ﴿إنه لا يفلح الظالمون﴾؟","answer":"الخاتمة تعلل الوعيد وتقرر سنة عامة: الشرك والصد عن الحق ظلم، والظالم لا يبلغ الفلاح؛ لذلك ستكون عاقبة الدار للرسول والمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص156–175.","url":""}]},{"id":"s6-904","number":904,"surah":6,"verses":[136],"verseLabel":"الأنعام: 136","question":"ما سرّ التعبير في قوله تعالى: ﴿مما ذرأ من الحرث والأنعام نصيبًا﴾، واختار ﴿ذرأ﴾؟","answer":"الذرء هو الخلق مع الإكثار والبث؛ فذكّر أن الحرث والأنعام التي قسموها من خلق الله المنشور لهم، فلا يملكون التشريع فيها من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص176–192.","url":""}]},{"id":"s6-905","number":905,"surah":6,"verses":[136],"verseLabel":"الأنعام: 136","question":"ما دلالة قولهم: ﴿هذا لله بزعمهم وهذا لشركائنا﴾ مع تكرار اسم الإشارة؟","answer":"تكرار اسم الإشارة يفصل النصيبين فصلًا حسيًا كأنهما موضوعان أمامهم، ويكشف اصطناعهم قسمة بين الله وشركائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص176–192.","url":""}]},{"id":"s6-906","number":906,"surah":6,"verses":[136],"verseLabel":"الأنعام: 136","question":"لماذا قُيّد نصيب الله وحده بـ﴿بزعمهم﴾؟","answer":"قُيّد نصيب الله بـ﴿بزعمهم﴾ لأن أصل جعل نصيب لله على هذا الوجه تشريع باطل من عندهم، أما نسبة القسم الآخر لشركائهم فهي حكاية مباشرة لمقصودهم الفاسد، والزعم ينسحب على القسمة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص176–192.","url":""}]},{"id":"s6-907","number":907,"surah":6,"verses":[136],"verseLabel":"الأنعام: 136","question":"لماذا كان نصيب الشركاء لا يصل إلى الله، ونصيب الله يصل إليهم؟","answer":"كانوا إذا اختلط نصيب الشركاء بنصيب الله تركوه لهم، وإذا وقع العكس ردوه إلى الشركاء؛ فصور السياق جورهم وميلهم إلى أوثانهم حتى في قسمة اخترعوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص176–192.","url":""}]},{"id":"s6-908","number":908,"surah":6,"verses":[136],"verseLabel":"الأنعام: 136","question":"لماذا خُتمت بـ﴿ساء ما يحكمون﴾؟","answer":"﴿ساء﴾ ذم جامع لحكمهم؛ فهو فاسد في أصله لأنه تشريع بلا إذن، وجائر في تطبيقه لانحيازهم إلى الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص176–192.","url":""}]},{"id":"s6-909","number":909,"surah":6,"verses":[137],"verseLabel":"الأنعام: 137","question":"لماذا أسند تزيين قتل الأولاد إلى ﴿شركائهم﴾؟","answer":"أسند التزيين إلى الشركاء لأن الكهنة وسدنة الأصنام والشياطين هم الذين حسّنوا لهم قتل الأولاد وشرعوه، فقادهم شركهم إلى الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص193–209.","url":""}]},{"id":"s6-910","number":910,"surah":6,"verses":[137],"verseLabel":"الأنعام: 137","question":"ما سرّ تقديم ﴿لكثير من المشركين﴾ بين الفعل وفاعله؟","answer":"فصل الجار والمجرور بين الفعل وفاعله للاهتمام بكثرة من وقع عليهم التزيين، وللتشويق إلى الفاعل المتأخر ﴿شركاؤهم﴾ وبيان تمكنه منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص193–209.","url":""}]},{"id":"s6-911","number":911,"surah":6,"verses":[137],"verseLabel":"الأنعام: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿ليردوهم وليلبسوا عليهم دينهم﴾؟","answer":"الإرداء الإهلاك والإسقاط، ولبس الدين خلطه وإفساده؛ فجمع بين غاية فعلهم في النفوس، وهي الهلاك، وفي الدين، وهي التشويش والتحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص193–209.","url":""}]},{"id":"s6-912","number":912,"surah":6,"verses":[137],"verseLabel":"الأنعام: 137","question":"لماذا خُتمت بـ﴿فذرهم وما يفترون﴾ كما في الآية 112؟","answer":"تكرر الختام لاتحاد الحال: شياطين الإنس والجن والشركاء يزينون الافتراء، وبعد إقامة الحجة يُترك أهله إلى وعيد الله، مع الاستمرار في البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص193–209.","url":""}]},{"id":"s6-913","number":913,"surah":6,"verses":[138],"verseLabel":"الأنعام: 138","question":"لماذا وصفوا الأنعام والحرث بـ﴿حجر﴾؟","answer":"الحِجر هو المنع والتحجير؛ وصفوا الأنعام والحرث به لأنهم جعلوها محظورة لا يأكلها إلا من يختارونه، كأن المنع صفة ثابتة فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص210–245.","url":""}]},{"id":"s6-914","number":914,"surah":6,"verses":[138],"verseLabel":"الأنعام: 138","question":"لماذا تكرر ﴿أنعام﴾ ثلاث مرات؟","answer":"تكررت ﴿أنعام﴾ لأن كل جملة تتناول طائفة ذات حكم مستقل اخترعوه: ممنوعة الأكل، أو محرمة الظهور، أو لا يذكرون اسم الله عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص210–245.","url":""}]},{"id":"s6-915","number":915,"surah":6,"verses":[138],"verseLabel":"الأنعام: 138","question":"ما دلالة قولهم: ﴿لا يطعمها إلا من نشاء﴾ وإسناد التشريع إلى مشيئتهم؟","answer":"إسناد الإطعام إلى مشيئتهم يفضح اغتصابهم حق التشريع؛ جعلوا الحل والمنع تابعين لأهوائهم لا لوحي من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص210–245.","url":""}]},{"id":"s6-916","number":916,"surah":6,"verses":[138],"verseLabel":"الأنعام: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنعام حرمت ظهورها﴾؟","answer":"تحريم الظهور كناية عن منع ركوب طائفة من الأنعام أو الحمل عليها؛ فخُص الظهر لأنه موضع الانتفاع الذي حظروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص210–245.","url":""}]},{"id":"s6-917","number":917,"surah":6,"verses":[138],"verseLabel":"الأنعام: 138","question":"لماذا خُتم بـ﴿افتراء عليه سيجزيهم بما كانوا يفترون﴾ بتكرار الافتراء؟","answer":"الأول ﴿افتراء عليه﴾ يصف علة فعلهم وحقيقته، والثاني ﴿بما كانوا يفترون﴾ يثبت أن الجزاء بسبب افترائهم المتكرر؛ فجمع وصف الجريمة ووعيدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص210–245.","url":""}]},{"id":"s6-918","number":918,"surah":6,"verses":[139],"verseLabel":"الأنعام: 139","question":"ما دلالة قولهم: ﴿ما في بطون هذه الأنعام خالصة لذكورنا ومحرم على أزواجنا﴾؟","answer":"حكوا تشريعًا متناقضًا: جعلوا ما في بطون أنواع مخصوصة خالصًا للذكور محرمًا على النساء، ثم سووا بينهم إذا خرج ميتًا؛ ففضح السياق تحكمهم بلا دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص246–267؛ باحث، تفريغ د. فاضل السامرائي: «خالصة لذكورنا ومحرم على أزواجنا».","url":""}]},{"id":"s6-919","number":919,"surah":6,"verses":[139],"verseLabel":"الأنعام: 139","question":"لماذا أُنثت ﴿خالصة﴾ مع أن ﴿ما﴾ قد يشمل المذكر؟","answer":"أُنثت ﴿خالصة﴾ لأنها خبر عن معنى مؤنث مقدر، كالنَّسَمة أو الأنعام، أو لأنها مصدر بمعنى الخلوص لا يلزم فيه التطابق؛ فصح وقوعها على ﴿ما﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص246–267.","url":""}]},{"id":"s6-920","number":920,"surah":6,"verses":[139],"verseLabel":"الأنعام: 139","question":"ما سرّ التعبير في قوله تعالى في الميتة: ﴿فهم فيه شركاء﴾، فغيّر حكم الذكور والإناث؟","answer":"التحول إلى الاشتراك عند الموت يكشف أن أحكامهم لا تقوم على علة ثابتة؛ فما خصوه بالذكور حيًا أباحوه للذكور والنساء ميتًا وفق الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص246–267.","url":""}]},{"id":"s6-921","number":921,"surah":6,"verses":[139],"verseLabel":"الأنعام: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿سيجزيهم وصفهم﴾، فجعل الوصف نفسه مجزيًا؟","answer":"فيه حذف مضاف أو مجاز؛ أي سيجزيهم جزاء وصفهم الكاذب، وجُعل الوصف نفسه كأنه الجزاء لمبالغة في تحقق العقوبة وملازمتها لافترائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص246–267.","url":""}]},{"id":"s6-922","number":922,"surah":6,"verses":[140],"verseLabel":"الأنعام: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿قد خسر الذين قتلوا أولادهم سفهًا بغير علم﴾؟","answer":"﴿قد﴾ تحقق الخسران، و﴿سفهًا﴾ يكشف خفة العقل، و﴿بغير علم﴾ ينفي كل حجة؛ فجمع الحكم بالخسارة وسببها النفسي والمعرفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص268–286.","url":""}]},{"id":"s6-923","number":923,"surah":6,"verses":[140],"verseLabel":"الأنعام: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿وحرموا ما رزقهم الله﴾، فجعل التحريم اعتداء على الرزق؟","answer":"إضافة الرزق إلى الله تبين قبح التحريم: منعوا أنفسهم نعمة أباحها رازقها، ونسبوا إليه حكمًا لم يأذن به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص268–286.","url":""}]},{"id":"s6-924","number":924,"surah":6,"verses":[140],"verseLabel":"الأنعام: 140","question":"لماذا كرر معنى الافتراء: ﴿افتراء على الله﴾؟","answer":"ذُكر ﴿افتراء على الله﴾ لأن مجرد قتل الأولاد وتحريم الرزق ضلال، ثم زادوا عليه جريمة نسبة ذلك التشريع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص268–286.","url":""}]},{"id":"s6-925","number":925,"surah":6,"verses":[140],"verseLabel":"الأنعام: 140","question":"لماذا جمع بين ﴿قد ضلوا﴾ و﴿وما كانوا مهتدين﴾؟","answer":"﴿قد ضلوا﴾ يثبت وقوعهم في الضلال، و﴿وما كانوا مهتدين﴾ ينفي عنهم أصل الاهتداء واستمراره؛ فجمع إثبات الفساد ونفي ضده توكيدًا لتمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص268–286.","url":""}]},{"id":"s6-926","number":926,"surah":6,"verses":[141],"verseLabel":"الأنعام: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿أنشأ جنات معروشات وغير معروشات﴾؟","answer":"المعروشات ما يُرفع نباتها على عروش أو ما يعتني الناس بإنشائه، وغير المعروشات ما يقوم على سوقه أو ينبت دون تعريش؛ فالمقابلة تستوعب صور الجنات وتنوع الصنعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص287–315.","url":""}]},{"id":"s6-927","number":927,"surah":6,"verses":[141],"verseLabel":"الأنعام: 141","question":"ما سرّ تقديم النخل والزرع على الزيتون والرمان؟","answer":"قُدّم النخل والزرع لأنهما أصل الأقوات وأعم نفعًا للعرب: التمر والحبوب، ثم ذُكر الزيتون والرمان من الثمار المكملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص287–315.","url":""}]},{"id":"s6-928","number":928,"surah":6,"verses":[141],"verseLabel":"الأنعام: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿مختلفًا أكله﴾ مع وحدة الماء؟","answer":"اختلاف الأكل مع وحدة الماء والتربة في الأصل دليل على القدرة والتقدير؛ فالثمار تتنوع طعمًا ولونًا ونفعًا بإبداع الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص287–315.","url":""}]},{"id":"s6-929","number":929,"surah":6,"verses":[141],"verseLabel":"الأنعام: 141","question":"لماذا تكرر: ﴿متشابهًا وغير متشابه﴾ بعد الآية 99؟","answer":"تكرر الوصف لأن آية 99 في مقام النظر إلى دلائل الخلق، وهنا في مقام الامتنان وإبطال التحريم وأداء الحق؛ فالمشهد الواحد يخدم غرضين مختلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص287–315.","url":""}]},{"id":"s6-930","number":930,"surah":6,"verses":[141],"verseLabel":"الأنعام: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿كلوا من ثمره إذا أثمر وآتوا حقه يوم حصاده﴾؟","answer":"أباح الأكل عند ظهور الثمر قبل الحصاد، وأمر بأداء حقه عند الحصاد حين يتيسر التقدير والإخراج؛ فجمع الانتفاع الشخصي وحق المحتاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص287–315.","url":""}]},{"id":"s6-931","number":931,"surah":6,"verses":[141],"verseLabel":"الأنعام: 141","question":"لماذا أعقب الإباحة بالنهي: ﴿ولا تسرفوا﴾؟","answer":"أعقب الإباحة بالنهي حتى لا ينقلب الانتفاع أو البذل إلى تجاوز: إسراف في الأكل أو الصدقة أو تضييع الثمر، فالنعمة تضبط بحقها وحدودها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص287–315.","url":""}]},{"id":"s6-932","number":932,"surah":6,"verses":[142],"verseLabel":"الأنعام: 142","question":"لماذا قُسمت الأنعام إلى ﴿حمولة وفرشًا﴾؟","answer":"الحمولة ما كبر من الأنعام فحمل الأثقال أو رُكب، والفرش ما صغر منها أو قرب من الأرض للذبح؛ فالقسمة تستوعب منافعها وأحجامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص316–327.","url":""}]},{"id":"s6-933","number":933,"surah":6,"verses":[142],"verseLabel":"الأنعام: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿مما رزقكم الله﴾ بعد الأمر بالأكل؟","answer":"التعبير يذكر أن المأكول عطية من الله لا ملك مستقل، فيوجب شكره واتباع حكمه في الحلال بدل تحريم المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص316–327.","url":""}]},{"id":"s6-934","number":934,"surah":6,"verses":[142],"verseLabel":"الأنعام: 142","question":"لماذا صُورت وساوس الشيطان بـ﴿خطوات﴾؟","answer":"الخطوات تصور الإغواء متدرجًا؛ لا ينقل الشيطان غالبًا إلى النهاية دفعة، بل يقود من تحريم مبتدع إلى آخر حتى يستحكم الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص316–327.","url":""}]},{"id":"s6-935","number":935,"surah":6,"verses":[142],"verseLabel":"الأنعام: 142","question":"لماذا خُتمت بـ﴿إنه لكم عدو مبين﴾؟","answer":"الخاتمة تعلل النهي: لا يُتبع من ثبتت عداوته وظهر قصده في الإضلال، و﴿لكم﴾ تخصيص يزيد التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص316–327.","url":""}]},{"id":"s6-936","number":936,"surah":6,"verses":[143],"verseLabel":"الأنعام: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿ثمانية أزواج﴾ ثم فصلها نوعًا نوعًا؟","answer":"الزوج هنا الفرد المقترن بنظيره؛ فالثمانية أربعة أنواع، من كل نوع ذكر وأنثى. ثم فُصلت ليحاصرهم السؤال في كل صنف ولا يبقى لتحريمهم مخرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص328–344.","url":""}]},{"id":"s6-937","number":937,"surah":6,"verses":[143],"verseLabel":"الأنعام: 143","question":"لماذا بدأ بالضأن ثم المعز؟","answer":"بدأ بالضأن لأنها أشهر الغنم وأكثرها نفعًا ولأنها ذات الصوف الموافق لمعنى الفرش، ثم أتبعها بالمعز من جنس الغنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص328–344.","url":""}]},{"id":"s6-938","number":938,"surah":6,"verses":[143],"verseLabel":"الأنعام: 143","question":"لماذا كرر السؤال: ﴿آلذكرين حرم أم الأنثيين أم ما اشتملت عليه أرحام الأنثيين﴾؟","answer":"تكرر السؤال مع كل نوع لاستيعاب الاحتمالات: إن حُرم الذكر لزم تحريم كل ذكر، وإن الأنثى فكل أنثى، وإن ما في الرحم فالجنسين؛ وبذلك يبطل تخصيصهم الاعتباطي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص328–344.","url":""}]},{"id":"s6-939","number":939,"surah":6,"verses":[143],"verseLabel":"الأنعام: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿نبئوني بعلم إن كنتم صادقين﴾؟","answer":"﴿نبئوني﴾ تطلب خبرًا عظيمًا واضح الحجة، وقُيّد بالعلم لإسقاط الظن والعادة؛ فإن كانوا صادقين فليأتوا بدليل على التحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص328–344.","url":""}]},{"id":"s6-940","number":940,"surah":6,"verses":[144],"verseLabel":"الأنعام: 144","question":"لماذا كرر التفصيل نفسه في الإبل والبقر؟","answer":"كرر التفصيل في الإبل والبقر لإتمام حصر الأزواج الثمانية وإلزامهم بالحجة نفسها في كل الأنواع التي تعلق بها تحريمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص345–362.","url":""}]},{"id":"s6-941","number":941,"surah":6,"verses":[144],"verseLabel":"الأنعام: 144","question":"لماذا انتقل إلى سؤال الشهادة: ﴿أم كنتم شهداء إذ وصاكم الله بهذا﴾؟","answer":"بعد إبطال كل تعليل عقلي انتقل إلى آخر دعوى ممكنة: هل شهدوا وحي الله بهذا التحريم؟ والاستفهام إنكاري يكشف أنهم لم يملكوا علمًا ولا شهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص345–362.","url":""}]},{"id":"s6-942","number":942,"surah":6,"verses":[144],"verseLabel":"الأنعام: 144","question":"لماذا وصف التحريم المفتَرى بأنه إضلال ﴿بغير علم﴾؟","answer":"وُصف بالإضلال لأن المفترين لا يكتفون بضلال أنفسهم بل ينسبون الحكم إلى الله ليحملوا الناس عليه، و﴿بغير علم﴾ تفضح غياب الوحي والبرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص345–362.","url":""}]},{"id":"s6-943","number":943,"surah":6,"verses":[144],"verseLabel":"الأنعام: 144","question":"لماذا خُتمت بـ﴿إن الله لا يهدي القوم الظالمين﴾؟","answer":"الخاتمة تناسب افتراءهم وظلمهم: من اختار نسبة الكذب إلى الله وإضلال الناس حُرم هداية التوفيق جزاء إصراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص345–362.","url":""}]},{"id":"s6-944","number":944,"surah":6,"verses":[145],"verseLabel":"الأنعام: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿لا أجد فيما أوحي إلي محرمًا﴾، دون أن يقال: لا يوجد؟","answer":"﴿لا أجد﴾ يحكي نتيجة البحث في الوحي المبلغ للنبي، فيواجه دعواهم بشهادة الرسول المباشرة: لا أجد فيه تحريمًا إلا المذكورات.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص363–389.","url":""}]},{"id":"s6-945","number":945,"surah":6,"verses":[145],"verseLabel":"الأنعام: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿على طاعم يطعمه﴾، فكرر مادة الطعم؟","answer":"﴿على طاعم﴾ يعمم الحكم في كل من يتناول الطعام، و﴿يطعمه﴾ تؤكد تحقق فعل الأكل؛ فلا يلحق التحريم الشيء من غير جهة تناوله طعامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص363–389.","url":""}]},{"id":"s6-946","number":946,"surah":6,"verses":[145],"verseLabel":"الأنعام: 145","question":"لماذا قُيد الدم بـ﴿مسفوحًا﴾؟","answer":"المسفوح هو الدم الجاري المصبوب عند الذبح؛ فالقيد يخرج الدم الباقي في العروق واللحم مما لا يمكن الاحتراز منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص363–389.","url":""}]},{"id":"s6-947","number":947,"surah":6,"verses":[145],"verseLabel":"الأنعام: 145","question":"ما سرّ التعبير في قوله تعالى في الخنزير: ﴿فإنه رجس﴾، وإلى ماذا يعود الضمير؟","answer":"الأقرب أن الضمير يعود إلى لحم الخنزير، وقيل إلى الخنزير أو إلى المحرم المذكور؛ ووصفه بالرجس يبين خبثه ونجاسته المعنوية أو الحسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص363–389.","url":""}]},{"id":"s6-948","number":948,"surah":6,"verses":[145],"verseLabel":"الأنعام: 145","question":"لماذا وصف ما أهل لغير الله به بأنه ﴿فسقًا﴾؟","answer":"الفسق خروج عن طاعة الله، والذبيحة التي رُفع عليها اسم غيره مظهر عبادة وشرك؛ لذلك وصفها بالمصدر للمبالغة في قبحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص363–389.","url":""}]},{"id":"s6-949","number":949,"surah":6,"verses":[145],"verseLabel":"الأنعام: 145","question":"لماذا خُتم حكم المضطر بـ﴿فإن ربك غفور رحيم﴾؟","answer":"ذكر الربوبية يناسب رعاية المضطر، والمغفرة ترفع إثم المحظور، والرحمة أباحت له ما يحفظ حياته؛ بشرط ألا يكون باغيًا ولا متجاوزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص363–389.","url":""}]},{"id":"s6-950","number":950,"surah":6,"verses":[145],"verseLabel":"الأنعام: 145","question":"لماذا قُيّد الدم هنا بـ﴿مسفوحًا﴾، وجاء ذكر الدم مطلقًا في آية المائدة؟","answer":"آية الأنعام في مقام حصر المحرمات وتفصيل أحكامها، فقيدت الدم بالمسفوح لإخراج غير الجاري. أما آية المائدة فذكرت الدم ضمن أجناس المحرمات إجمالًا، وحُمل مطلقها على القيد المبين هنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص534.","url":""}]},{"id":"s6-951","number":951,"surah":6,"verses":[146],"verseLabel":"الأنعام: 146","question":"لماذا خص ﴿الذين هادوا﴾ بتحريم كل ذي ظفر؟","answer":"خُص اليهود لأن التحريم كان عقوبة لهم على بغيهم، لا حكمًا أصليًا عامًا في جميع الأمم؛ فالتخصيص يمهد لتعليل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص390–401.","url":""}]},{"id":"s6-952","number":952,"surah":6,"verses":[146],"verseLabel":"الأنعام: 146","question":"لماذا جُمعت شحوم البقر والغنم ثم استثنيت ثلاثة مواضع؟","answer":"عُممت الشحوم أولًا، ثم استثني ما حملته الظهور والحوايا وما اختلط بعظم؛ لتحديد مواضع العفو بدقة وإظهار شدة العقوبة مع بقاء ما يشق فصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص390–401.","url":""}]},{"id":"s6-953","number":953,"surah":6,"verses":[146],"verseLabel":"الأنعام: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك جزيناهم ببغيهم﴾، فجعل التحريم جزاء؟","answer":"جُعل التحريم جزاء لأنه عقوبة تشريعية على بغيهم؛ فسُلبوا بعض الطيبات التي كانت حلالًا لهم، والجزاء من جنس تعديهم للحدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص390–401.","url":""}]},{"id":"s6-954","number":954,"surah":6,"verses":[146],"verseLabel":"الأنعام: 146","question":"لماذا خُتمت بـ﴿وإنا لصادقون﴾؟","answer":"أكدت الخاتمة صدق الخبر ردًا على تكذيبهم وتحريفهم سبب التحريم؛ فالله صادق في أن هذه القيود جزاء بغيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص390–401.","url":""}]},{"id":"s6-955","number":955,"surah":6,"verses":[147],"verseLabel":"الأنعام: 147","question":"ما سرّ التعبير عند تكذيبهم بقوله تعالى: ﴿ربكم ذو رحمة واسعة﴾؟","answer":"ذكر الرحمة عند التكذيب ترغيب قبل الترهيب، وبيان أنه لا يعاجلهم بالعقوبة مع تكذيبهم؛ فالإمهال رحمة وليس دليل رضا أو عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص402–412.","url":""}]},{"id":"s6-956","number":956,"surah":6,"verses":[147],"verseLabel":"الأنعام: 147","question":"لماذا عبّر بـ﴿ذو رحمة﴾، لا: رحيم؟","answer":"﴿ذو رحمة﴾ تفيد اتصافه برحمة عظيمة واسعة ثابتة كأنها ملكه، وهي أنسب مع التصريح بسعتها من الوصف المفرد ﴿رحيم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص402–412.","url":""}]},{"id":"s6-957","number":957,"surah":6,"verses":[147],"verseLabel":"الأنعام: 147","question":"لماذا جمع بين سعة الرحمة وعدم رد البأس؟","answer":"جمعهما ليوازن بين الرجاء والخوف: رحمته واسعة تمهل وتفتح التوبة، لكن بأسه إذا نزل بالمجرمين لا يرده أحد؛ فلا اغترار بالإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص402–412.","url":""}]},{"id":"s6-958","number":958,"surah":6,"verses":[148],"verseLabel":"الأنعام: 148","question":"ما وجه احتجاج المشركين بقولهم: ﴿لو شاء الله ما أشركنا﴾، وكيف أبطل القرآن حجتهم؟","answer":"احتجوا بالمشيئة ليجعلوا وقوع الشرك والتحريم دليل رضا ويسقطوا المسؤولية. ورد القرآن بأن المكذبين قبلهم قالوا مثل ذلك ثم ذاقوا العذاب، وبأنهم لا يملكون علمًا وإنما يتبعون الظن.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص413–433.","url":""}]},{"id":"s6-959","number":959,"surah":6,"verses":[148],"verseLabel":"الأنعام: 148","question":"لماذا جمعوا أنفسهم وآباءهم وتحريمهم في حجة واحدة؟","answer":"جمعوا أفعالهم وآباءهم وتشريعاتهم ليصوروا واقعًا كاملًا زعموا أن المشيئة أجبرتهم عليه؛ فخلطوا بين وقوع الشيء بإذن الله الكوني ورضاه الشرعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص413–433.","url":""}]},{"id":"s6-960","number":960,"surah":6,"verses":[148],"verseLabel":"الأنعام: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى ذاقوا بأسنا﴾؟","answer":"الذوق أصله إدراك المطعوم مباشرة، فاستعير لمباشرة العذاب ومعاناة أثره؛ ليبين أن حجتهم لم تمنع عن السابقين بأس الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص413–433.","url":""}]},{"id":"s6-961","number":961,"surah":6,"verses":[148],"verseLabel":"الأنعام: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿هل عندكم من علم فتخرجوه لنا﴾؟","answer":"الاستفهام يتحداهم أن يأتوا بعلم موثوق ثم يظهروه، و﴿من﴾ تؤكد نفي أي قدر منه؛ فلا علم عندهم يمكن إخراجه حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص413–433.","url":""}]},{"id":"s6-962","number":962,"surah":6,"verses":[148],"verseLabel":"الأنعام: 148","question":"لماذا جمع بين ﴿الظن﴾ و﴿تخرصون﴾؟","answer":"الظن هو مستندهم غير اليقيني، والخرص هو ما يصوغونه بناء عليه من تقديرات وأكاذيب؛ فجمع فساد الأصل وفساد القول الناتج.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص413–433.","url":""}]},{"id":"s6-963","number":963,"surah":6,"verses":[149],"verseLabel":"الأنعام: 149","question":"ما سرّ تقديم ﴿لله﴾ في ﴿فلله الحجة البالغة﴾؟","answer":"تقديم ﴿لله﴾ يفيد الاختصاص: الحجة الكاملة له وحده، لا لمن يحتج بالظن على الشرك والمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص434–440.","url":""}]},{"id":"s6-964","number":964,"surah":6,"verses":[149],"verseLabel":"الأنعام: 149","question":"لماذا وُصفت الحجة بـ﴿البالغة﴾؟","answer":"البالغة هي التي تبلغ غايتها في البيان والإلزام وتقطع العذر؛ فقد وهب الاختيار وأرسل الرسل وبين الشرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص434–440.","url":""}]},{"id":"s6-965","number":965,"surah":6,"verses":[149],"verseLabel":"الأنعام: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿فلو شاء لهداكم أجمعين﴾ بعد رد احتجاجهم بالمشيئة؟","answer":"بيّن الفرق بين نوعي المشيئة: لو شاء الله هداية الإلجاء لهدى الجميع، لكنه شاء التكليف والاختيار وأقام الحجة؛ فلا يصح اتخاذ مشيئته عذرًا للمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص434–440.","url":""}]},{"id":"s6-966","number":966,"surah":6,"verses":[150],"verseLabel":"الأنعام: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿هلم شهداءكم﴾، دون أن يقال: أحضروا؟","answer":"﴿هلم﴾ اسم فعل يستدعي الحضور عاجلًا؛ ففيه تحد مباشر: أحضروا شهداءكم الذين يثبتون أن الله حرم هذا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص441–455.","url":""}]},{"id":"s6-967","number":967,"surah":6,"verses":[150],"verseLabel":"الأنعام: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن شهدوا فلا تشهد معهم﴾ مع بطلان شهادتهم؟","answer":"نهى عن موافقتهم لأن صدور الشهادة لا يمنحها صدقًا؛ فإن شهدوا بالباطل فلا يشاركهم الرسول ولا يقر دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص441–455.","url":""}]},{"id":"s6-968","number":968,"surah":6,"verses":[150],"verseLabel":"الأنعام: 150","question":"لماذا كرر النهي عن اتباع الأهواء؟","answer":"تكرر النهي لأن أهواءهم ظهرت هنا في باب التحليل والتحريم بعد ظهورها في الشرك وطلب الآيات؛ فكل صورة تحتاج تحذيرًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص441–455.","url":""}]},{"id":"s6-969","number":969,"surah":6,"verses":[150],"verseLabel":"الأنعام: 150","question":"لماذا خُتم وصفهم بـ﴿وهم بربهم يعدلون﴾ كما في أول السورة؟","answer":"أعاد ختام المطلع ليطوق السورة موضوعيًا: مع قيام دلائل الربوبية لا يزالون يسوون بربهم غيره في العبادة والتشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص441–455.","url":""}]},{"id":"s6-970","number":970,"surah":6,"verses":[151],"verseLabel":"الأنعام: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿تعالوا أتل ما حرم ربكم عليكم﴾، ثم بدأ بـ﴿ألا تشركوا﴾؟","answer":"﴿تعالوا﴾ دعوة إلى الارتفاع من افترائهم إلى حكم الله، و﴿أتل﴾ يدل على وحي محفوظ. وبدأ بتحريم الشرك لأنه أصل المحرمات وأساس قبول سائر الوصايا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص456–485.","url":""}]},{"id":"s6-971","number":971,"surah":6,"verses":[151],"verseLabel":"الأنعام: 151","question":"لماذا جاء بعد نهي الشرك قوله: ﴿وبالوالدين إحسانًا﴾ من غير فعل؟","answer":"التقدير: وأحسنوا بالوالدين إحسانًا؛ حُذف الفعل وأقيم المصدر مقامه ليعم وجوه البر ويؤكد لزوم الإحسان، مع الانتقال من النهي عن الشرك إلى الأمر بالحق الأعظم بعد حق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص456–485.","url":""}]},{"id":"s6-972","number":972,"surah":6,"verses":[151],"verseLabel":"الأنعام: 151","question":"ما سرّ التعبير في قوله تعالى في الفقر: ﴿نحن نرزقكم وإياهم﴾، وفي الإسراء: ﴿نحن نرزقهم وإياكم﴾؟","answer":"في الأنعام الفقر واقع بالآباء، فقدم ضمان رزقهم ﴿نرزقكم﴾ ثم الأولاد. وفي الإسراء الخوف من فقر متوقع بسبب الأولاد، فقدم رزقهم ﴿نرزقهم﴾ لإزالة موضع الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص456–485.","url":""}]},{"id":"s6-973","number":973,"surah":6,"verses":[151],"verseLabel":"الأنعام: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تقربوا الفواحش﴾، لا: لا تفعلوها؟","answer":"النهي عن القرب يسد كل الطرق والمقدمات المفضية إلى الفاحشة، وهو أبلغ من النهي عن فعلها بعد الوصول إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص456–485.","url":""}]},{"id":"s6-974","number":974,"surah":6,"verses":[151],"verseLabel":"الأنعام: 151","question":"لماذا جمع بين ﴿ما ظهر منها وما بطن﴾؟","answer":"الجمع يستوعب الفواحش المعلنة والمستترة، وأعمال الجوارح وخفايا القلوب؛ فلا يباح القبيح بخفائه ولا يقتصر النهي على المشهور.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص456–485.","url":""}]},{"id":"s6-975","number":975,"surah":6,"verses":[151],"verseLabel":"الأنعام: 151","question":"لماذا خُتمت الوصايا الأولى بـ﴿لعلكم تعقلون﴾؟","answer":"هذه الوصايا أصول يدرك العقل قبح أضدادها: الشرك والعقوق وقتل النفس والفواحش؛ فختمت بالدعوة إلى استعمال العقل في حفظها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص456–485.","url":""}]},{"id":"s6-976","number":976,"surah":6,"verses":[152],"verseLabel":"الأنعام: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تقربوا مال اليتيم﴾ كما قال في الفواحش؟","answer":"النهي عن القرب يمنع كل تصرف يعرض مال اليتيم للنقص، لا مجرد أكله؛ ثم استثنى التصرف الذي يحقق مصلحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص486–521.","url":""}]},{"id":"s6-977","number":977,"surah":6,"verses":[152],"verseLabel":"الأنعام: 152","question":"لماذا استثنى: ﴿إلا بالتي هي أحسن﴾، ولم يقل: إلا بالحسنى؟","answer":"﴿بالتي هي أحسن﴾ تطلب الخصلة أو الطريقة التي بلغت الغاية في حفظ المال وتنميته، لا مجرد طريقة حسنة مع وجود ما هو أصلح.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص486–521.","url":""}]},{"id":"s6-978","number":978,"surah":6,"verses":[152],"verseLabel":"الأنعام: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يبلغ أشده﴾، وما صورة بلوغ الأشد؟","answer":"الأشد كمال القوة والعقل والرشد، وصُوّر كغاية يبلغها اليتيم بعد تدرج؛ وعندها تنتهي الولاية ويُدفع إليه ماله إذا تحقق رشده.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص486–521.","url":""}]},{"id":"s6-979","number":979,"surah":6,"verses":[152],"verseLabel":"الأنعام: 152","question":"لماذا اعترض بقوله: ﴿لا نكلف نفسًا إلا وسعها﴾ بين وصايا المعاملات؟","answer":"الاعتراض يرفع الحرج في الكيل والميزان والقسط عما يقع بعد بذل الوسع من تفاوت لا يمكن ضبطه، من غير أن يبيح التساهل المتعمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص486–521.","url":""}]},{"id":"s6-980","number":980,"surah":6,"verses":[152],"verseLabel":"الأنعام: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو كان ذا قربى﴾، دون أن يقال: ولو كان قريبًا؟","answer":"﴿ذا قربى﴾ صاحب قرابة ثابتة، وهو أبلغ في تصوير قوة الصلة التي قد تحمل على المحاباة؛ ومع ذلك يجب العدل في القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص486–521.","url":""}]},{"id":"s6-981","number":981,"surah":6,"verses":[152],"verseLabel":"الأنعام: 152","question":"لماذا خُتمت الوصايا الثانية بـ﴿لعلكم تذكرون﴾؟","answer":"وصايا المعاملات معروفة الأصول لكن الشهوة والقرابة قد تنسي مقتضاها؛ فختمت بالتذكر ليستحضر المكلف العهد والعدل عند التطبيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص486–521.","url":""}]},{"id":"s6-982","number":982,"surah":6,"verses":[153],"verseLabel":"الأنعام: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿وأن هذا صراطي مستقيمًا﴾ بالإفراد، ثم ﴿ولا تتبعوا السبل﴾ بالجمع؟","answer":"أُفرد الصراط لأن الحق طريق واحد مستقيم، وجُمعت السبل لأن طرق البدع والضلال كثيرة متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص522–536.","url":""}]},{"id":"s6-983","number":983,"surah":6,"verses":[153],"verseLabel":"الأنعام: 153","question":"لماذا أضيف الصراط إلى الله: ﴿صراطي﴾؟","answer":"إضافته إلى الله تشريف وتعيين لمصدره: هذا طريقه الذي شرعه الموصل إليه، فلا يلتبس بطرق البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص522–536.","url":""}]},{"id":"s6-984","number":984,"surah":6,"verses":[153],"verseLabel":"الأنعام: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿فتفرق بكم عن سبيله﴾، فجعل السبل تفرق بالناس؟","answer":"صُورت السبل كقوى تسحب السائرين فتفرق الجماعة بعيدًا عن الطريق الواحد؛ والباء تجعل التفرق ملابسًا لهم ومؤثرًا في وحدتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص522–536.","url":""}]},{"id":"s6-985","number":985,"surah":6,"verses":[153],"verseLabel":"الأنعام: 153","question":"لماذا خُتمت الوصايا الثالثة بـ﴿لعلكم تتقون﴾؟","answer":"بعد العقل في الأصول والتذكر في المعاملات تأتي ثمرة التزام الطريق كله: التقوى التي تحفظ من السبل ومخالفة الوصايا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص522–536.","url":""}]},{"id":"s6-986","number":986,"surah":6,"verses":[154],"verseLabel":"الأنعام: 154","question":"لماذا بدأ بـ﴿ثم آتينا موسى الكتاب﴾ مع أن إيتاء موسى أسبق زمنًا؟","answer":"﴿ثم﴾ لترتيب الأخبار أو للانتقال الرتبي إلى شاهد آخر على تمام الحجة، لا للترتيب الزمني؛ فإيتاء موسى سابق معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص537–548.","url":""}]},{"id":"s6-987","number":987,"surah":6,"verses":[154],"verseLabel":"الأنعام: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿تمامًا على الذي أحسن﴾، ومن المراد؟","answer":"أي آتينا موسى الكتاب إتمامًا للنعمة على من أحسن، أو تمامًا على موسى الذي أحسن الطاعة؛ والموصول يعلق الفضل بصفة الإحسان مع احتمال الوجهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص537–548.","url":""}]},{"id":"s6-988","number":988,"surah":6,"verses":[154],"verseLabel":"الأنعام: 154","question":"لماذا جمع للكتاب: ﴿تفصيلًا لكل شيء وهدى ورحمة﴾؟","answer":"جمع وظائف الكتاب: يفصل ما تحتاجه الشريعة، ويهدي إلى الحق، ويرحم من اتبعه؛ فجمع البيان العلمي وأثره العملي والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص537–548.","url":""}]},{"id":"s6-989","number":989,"surah":6,"verses":[154],"verseLabel":"الأنعام: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿لعلهم بلقاء ربهم يؤمنون﴾ بتقديم ﴿بلقاء ربهم﴾؟","answer":"قُدّم ﴿بلقاء ربهم﴾ للاهتمام بموضع إيمانهم المقصود، ولأن إنكار البعث هو العلة التي يعالجها هدى الكتاب ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص537–548.","url":""}]},{"id":"s6-990","number":990,"surah":6,"verses":[155],"verseLabel":"الأنعام: 155","question":"لماذا تكرر: ﴿وهذا كتاب أنزلناه مبارك﴾ بعد الآية 92؟","answer":"تكرر التعريف بالكتاب لأن الآية 92 أثبتت بركته وصدقه ومهمته في إنذار أم القرى، وهنا جاءت بعد ذكر كتاب موسى لتقرر أن القرآن هو الكتاب المبارك الواجب اتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص549–555.","url":""}]},{"id":"s6-991","number":991,"surah":6,"verses":[155],"verseLabel":"الأنعام: 155","question":"لماذا فرع: ﴿فاتبعوه واتقوا﴾؟","answer":"الفاء تفرع الأمر على كونه كتابًا منزلًا مباركًا: مقتضى بركته وتنزيله اتباع أحكامه، واتقاء مخالفته والشرك به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص549–555.","url":""}]},{"id":"s6-992","number":992,"surah":6,"verses":[155],"verseLabel":"الأنعام: 155","question":"لماذا خُتمت بـ﴿لعلكم ترحمون﴾؟","answer":"الرجاء متعلق بالمخاطبين: اتبعوه واتقوا لتكونوا أهلًا لنيل الرحمة؛ فالرحمة ثمرة الاتباع والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص549–555.","url":""}]},{"id":"s6-993","number":993,"surah":6,"verses":[156],"verseLabel":"الأنعام: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تقولوا إنما أنزل الكتاب على طائفتين من قبلنا﴾؟","answer":"أنزل القرآن لقطع عذرهم أن الكتب السابقة نزلت على اليهود والنصارى وحدهم وأن العرب غافلون عن قراءتها وفهمها؛ فقد جاءهم كتاب بلغتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص556–564.","url":""}]},{"id":"s6-994","number":994,"surah":6,"verses":[156],"verseLabel":"الأنعام: 156","question":"لماذا سمّى اليهود والنصارى ﴿طائفتين﴾؟","answer":"الطائفة جماعة اجتمعت على مذهب، فالتعبير يجمع اليهود والنصارى باعتبار ملتيهما وكتابيهما، من غير تفصيل أسمائهما لأن المقصود حصر دعوى نزول الكتاب قبلهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص556–564.","url":""}]},{"id":"s6-995","number":995,"surah":6,"verses":[156],"verseLabel":"الأنعام: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿عن دراستهم لغافلين﴾، لا: عن كتبهم؟","answer":"جعلت الدراسة كناية عن معرفة ما في كتب الطائفتين واتباعه؛ فليست القضية بُعد الكتب وحده، بل الغفلة عن قراءتها وتعلمها ومضامينها، وقد أغناهم القرآن عن دراستها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص556–564.","url":""}]},{"id":"s6-996","number":996,"surah":6,"verses":[157],"verseLabel":"الأنعام: 157","question":"ما دلالة افتراضهم: ﴿لو أنا أنزل علينا الكتاب لكنا أهدى منهم﴾؟","answer":"هو تمنّ واعتذار يزعمون به أنهم لو خُصوا بكتاب لكانوا أشد اهتداء من اليهود والنصارى؛ فقطع نزول القرآن هذا العذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص565–581.","url":""}]},{"id":"s6-997","number":997,"surah":6,"verses":[157],"verseLabel":"الأنعام: 157","question":"ما سرّ وصف القرآن بقوله تعالى: ﴿بينة من ربكم وهدى ورحمة﴾؟","answer":"هو بيّنة لظهور حجته وإعجازه، وهدى بما يرشد إليه من الخير، ورحمة بما جاء به من شريعة سمحة ونعمة في الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص565–581.","url":""}]},{"id":"s6-998","number":998,"surah":6,"verses":[157],"verseLabel":"الأنعام: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن أظلم ممن كذب بآيات الله وصدف عنها﴾؟","answer":"الاستفهام للإنكار والنفي؛ فقد جمعوا تكذيب الآيات والإعراض الشديد عنها، أي رد الحق وترك الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص565–581.","url":""}]},{"id":"s6-999","number":999,"surah":6,"verses":[157],"verseLabel":"الأنعام: 157","question":"ما دلالة تكرار مادة الصدوف بعد ورودها في الآية 46؟","answer":"تكررت لتوكيد شدة إعراضهم، وللدلالة على أن سوء العذاب واقع بهم لا محالة بسبب ما ثبت واستمر منهم من الصدوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص565–581.","url":""}]},{"id":"s6-1000","number":1000,"surah":6,"verses":[158],"verseLabel":"الأنعام: 158","question":"ما دلالة حصر انتظارهم في مجيء الملائكة أو أمر الرب أو بعض آياته؟","answer":"يبين القصر أنهم لم يبق لهم بعد قيام الحجة إلا انتظار ما ينهي زمن الاختيار: الملائكة، أو أمر الله بالعذاب والقضاء، أو بعض أشراط الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص582–599.","url":""}]},{"id":"s6-1001","number":1001,"surah":6,"verses":[158],"verseLabel":"الأنعام: 158","question":"ما سرّ تكرار الفعل ﴿يأتي﴾ مع كل معطوف؟","answer":"كرر الفعل لاستقلال كل أمر وتمييزه، ولتصوير تجدد انتظارهم لكل واحد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص582–599.","url":""}]},{"id":"s6-1002","number":1002,"surah":6,"verses":[158],"verseLabel":"الأنعام: 158","question":"ما سرّ التعبير بقوله تعالى: ﴿بعض آيات ربك﴾ لا جميعها؟","answer":"المقصود بعض الآيات الحاسمة التي ينتهي بظهورها زمن قبول الإيمان، فلا يلزم مجيء جميع الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص582–599.","url":""}]},{"id":"s6-1003","number":1003,"surah":6,"verses":[158],"verseLabel":"الأنعام: 158","question":"ما سرّ عدم نفع الإيمان حينئذ لمن ﴿لم تكن آمنت من قبل أو كسبت في إيمانها خيرًا﴾؟","answer":"لأنه يصبح إيمان اضطرار ومشاهدة بعد انقضاء زمن التكليف؛ فلا ينفع من لم يسبق له إيمان، ولا من لم يضم إلى إيمانه عملًا صالحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص582–599.","url":""}]},{"id":"s6-1004","number":1004,"surah":6,"verses":[158],"verseLabel":"الأنعام: 158","question":"ما دلالة ختام الآية بقوله تعالى: ﴿قل انتظروا إنا منتظرون﴾؟","answer":"هو تهديد: انتظروا ما تتوقعونه من الآيات والعقاب، ونحن ننتظر وعد الله بنصر المؤمنين ووعيده للمكذبين؛ وحذف المتعلق ليشمل الأمرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص582–599.","url":""}]},{"id":"s6-1005","number":1005,"surah":6,"verses":[158],"verseLabel":"الأنعام: 158","question":"ما الفرق بين قوله تعالى: ﴿أو يأتي ربك﴾ وقوله في الفجر: ﴿وجاء ربك﴾ من جهة زمن المشهد؟","answer":"في الأنعام جاء المضارع في سياق ما ينتظره المكذبون قبل وقوعه؛ وفي الفجر جاء الماضي في عرض مشهد القيامة محقق الوقوع، فنُزّل المستقبل منزلة الواقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص352.","url":""}]},{"id":"s6-1006","number":1006,"surah":6,"verses":[159],"verseLabel":"الأنعام: 159","question":"ما سرّ الجمع بين قوله تعالى: ﴿فرقوا دينهم﴾ وقوله: ﴿وكانوا شيعًا﴾؟","answer":"الأول يصف تفريق الدين وخلط حقه بباطله، والثاني تحولهم جماعات يتبع بعضها بعضًا ويناصره؛ فجمع فساد المعتقد والتحزب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص600–613.","url":""}]},{"id":"s6-1007","number":1007,"surah":6,"verses":[159],"verseLabel":"الأنعام: 159","question":"ما دلالة خطاب النبي ﷺ بقوله تعالى: ﴿لست منهم في شيء﴾؟","answer":"هو براءة تامة من الذين فرقوا دينهم، وقطع لأي صلة دينية بمنهجهم، مع تحذير الأمة من طريقتهم؛ وحسابهم إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص600–613.","url":""}]},{"id":"s6-1008","number":1008,"surah":6,"verses":[159],"verseLabel":"الأنعام: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما أمرهم إلى الله ثم ينبئهم﴾؟","answer":"القصر يفوض جزاءهم إلى الله وحده، و«ثم» لتراخي يوم الحساب، والإنباء كناية عن إظهار أعمالهم ومعاقبتهم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص600–613.","url":""}]},{"id":"s6-1009","number":1009,"surah":6,"verses":[160],"verseLabel":"الأنعام: 160","question":"ما سرّ مجازاة الحسنة بعشر أمثالها والسيئة بمثلها؟","answer":"مضاعفة الحسنة فضل وإحسان، والاقتصار في السيئة على مثلها عدل؛ ولذلك لا يُظلم أحد بزيادة العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص614–625.","url":""}]},{"id":"s6-1010","number":1010,"surah":6,"verses":[160],"verseLabel":"الأنعام: 160","question":"ما سرّ تقديم ﴿له﴾ في قوله تعالى: ﴿فله عشر أمثالها﴾؟","answer":"قُدّم للاختصاص والاهتمام: جزاء صاحب الحسنة ثابت له، وفيه إشعار بمنزلته حتى نال هذا التضعيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص614–625.","url":""}]},{"id":"s6-1011","number":1011,"surah":6,"verses":[160],"verseLabel":"الأنعام: 160","question":"ما سرّ بناء ﴿فلا يجزى﴾ للمجهول في جزاء السيئة؟","answer":"لأن المقصود إبراز مقدار الجزاء وعدله، لا ذكر المجازي المعلوم من السياق؛ فالسيئة لا يقابلها إلا مثلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص614–625.","url":""}]},{"id":"s6-1012","number":1012,"surah":6,"verses":[160],"verseLabel":"الأنعام: 160","question":"ما مناسبة ختام الآية بقوله تعالى: ﴿وهم لا يظلمون﴾؟","answer":"يقرر عدل الجزاء: لا تُنقص حسنة ولا تُزاد سيئة على مثلها؛ فالتضعيف فضل، وعدم زيادة العقاب عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص614–625.","url":""}]},{"id":"s6-1013","number":1013,"surah":6,"verses":[160],"verseLabel":"الأنعام: 160","question":"ما الفرق بين قوله هنا: ﴿فله عشر أمثالها﴾، وقوله في البقرة: ﴿يضاعف﴾ من غير تقييد بالعشر؟","answer":"آية الأنعام تبين أصل الحد الأدنى العام لمضاعفة الحسنة، وآية البقرة في النفقة التي يزيد الله ثوابها أضعافًا كثيرة بحسب فضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص203.","url":""}]},{"id":"s6-1014","number":1014,"surah":6,"verses":[161],"verseLabel":"الأنعام: 161","question":"ما دلالة توكيد قوله تعالى: ﴿إنني هداني ربي﴾ بعد عرض ضلال المشركين؟","answer":"توالي المؤكدات يثبت هداية النبي ﷺ وثباته على الحق في مواجهة إنكار المشركين، ويغلق باب جدالهم في خاتمة السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1015","number":1015,"surah":6,"verses":[161],"verseLabel":"الأنعام: 161","question":"ما سرّ الجمع بين ﴿صراط مستقيم دينًا قيمًا ملة إبراهيم﴾؟","answer":"هو طريق لا عوج فيه، ودين بالغ الاستقامة قائم بمصالح أهله، وملة إبراهيم التي يعرف العرب وأهل الكتاب فضلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1016","number":1016,"surah":6,"verses":[161],"verseLabel":"الأنعام: 161","question":"ما سرّ اختيار ﴿قيمًا﴾ بعد قوله: ﴿صراط مستقيم﴾؟","answer":"«قيّمًا» أبلغ من تكرار الاستقامة؛ فهو يدل على شدتها وثباتها، وعلى قيام الدين بأمر الأمة وإصلاح دينها ودنياها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1017","number":1017,"surah":6,"verses":[161],"verseLabel":"الأنعام: 161","question":"ما سرّ وصف إبراهيم عليه السلام بـ﴿حنيفًا﴾ ثم نفي الشرك عنه؟","answer":"الحنيف مائل عن الأديان الباطلة إلى الحق، ثم جاء نفي الشرك ليقطع دعوى المشركين الانتساب إلى ملته ويؤكد خلوص توحيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1018","number":1018,"surah":6,"verses":[161],"verseLabel":"الأنعام: 161","question":"ما الفرق بين قوله في الأنعام: ﴿دينًا قيمًا﴾ وقوله في الفاتحة: ﴿الصراط المستقيم﴾؟","answer":"«المستقيم» وصف للصراط المطلوب بلا عوج، و«قيّمًا» وصف للدين بالمبالغة في الاستقامة وبقيامه بمصالح أهله؛ فلكل وصف جهة اقتضاها سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص402.","url":""}]},{"id":"s6-1019","number":1019,"surah":6,"verses":[162],"verseLabel":"الأنعام: 162","question":"ما سرّ الجمع بين ﴿صلاتي ونسكي ومحياي ومماتي﴾؟","answer":"جمع العبادة الخاصة وسائر النسك، ثم الحياة والموت وما يتصل بهما، ليدل على إخلاص العبد لله في عبادته وحياته ومآله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1020","number":1020,"surah":6,"verses":[162],"verseLabel":"الأنعام: 162","question":"ما سرّ تقديم الصلاة على النسك، والمحيا على الممات؟","answer":"قُدمت الصلاة لعظمها ولزومها كل يوم، بخلاف النسك المتعلق بعضه بالاستطاعة؛ وقُدم المحيا لأنه سابق للممات وميدان العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1021","number":1021,"surah":6,"verses":[162],"verseLabel":"الأنعام: 162","question":"ما سرّ الجمع بين الألوهية والربوبية في قوله تعالى: ﴿لله رب العالمين﴾؟","answer":"إفراد العبادة له يقتضيه كونه رب العالمين؛ فهو المستحق لها بما تفضل به من الخلق والرزق، وبيده الحياة والموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1022","number":1022,"surah":6,"verses":[163],"verseLabel":"الأنعام: 163","question":"ما دلالة مجيء قوله تعالى: ﴿لا شريك له﴾ بعد إعلان الإخلاص؟","answer":"تؤكد أن تخصيص الصلاة والنسك والمحيا والممات لله إخلاص لا يخالطه شرك، وتصرح بنفي كل شريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1023","number":1023,"surah":6,"verses":[163],"verseLabel":"الأنعام: 163","question":"ما سرّ بناء ﴿وبذلك أمرت﴾ للمجهول؟","answer":"حُذف الفاعل للعلم بأنه الله وشدة ظهوره، وللإيجاز، ولتوجيه الاهتمام إلى الأمر نفسه: إخلاص العبادة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1024","number":1024,"surah":6,"verses":[163],"verseLabel":"الأنعام: 163","question":"ما المراد بقوله تعالى: ﴿وأنا أول المسلمين﴾ مع سبق الأنبياء عليهم السلام؟","answer":"المراد المبادرة والسبق في الإسلام من هذه الأمة؛ فهي أولية استجابة في قومه وأمته، لا نفي إسلام الأنبياء قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص626–647.","url":""}]},{"id":"s6-1025","number":1025,"surah":6,"verses":[164],"verseLabel":"الأنعام: 164","question":"ما سرّ تقديم ﴿غير الله﴾ في قوله تعالى: ﴿أغير الله أبغي ربًا وهو رب كل شيء﴾؟","answer":"قُدّم لأنه موضع الإنكار والتوبيخ: المنكر طلب رب غير الله مع أنه رب كل شيء؛ وفيه عناية بإبطال المعبود الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص648–661.","url":""}]},{"id":"s6-1026","number":1026,"surah":6,"verses":[164],"verseLabel":"الأنعام: 164","question":"ما دلالة قوله تعالى: ﴿ولا تكسب كل نفس إلا عليها﴾؟","answer":"كل نفس مختصة بكسبها وتبعته، فلا يتجاوز كسبها إلى غيرها؛ وجاء «عليها» لأن المقام في تبعة العمل ومؤاخذته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص648–661.","url":""}]},{"id":"s6-1027","number":1027,"surah":6,"verses":[164],"verseLabel":"الأنعام: 164","question":"ما سرّ تصوير المسؤولية بقوله تعالى: ﴿ولا تزر وازرة وزر أخرى﴾؟","answer":"استُعير الوزر، وهو الحمل الثقيل، للإثم؛ فصورت الآية الذنب حملًا لا تحمله نفس عن أخرى، تأكيدًا للمسؤولية الفردية وعدل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص648–661.","url":""}]},{"id":"s6-1028","number":1028,"surah":6,"verses":[164],"verseLabel":"الأنعام: 164","question":"ما سرّ تقديم ﴿إلى ربكم﴾ في قوله تعالى: ﴿ثم إلى ربكم مرجعكم﴾؟","answer":"قُدّم للاهتمام والاختصاص: المرجع النهائي إلى الله وحده، وفي إضافة الرب إليهم تذكير بسلطانه ووعد ووعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص648–661.","url":""}]},{"id":"s6-1029","number":1029,"surah":6,"verses":[164],"verseLabel":"الأنعام: 164","question":"ما دلالة قوله تعالى: ﴿فينبئكم بما كنتم فيه تختلفون﴾؟","answer":"الإنباء إظهار لحقيقة ما اختلفوا فيه وتمييز للحق من الباطل يوم الرجوع، ويتبعه الجزاء؛ والفاء تربطه بالمرجع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص648–661.","url":""}]},{"id":"s6-1030","number":1030,"surah":6,"verses":[165],"verseLabel":"الأنعام: 165","question":"ما مناسبة ختام السورة بقوله تعالى: ﴿جعلكم خلائف الأرض﴾؟","answer":"بعد تقرير الرجوع والحساب ذكّرهم بنعمة تمكينهم واستخلاف بعضهم بعد بعض؛ ليعلموا أن مقامهم عارض وأن التكليف يعقبه الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص662–679.","url":""}]},{"id":"s6-1031","number":1031,"surah":6,"verses":[165],"verseLabel":"الأنعام: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿ورفع بعضكم فوق بعض درجات﴾؟","answer":"رفع الدرجات استعارة لتفاوت الناس في الفضل والغنى ونحوهما؛ والغرض العبرة وعدم الاغترار وشكر النعمة بالرفق والإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص662–679.","url":""}]},{"id":"s6-1032","number":1032,"surah":6,"verses":[165],"verseLabel":"الأنعام: 165","question":"ما سرّ تعليل التفاوت بقوله تعالى: ﴿ليبلوكم فيما آتاكم﴾؟","answer":"يبين أن تفاوت العطايا امتحان: ليظهر شكر من أُعطي وصبر من قُدّر عليه، ويحاسب كل إنسان على ما آتاه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص662–679.","url":""}]},{"id":"s6-1033","number":1033,"surah":6,"verses":[165],"verseLabel":"الأنعام: 165","question":"ما سرّ وصف العقاب بالسرعة مع تأخره أحيانًا؟","answer":"استعيرت السرعة لعدم التردد وكمال القدرة حين يحين وقت العقاب؛ فليس المراد وجوب وقوعه فورًا في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص662–679.","url":""}]},{"id":"s6-1034","number":1034,"surah":6,"verses":[165],"verseLabel":"الأنعام: 165","question":"ما سرّ الجمع في الختام بين ﴿سريع العقاب﴾ و﴿غفور رحيم﴾؟","answer":"جمع الوعيد والوعد ليبقى العبد بين الخوف والرجاء؛ وقُدم العقاب لسياق محاجة الكافرين، ثم رُجحت الرحمة بتوكيد ﴿لغفور﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص662–679.","url":""}]},{"id":"s6-1035","number":1035,"surah":6,"verses":[165],"verseLabel":"الأنعام: 165","question":"ما سرّ الإضمار في قوله تعالى: ﴿وإنه لغفور رحيم﴾ بعد قوله: ﴿إن ربك سريع العقاب﴾؟","answer":"الإضمار هو الأصل بعد إظهار الاسم، وفيه حسن اتصال الجملتين وقوة تعالقهما وتجنب التكرار؛ وزيدت اللام ترجيحًا لجانب المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص662–679.","url":""}]},{"id":"s7-1","number":1,"surah":7,"verses":[1],"verseLabel":"الأعراف: السورة","question":"ما مناسبة مجيء سورة الأعراف بعد الأنعام، وكيف تفصل ما أُجمل فيها؟","answer":"تأتي الأعراف بعد الأنعام لتفصيل ما أُجمل فيها من أحوال الأمم والرسل وقصة آدم وإبليس ومشاهد الرحمة والعذاب؛ فكانت بسطًا لمقاصد سبقتها إجمالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص198–199.","url":""}]},{"id":"s7-2","number":2,"surah":7,"verses":[1],"verseLabel":"الأعراف: 1","question":"ما سرّ افتتاح السورة بالحروف المقطعة ﴿المص﴾ وزيادة الصاد على ﴿الم﴾؟","answer":"الحروف المقطعة تسترعي السمع وتنبه إلى أن القرآن مؤلف من جنس حروف العرب مع عجزهم عن معارضته؛ وزيادة الصاد مما اختص به المطلع، وعلم تعيين سرها عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-3","number":3,"surah":7,"verses":[1,2],"verseLabel":"الأعراف: 1–2","question":"ما سرّ وصل الحروف المقطعة مباشرة بقوله تعالى: ﴿كتاب أنزل إليك﴾؟","answer":"وصلت الحروف بالكتاب لإبراز الصلة بينها وبين القرآن المعجز المؤلف منها، وللانتقال من التنبيه إلى المقصود: الكتاب المنزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-4","number":4,"surah":7,"verses":[2],"verseLabel":"الأعراف: 2","question":"ما سرّ تنكير ﴿كتاب﴾؟","answer":"نُكّر ﴿كتاب﴾ للتعظيم: أي كتاب عظيم الشأن، لا كتابًا من جنس كتب البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-5","number":5,"surah":7,"verses":[2],"verseLabel":"الأعراف: 2","question":"ما سرّ بناء ﴿أنزل إليك﴾ للمجهول؟","answer":"بُني للمجهول للعلم بأن المنزل هو الله، وللاهتمام بالكتاب وإنزاله، مع جريان الأسلوب على سنن الكبرياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-6","number":6,"surah":7,"verses":[2],"verseLabel":"الأعراف: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا يكن في صدرك حرج منه﴾، دون أن يقال: فلا تحرج منه؟","answer":"نُفي وجود الحرج في الصدر نفسه، وهو أبلغ من مجرد النهي عن التحَرّج؛ إذ يصور الصدر منشرحًا لا محل فيه لضيق من التكذيب أو التبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-7","number":7,"surah":7,"verses":[2],"verseLabel":"الأعراف: 2","question":"لماذا جعل الحرج ﴿في الصدر﴾؟","answer":"خُص الصدر لأنه موضع ما يعرض للنفس من الضيق والشك، فجعل تعلق الحرج به كناية عن الضيق النفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-8","number":8,"surah":7,"verses":[2],"verseLabel":"الأعراف: 2","question":"ما سرّ تقديم ﴿في صدرك﴾ على اسم ﴿يكن﴾؟","answer":"قُدّم ﴿في صدرك﴾ للاهتمام بصدر الرسول ﷺ، ولتقوية معنى ألا يكون محلًا لأي حرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-9","number":9,"surah":7,"verses":[2],"verseLabel":"الأعراف: 2","question":"إلى ماذا يعود الضمير في ﴿منه﴾: إلى الكتاب أم إلى الإنذار؟","answer":"يحتمل عوده إلى الكتاب، وهو الأقرب لفظًا، أي لا يكن حرج بسببه أو من تبليغه؛ ويدخل فيه الإنذار الذي أنزل لأجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-10","number":10,"surah":7,"verses":[2],"verseLabel":"الأعراف: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿لتنذر به وذكرى للمؤمنين﴾، فعبّر عن الإنذار بالفعل وعن التذكير بالاسم؟","answer":"جاء الإنذار فعلًا لتجدده وتعلقه بالبلاغ، وجاءت ﴿ذكرى﴾ اسمًا لثبوت كون الكتاب تذكرة للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-11","number":11,"surah":7,"verses":[2],"verseLabel":"الأعراف: 2","question":"لماذا خُص المؤمنون بالذكرى مع أن الكتاب أُنزل للناس؟","answer":"خُصوا لأنهم المنتفعون بالذكرى قبولًا وامتثالًا، وإن كان الإنذار بالكتاب أعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–704.","url":""}]},{"id":"s7-12","number":12,"surah":7,"verses":[3],"verseLabel":"الأعراف: 3","question":"لماذا انتقل من خطاب النبي في ﴿إليك﴾ إلى خطاب الناس: ﴿اتبعوا ما أنزل إليكم﴾؟","answer":"انتقل من خطاب الرسول ﷺ متلقي الكتاب إلى خطاب الناس المكلفين باتباعه؛ فالتبليغ للنبي والاتباع للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص705–716.","url":""}]},{"id":"s7-13","number":13,"surah":7,"verses":[3],"verseLabel":"الأعراف: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿ما أنزل إليكم من ربكم﴾، دون أن يقال: اتبعوا الكتاب؟","answer":"عبّر بالموصول ليعلق وجوب الاتباع بوصف الإنزال، ويشمل كل ما أنزله الله، لا مجرد اسم الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص705–716.","url":""}]},{"id":"s7-14","number":14,"surah":7,"verses":[3],"verseLabel":"الأعراف: 3","question":"لماذا اختير اسم الرب في ﴿من ربكم﴾؟","answer":"اختير ﴿ربكم﴾ لاستمالتهم إلى الاتباع بتذكيرهم بأن المنزل مربيهم والمنعم عليهم والعالم بمصالحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص705–716.","url":""}]},{"id":"s7-15","number":15,"surah":7,"verses":[3],"verseLabel":"الأعراف: 3","question":"لماذا قابل اتباع الوحي بقوله: ﴿ولا تتبعوا من دونه أولياء﴾؟","answer":"قوبل الأمر والنهي ليحصر طريق الهداية في اتباع الوحي وينفي اتباع كل ولاية تخالفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص705–716.","url":""}]},{"id":"s7-16","number":16,"surah":7,"verses":[3],"verseLabel":"الأعراف: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿من دونه أولياء﴾، دون أن يقال: غيره؟","answer":"﴿من دونه﴾ تصور اتخاذ الأولياء في مرتبة أدنى ومجاوزة لولاية الله، وهي أبلغ في ذم الشرك من «غيره».","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص705–716.","url":""}]},{"id":"s7-17","number":17,"surah":7,"verses":[3],"verseLabel":"الأعراف: 3","question":"لماذا جُمعت ﴿أولياء﴾؟","answer":"جُمعت لتعدد المعبودات والرؤساء والشياطين الذين يتخذهم الناس أولياء من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص705–716.","url":""}]},{"id":"s7-18","number":18,"surah":7,"verses":[3],"verseLabel":"الأعراف: 3","question":"لماذا خُتمت الآية بـ﴿قليلًا ما تذكرون﴾؟","answer":"الختام توبيخ على قلة اتعاظهم؛ فلو تذكروا نعمة الرب وحقيقة الوحي لما اتبعوا أولياء من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص705–716.","url":""}]},{"id":"s7-19","number":19,"surah":7,"verses":[3],"verseLabel":"الأعراف: 3","question":"ما سرّ التعبير هنا في قوله تعالى ﴿تذكرون﴾، وفي الآية 10 ﴿تشكرون﴾؟","answer":"جاء ﴿تذكرون﴾ بعد الأمر باتباع الوحي لأن المطلوب الاتعاظ، و﴿تشكرون﴾ بعد التمكين والمعايش لأنها نعم تستوجب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص705–716؛ 757–766.","url":""}]},{"id":"s7-20","number":20,"surah":7,"verses":[4],"verseLabel":"الأعراف: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿وكم من قرية أهلكناها﴾، والمراد أهلها؟","answer":"أُطلقت القرية وأريد أهلها بعلاقة المحل والحال؛ وفي ذلك تصوير للهلاك مستوعبًا المكان ومن فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-21","number":21,"surah":7,"verses":[4],"verseLabel":"الأعراف: 4","question":"لماذا اختيرت ﴿كم﴾ الخبرية؟","answer":"﴿كم﴾ الخبرية للتكثير، فتستحضر كثرة القرى الهالكة للتهديد والعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-22","number":22,"surah":7,"verses":[4],"verseLabel":"الأعراف: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿فجاءها بأسنا﴾ بعد قوله: ﴿أهلكناها﴾، مع أن مجيء البأس قبل الهلاك؟","answer":"الفاء للترتيب الذكري أو لتفصيل كيفية الإهلاك؛ فالإهلاك حكم مجمل، ثم بيّن أن البأس جاءها فكان به الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-23","number":23,"surah":7,"verses":[4],"verseLabel":"الأعراف: 4","question":"لماذا صُوّر البأس بأنه يأتي القرية؟","answer":"شُبه البأس بوافد يأتي القرية ويداهمها، تجسيمًا لشدة وقوعه ومباغتته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-24","number":24,"surah":7,"verses":[4],"verseLabel":"الأعراف: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿بياتًا أو هم قائلون﴾، فعبّر مرة بالمصدر ومرة بالجملة؟","answer":"﴿بياتًا﴾ مصدر وقع حالًا يفيد الإيجاز، و﴿هم قائلون﴾ جملة حالية صورت هيئتهم المستقرة وقت القيلولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-25","number":25,"surah":7,"verses":[4],"verseLabel":"الأعراف: 4","question":"لماذا اختير وقتا الليل والقيلولة لنزول البأس؟","answer":"لأنهما وقتا سكون وغفلة واطمئنان، فيكون مجيء البأس فيهما أشد مباغتة وأوقع في التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-26","number":26,"surah":7,"verses":[5],"verseLabel":"الأعراف: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿فما كان دعواهم﴾، وسمّى اعترافهم دعوى؟","answer":"الدعوى هنا ما دعوه وكرروه عند البأس؛ فسمي اعترافهم قولًا يدعونه بعد بطلان دعاواهم السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-27","number":27,"surah":7,"verses":[5],"verseLabel":"الأعراف: 5","question":"لماذا جاء التعبير بطريق القصر: ﴿إلا أن قالوا إنا كنا ظالمين﴾؟","answer":"القصر يصور انقطاع كل حجة؛ فلم يبق عند معاينة البأس إلا الاعتراف بالظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-28","number":28,"surah":7,"verses":[5],"verseLabel":"الأعراف: 5","question":"لماذا أكدوا اعترافهم بـ﴿إنّا﴾؟","answer":"أكدوا بـ﴿إنّا﴾ لأن المقام إقرار حاسم بعد طول إنكار، فثبتوا الظلم على أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-29","number":29,"surah":7,"verses":[5],"verseLabel":"الأعراف: 5","question":"ما دلالة اعترافهم بصيغة ﴿كنا ظالمين﴾ بدلًا من: ظلمنا؟","answer":"تدل ﴿كان﴾ مع اسم الفاعل على ثبوت الظلم واستمراره في ماضيهم، لا وقوع فعل عابر مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص717–728.","url":""}]},{"id":"s7-30","number":30,"surah":7,"verses":[6],"verseLabel":"الأعراف: 6","question":"لماذا أكد السؤال مرتين: ﴿فلنسألن الذين أرسل إليهم ولنسألن المرسلين﴾؟","answer":"توكيد السؤال يحقق وقوع الحساب، ويشمل سؤال الأمم عن إجابة الرسل وسؤال الرسل عن التبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-31","number":31,"surah":7,"verses":[6],"verseLabel":"الأعراف: 6","question":"ما سرّ تقديم سؤال الأمم على سؤال المرسلين؟","answer":"قُدمت الأمم لأن السياق في تهديد المكذبين، ولأن سؤالهم عن الاستجابة هو المقصود الأول في المحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-32","number":32,"surah":7,"verses":[6],"verseLabel":"الأعراف: 6","question":"ما سرّ التعبير في قوله تعالى عن الأمم: ﴿الذين أرسل إليهم﴾، دون أن يقال: المرسل إليهم؟","answer":"جاءت صلة الموصول فعلية لتستحضر واقعة إرسال الرسل إليهم وما ترتب عليها، وتعينهم بهذه الصفة موضعًا للسؤال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-33","number":33,"surah":7,"verses":[6],"verseLabel":"الأعراف: 6","question":"لماذا جُمعت نون التوكيد واللام في الفعلين؟","answer":"اللام موطئة للقسم والنون الثقيلة تؤكد الفعل؛ فاجتماعهما يقرر حتمية السؤال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-34","number":34,"surah":7,"verses":[7],"verseLabel":"الأعراف: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿فلنقصن عليهم بعلم﴾، والله يعلم أخبارهم قبل سؤالهم؟","answer":"ليس القص لاكتساب علم، بل لإظهار علم الله المحيط وإقامة الحجة عليهم بإخبارهم بأعمالهم على حقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-35","number":35,"surah":7,"verses":[7],"verseLabel":"الأعراف: 7","question":"لماذا عُدّي القص بـ﴿على﴾؟","answer":"عُدي بـ﴿على﴾ لتضمينه معنى الإلقاء أو الإخبار المتمكن، فكأن أخبار أعمالهم تلقى عليهم إلزامًا للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-36","number":36,"surah":7,"verses":[7],"verseLabel":"الأعراف: 7","question":"لماذا زيد قيد ﴿بعلم﴾ مع أن قصص الله لا يكون إلا بعلم؟","answer":"القيد يقرر أن القص قائم على علم محيط لا على شهادة ناقصة أو خبر منقول، وفيه تمام العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-37","number":37,"surah":7,"verses":[7],"verseLabel":"الأعراف: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كنا غائبين﴾ بصيغة الجمع والماضي؟","answer":"صيغة الجمع للتعظيم، والماضي يدل على ثبوت انتفاء الغيبة في كل ما مضى؛ فلم يغب عن علمه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-38","number":38,"surah":7,"verses":[8],"verseLabel":"الأعراف: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿والوزن يومئذ الحق﴾، وما الذي يوزن؟","answer":"الوزن يوم القيامة عدل حق؛ وتوزن الأعمال أو صحائفها أو أصحابها، والمقصود ثبوت الميزان مع احتمال هذه الأقوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-39","number":39,"surah":7,"verses":[8],"verseLabel":"الأعراف: 8","question":"لماذا عُرّف ﴿الوزن﴾ و﴿الحق﴾؟","answer":"تعريفهما يفيد أن الوزن المعهود يومئذ هو الوزن الحق الكامل الذي لا يداخله باطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-40","number":40,"surah":7,"verses":[8],"verseLabel":"الأعراف: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿ثقلت موازينه﴾ بالجمع؟","answer":"جمع الموازين باعتبار تعدد الموزونات أو الصحائف أو موازين الخلق، مع اتحاد حقيقة العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-41","number":41,"surah":7,"verses":[8],"verseLabel":"الأعراف: 8","question":"لماذا أظهر ضمير الفصل: ﴿فأولئك هم المفلحون﴾؟","answer":"ضمير الفصل يقوي الحكم ويفيد القصر: أصحاب الموازين الثقيلة هم المحققون للفلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-42","number":42,"surah":7,"verses":[9],"verseLabel":"الأعراف: 9","question":"لماذا قابل ثقل الموازين بخفتها، ولم يقل: ومن لم تثقل؟","answer":"صرح بالخفة لتحقيق المقابلة وتصوير حال الفريقين في الميزان، وهو أبلغ من نفي الثقل وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-43","number":43,"surah":7,"verses":[9],"verseLabel":"الأعراف: 9","question":"ما سرّ التعبير في قوله تعالى عن أصحاب الموازين الخفيفة: ﴿خسروا أنفسهم﴾؟","answer":"جعل أنفسهم رأس مالهم، فلما أوردوها موارد العذاب كانوا كمن أضاع رأس ماله وخسر كل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-44","number":44,"surah":7,"verses":[9],"verseLabel":"الأعراف: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كانوا بآياتنا يظلمون﴾ بتقديم ﴿بآياتنا﴾؟","answer":"قُدّم ﴿بآياتنا﴾ للاهتمام بمتعلق ظلمهم وتشنيع الجناية؛ فالظلم واقع بآيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-45","number":45,"surah":7,"verses":[9],"verseLabel":"الأعراف: 9","question":"لماذا عُدّي الظلم بالباء في ﴿بآياتنا يظلمون﴾؟","answer":"الباء للسببية أو الملابسة: خسروا بسبب ظلمهم المتعلق بالآيات، أي جحودها ووضعها في غير موضع التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729–756.","url":""}]},{"id":"s7-46","number":46,"surah":7,"verses":[10],"verseLabel":"الأعراف: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد مكناكم في الأرض﴾، دون أن يقال: أسكناكم؟","answer":"التمكين أوسع من الإسكان؛ فهو جعل الأرض قرارًا مع القدرة على التصرف والانتفاع بأسباب العيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص757–766.","url":""}]},{"id":"s7-47","number":47,"surah":7,"verses":[10],"verseLabel":"الأعراف: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿وجعلنا لكم فيها معايش﴾، فكرر معنى المكان بـ﴿فيها﴾؟","answer":"ذُكرت ﴿فيها﴾ لتوكيد أن المعايش مهيأة لهم في الأرض نفسها، وربط النعمة بمحل التمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص757–766.","url":""}]},{"id":"s7-48","number":48,"surah":7,"verses":[10],"verseLabel":"الأعراف: 10","question":"لماذا جُمعت ﴿معايش﴾؟","answer":"جُمعت لتنوع أسباب العيش من طعام وشراب وتجارة وصناعة وسائر المنافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص757–766.","url":""}]},{"id":"s7-49","number":49,"surah":7,"verses":[10],"verseLabel":"الأعراف: 10","question":"لماذا خُتمت بـ﴿قليلًا ما تشكرون﴾، لا: تذكرون كما في الآية 3؟","answer":"لأن المقام تعداد نعم التمكين والمعايش فناسبه الشكر؛ أما الآية 3 فمقام أمر ونهي يناسب التذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص757–766.","url":""}]},{"id":"s7-50","number":50,"surah":7,"verses":[11],"verseLabel":"الأعراف: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿خلقناكم ثم صورناكم ثم قلنا للملائكة﴾ مع أن السجود كان لآدم قبل خلق ذريته؟","answer":"الخطاب للذرية لأن خلق أصلهم آدم وتصويره نعمة جارية عليهم، أو لأنهم مقدرون في أصله؛ و﴿ثم﴾ لترتيب الرتب والأخبار لا التراخي الزمني في كل فرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص767–777.","url":""}]},{"id":"s7-51","number":51,"surah":7,"verses":[11],"verseLabel":"الأعراف: 11","question":"ما الفرق بين الخلق والتصوير في الآية؟","answer":"الخلق إيجاد الذات وأصل البنية، والتصوير إعطاؤها صورتها وهيئتها المميزة بعد ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص767–777.","url":""}]},{"id":"s7-52","number":52,"surah":7,"verses":[11],"verseLabel":"الأعراف: 11","question":"لماذا تكررت ﴿ثم﴾ مرتين؟","answer":"تفيد الأولى تفاوت الرتبة بين أصل الخلق والتصوير، والثانية الانتقال إلى مشهد الأمر بالسجود وتعظيم شأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص767–777.","url":""}]},{"id":"s7-53","number":53,"surah":7,"verses":[11],"verseLabel":"الأعراف: 11","question":"لماذا أُمر الملائكة بالسجود لآدم بعد ذكر خلق البشر جميعًا؟","answer":"ذكر خلق البشر قبل سجود الملائكة لأصلهم تذكير بأن تكريم آدم بالسجود تكريم لذريته ونعمة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص767–777.","url":""}]},{"id":"s7-54","number":54,"surah":7,"verses":[11],"verseLabel":"الأعراف: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿فسجدوا إلا إبليس﴾ مع أن إبليس ليس من الملائكة؟","answer":"الاستثناء متصل باعتبار أن إبليس كان مأمورًا مع الملائكة وفي جماعتهم، وإن لم يكن من جنسهم؛ أو منقطع على أصل جنسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص767–777.","url":""}]},{"id":"s7-55","number":55,"surah":7,"verses":[11],"verseLabel":"الأعراف: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿لم يكن من الساجدين﴾، دون أن يقال: فلم يسجد؟","answer":"الاسمية مع ﴿يكن﴾ تنفي اتصافه بالسجود وانضمامه إلى زمرة الساجدين، وهي أبلغ من الإخبار عن واقعة واحدة بأنه لم يسجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص767–777.","url":""}]},{"id":"s7-56","number":56,"surah":7,"verses":[12],"verseLabel":"الأعراف: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿ما منعك ألا تسجد﴾، وظاهر الكلام أن المتوقع: أن تسجد؟","answer":"في ﴿ألا تسجد﴾ وجوه؛ منها أن «لا» زائدة لتوكيد النفي، أو أن المعنى: ما منعك فحملك على ألا تسجد؛ والمقصود إنكار امتناعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص778–791.","url":""}]},{"id":"s7-57","number":57,"surah":7,"verses":[12],"verseLabel":"الأعراف: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ أمرتك﴾، فذكّر إبليس بالأمر لا بفضل آدم؟","answer":"ذكر الأمر لأن موجب السجود هو امتثال أمر الله، لا أن يزن إبليس فضل آدم بقياسه الفاسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص778–791.","url":""}]},{"id":"s7-58","number":58,"surah":7,"verses":[12],"verseLabel":"الأعراف: 12","question":"ما دلالة جواب إبليس بقوله: ﴿أنا خير منه﴾ بدل التصريح بما منعه؟","answer":"ذكر علة امتناعه التي توهمها: ادعاء الخيرية؛ فكأن جوابه كشف أن الكبر والقياس الفاسد هما المانع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص778–791.","url":""}]},{"id":"s7-59","number":59,"surah":7,"verses":[12],"verseLabel":"الأعراف: 12","question":"ما وجه فساد قياس إبليس النار بالطين في قوله: ﴿خلقتني من نار وخلقته من طين﴾؟","answer":"قاس أصل النار بأصل الطين فتوهم شرف النار، وأغفل أن الفضل بطاعة الله واصطفائه لا بمادة الخلق؛ فكان قياسه فاسدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص778–791.","url":""}]},{"id":"s7-60","number":60,"surah":7,"verses":[12],"verseLabel":"الأعراف: 12","question":"لماذا كرر فعل الخلق في الطرفين؟","answer":"تكرار ﴿خلقت﴾ أبرز مقابلة الأصلين في حجته، وأكد أن كليهما مخلوق لله؛ وهو ما يهدم دعوى الاستحقاق الذاتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص778–791.","url":""}]},{"id":"s7-61","number":61,"surah":7,"verses":[12],"verseLabel":"الأعراف: 12","question":"ما سرّ تقديم خلق إبليس على خلق آدم في حجته؟","answer":"بدأ بنفسه لأن كلامه صادر عن العجب وتقديم الذات، ولأن غرضه إثبات ما زعمه من خيريته قبل الانتقاص من آدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص778–791.","url":""}]},{"id":"s7-62","number":62,"surah":7,"verses":[12],"verseLabel":"الأعراف: 12","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿ما منعك﴾، وحذف النداء والاسم، بينما قال في ص: ﴿يا إبليس ما منعك﴾، وفي الحجر: ﴿يا إبليس ما لك﴾؟","answer":"قرب ذكر إبليس في الأعراف من الخطاب فحسن حذف النداء والاسم؛ وفي ص والحجر فصلت زيادة في وصف فعله، فأعيد اسمه بالنداء.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-63","number":63,"surah":7,"verses":[13],"verseLabel":"الأعراف: 13","question":"لماذا كان الجزاء: ﴿فاهبط منها﴾؟","answer":"كان الهبوط جزاء مناسبًا لاستكباره؛ فمن طلب العلو بغير حق أُنزل من المنزلة التي كان فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص792–807.","url":""}]},{"id":"s7-64","number":64,"surah":7,"verses":[13],"verseLabel":"الأعراف: 13","question":"إلى ماذا يعود الضمير في ﴿منها﴾: إلى الجنة أم السماء أم المنزلة؟","answer":"يحتمل عوده إلى الجنة أو السماء أو المنزلة؛ ويجمعها معنى الإخراج من مقام الكرامة والعلو الذي كان فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص792–807.","url":""}]},{"id":"s7-65","number":65,"surah":7,"verses":[13],"verseLabel":"الأعراف: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿فما يكون لك أن تتكبر فيها﴾، لا: لا تتكبر؟","answer":"التركيب ينفي استحقاقه للتكبر وإمكان قبوله منه في ذلك المقام، وهو أبلغ من مجرد النهي: لا تتكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص792–807.","url":""}]},{"id":"s7-66","number":66,"surah":7,"verses":[13],"verseLabel":"الأعراف: 13","question":"لماذا كرر الأمر بالخروج بعد الهبوط: ﴿فاخرج﴾؟","answer":"الهبوط إنزال من المرتبة أو المكان، والخروج طرد وإبعاد تام؛ فتكرر الأمر لتقرير نوعي العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص792–807.","url":""}]},{"id":"s7-67","number":67,"surah":7,"verses":[13],"verseLabel":"الأعراف: 13","question":"لماذا خُتم الحكم بـ﴿إنك من الصاغرين﴾، لا: من المتكبرين؟","answer":"قوبل تكبره بالصغار؛ فجزاء من طلب الكبر أن يلحقه الذل والهوان، وفي الوصف حكم ثابت لا فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص792–807.","url":""}]},{"id":"s7-68","number":68,"surah":7,"verses":[14],"verseLabel":"الأعراف: 14","question":"ما دلالة طلب إبليس الإنظار إلى يوم البعث بدل طلب المغفرة؟","answer":"طلب البقاء ليتمكن من إغواء ذرية آدم ويتفادى الموت إلى البعث، ولم يتجه إلى التوبة لأن الكبر والإصرار استوليا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-69","number":69,"surah":7,"verses":[14],"verseLabel":"الأعراف: 14","question":"لماذا اختير ﴿أنظرني﴾، لا: أمهلني؟","answer":"الإنظار تأخير إلى أجل معلوم، أما الإمهال فأعم وقد لا يذكر معه حد؛ فوافق لفظه طلب تحديد الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-70","number":70,"surah":7,"verses":[14],"verseLabel":"الأعراف: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى يوم يبعثون﴾، دون أن يقال: إلى يوم القيامة؟","answer":"ذكر البعث لأنه أراد تجاوز الموت إلى وقت إحياء الخلق، وفيه تصوير لهول الغاية التي طلب بلوغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-71","number":71,"surah":7,"verses":[14],"verseLabel":"الأعراف: 14","question":"لماذا جاء ﴿يبعثون﴾ بالبناء للمجهول؟","answer":"بُني للمجهول لتوجيه النظر إلى حدث بعث الخلق وعظمته، لا إلى إسناد الفعل إلى فاعله المعلوم، وفيه إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-72","number":72,"surah":7,"verses":[14],"verseLabel":"الأعراف: 14","question":"ما سرّ مجيء طلب إبليس في الأعراف: ﴿أنظرني﴾، وفي الحجر وص: ﴿رب فأنظرني﴾؟","answer":"لما اقتصر السياق في الأعراف على الخطاب دون التصريح باسم إبليس، اقتصر هو أيضًا على الطلب دون ﴿رب﴾؛ والفاء في السورتين ناشئة عن معنى الدعاء في النداء.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-73","number":73,"surah":7,"verses":[15],"verseLabel":"الأعراف: 15","question":"ما سرّ الجواب بقوله تعالى: ﴿إنك من المنظرين﴾ بدل: أنظرتك؟","answer":"الجملة الاسمية تدل على أنه داخل في طائفة سبق تقدير تأخير آجالها، لا أنه مُنح إنظارًا خاصًا استجابةً كاملة لطلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-74","number":74,"surah":7,"verses":[15],"verseLabel":"الأعراف: 15","question":"ما سرّ حذف غاية الإنظار من الجواب مع أن إبليس طلب تحديدها؟","answer":"حذف الغاية ليبين أنه لم يُجب إلى اليوم الذي طلبه؛ فكونه من المنظرين يتحقق بتأخيره إلى الوقت المعلوم، وهو قبل بعث الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-75","number":75,"surah":7,"verses":[15],"verseLabel":"الأعراف: 15","question":"ما سرّ مجيء الجواب في الأعراف: ﴿إنك من المنظرين﴾، وفي الحجر وص بالفاء: ﴿فإنك﴾؟","answer":"لم يسبق في الأعراف نداء يقتضي تفريع الجواب، فجاء بلا فاء؛ أما ﴿رب فأنظرني﴾ ففيه معنى: أدعوك فأنظرني، فناسب أن يقال ﴿فإنك﴾.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-76","number":76,"surah":7,"verses":[16],"verseLabel":"الأعراف: 16","question":"ما دلالة نسبة إبليس الغواية إلى الله في قوله: ﴿فبما أغويتني﴾؟","answer":"نسبها إلى الله من جهة القضاء والخذلان جزاء اختياره المعصية، لكنه قالها احتجاجًا وإصرارًا ولم ينسب ضلاله إلى اختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-77","number":77,"surah":7,"verses":[16],"verseLabel":"الأعراف: 16","question":"ما دلالة الباء و﴿ما﴾ في ﴿فبما أغويتني﴾؟","answer":"الباء للسببية أو للقسم، و﴿ما﴾ مصدرية: بسبب إغوائك إياي، أو أقسم بإغوائك؛ وعلى الوجهين بنى وعيده على غوايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-78","number":78,"surah":7,"verses":[16],"verseLabel":"الأعراف: 16","question":"لماذا أكد وعيده باللام والنون: ﴿لأقعدن لهم﴾؟","answer":"اللام موطئة للقسم والنون الثقيلة للتوكيد؛ فاجتمعتا لإظهار عزمه المؤكد على الإغواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-79","number":79,"surah":7,"verses":[16],"verseLabel":"الأعراف: 16","question":"لماذا صوّر الإضلال بالقعود على الطريق؟","answer":"استعار القعود للملازمة والترصد؛ كقاطع الطريق يقعد للمارين ليصدهم عن وجهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-80","number":80,"surah":7,"verses":[16],"verseLabel":"الأعراف: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿صراطك المستقيم﴾، فأضاف الصراط إلى الله؟","answer":"أضيف الصراط إلى الله تشريفًا وبيانًا أنه الطريق الموصل إلى رضاه، ولذلك خصه إبليس بالقعود لإبعاد الناس عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-81","number":81,"surah":7,"verses":[16],"verseLabel":"الأعراف: 16","question":"لماذا عُدّي القعود للصراط بنفسه من غير ﴿على﴾ أو ﴿في﴾؟","answer":"عُدي بنفسه لتضمينه معنى اللزوم والترصد، أو على حذف الجار؛ فاشتد التصاق القعود بالصراط.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-82","number":82,"surah":7,"verses":[17],"verseLabel":"الأعراف: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم لآتينهم﴾ بـ﴿ثم﴾ بعد ﴿لأقعدن﴾؟","answer":"﴿ثم﴾ للترتيب الرتبي: بعد أصل الملازمة والقعود ينتقل إلى مباشرة إتيانهم من وجوه متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-83","number":83,"surah":7,"verses":[17],"verseLabel":"الأعراف: 17","question":"لماذا ذكر الجهات الأربع: الأمام والخلف واليمين والشمال، ولم يذكر الفوق والتحت؟","answer":"ذكر جهات إحاطة العدو بالإنسان، ولم يذكر فوق لأن الرحمة تنزل منه، ولا تحت لأن السجود لله يقع إليه؛ وقيل إن المراد جهات الوسوسة المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-84","number":84,"surah":7,"verses":[17],"verseLabel":"الأعراف: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿من بين أيديهم ومن خلفهم﴾ بـ﴿من﴾، ثم ﴿عن أيمانهم وعن شمائلهم﴾ بـ﴿عن﴾؟","answer":"﴿من﴾ تلائم الابتداء والجهتين الممتدتين أمامًا وخلفًا، و﴿عن﴾ تلائم المجاوزة والميل من جانبي اليمين والشمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-85","number":85,"surah":7,"verses":[17],"verseLabel":"الأعراف: 17","question":"لماذا جُمعت ﴿أيمانهم﴾ و﴿شمائلهم﴾، وأُفرد ما بين الأيدي والخلف؟","answer":"أفرد الأمام والخلف لأن لكل منهما جهة واحدة في الاعتبار، وجمع اليمين والشمال لتعدد جوانبهما أو أعضائهما ومسالك الإتيان منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-86","number":86,"surah":7,"verses":[17],"verseLabel":"الأعراف: 17","question":"لماذا ختم إبليس وعيده بقوله: ﴿ولا تجد أكثرهم شاكرين﴾، لا: مؤمنين؟","answer":"اختار الشكر لأنه ثمرة معرفة نعم الله وطاعته، ونفيه يشمل كفر النعمة والكفر بالله؛ فمراده صرف أكثرهم عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10–30.","url":""}]},{"id":"s7-87","number":87,"surah":7,"verses":[18],"verseLabel":"الأعراف: 18","question":"لماذا أعيد الأمر بالخروج: ﴿اخرج منها﴾ بعد قوله في الآية 13: ﴿فاخرج﴾؟","answer":"أعيد بعد ظهور إصراره ووعيده لتجديد الطرد وتأكيد أنه لا مقام له فيها بعد هذه المجاوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص31–37.","url":""}]},{"id":"s7-88","number":88,"surah":7,"verses":[18],"verseLabel":"الأعراف: 18","question":"لماذا جُمع لإبليس وصفا ﴿مذءومًا مدحورًا﴾؟","answer":"﴿مذءومًا﴾ مطرودًا معيبًا مذمومًا، و﴿مدحورًا﴾ مبعدًا مطرودًا؛ فجمع ذم الحال وإبعاد المكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص31–37.","url":""}]},{"id":"s7-89","number":89,"surah":7,"verses":[18],"verseLabel":"الأعراف: 18","question":"ما سرّ تقديم ﴿مذءومًا﴾ على ﴿مدحورًا﴾؟","answer":"قُدم الذم لأنه سبب الدحر والطرد، أو لأن الإهانة المعنوية تسبق إبعاده وتبين استحقاقه له.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص31–37.","url":""}]},{"id":"s7-90","number":90,"surah":7,"verses":[18],"verseLabel":"الأعراف: 18","question":"لماذا جاء الوعيد: ﴿لأملأن جهنم منكم أجمعين﴾؟","answer":"هو جواب قسم ووعيد لإبليس ومن تبعه، يبين عاقبة مشروع الإغواء وأن الاجتماع على العصيان ينتهي إلى الاجتماع في جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص31–37.","url":""}]},{"id":"s7-91","number":91,"surah":7,"verses":[18],"verseLabel":"الأعراف: 18","question":"إلى من يعود ضمير الجمع في ﴿منكم﴾؟","answer":"يعود إلى إبليس وأتباعه من الجن والإنس؛ ودل جمع الخطاب على إدخال من اتبعه معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص31–37.","url":""}]},{"id":"s7-92","number":92,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿اسكن أنت وزوجك الجنة﴾، فأظهر ﴿أنت﴾ بعد ضمير الفعل؟","answer":"أُظهر ﴿أنت﴾ لتوكيد ضمير الفاعل، وليصح عطف ﴿وزوجك﴾ عليه، مع إبراز آدم أصلًا في الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص37–48.","url":""}]},{"id":"s7-93","number":93,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿زوجك﴾، دون أن يقال: زوجتك؟","answer":"الزوج يطلق على كل واحد من القرينين، وهو الأفصح في هذا المقام؛ أما «زوجة» فصيغة جائزة لكنها أقل في الاستعمال القرآني.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص37–48.","url":""}]},{"id":"s7-94","number":94,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿فكلا من حيث شئتما﴾، ولم يحدد لهما موضعًا؟","answer":"أطلق لهما الأكل من أي موضع شاءا توسعةً وإباحةً عامة، فلم يحتج إلى تحديد إلا في الشجرة المستثناة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص37–48.","url":""}]},{"id":"s7-95","number":95,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"لماذا جاء النهي: ﴿ولا تقربا هذه الشجرة﴾، لا: لا تأكلا منها؟","answer":"النهي عن القرب أبلغ وأحوط من النهي عن الأكل؛ لأنه يسد الطرق المؤدية إليه ويبعدهما عن موضع الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص37–48.","url":""}]},{"id":"s7-96","number":96,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"لماذا أشار إلى الشجرة بـ﴿هذه﴾؟","answer":"اسم الإشارة يعين الشجرة تعيينًا مشاهدًا حتى لا يلتبس المحظور، ويشعر بقربها المكاني منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص37–48.","url":""}]},{"id":"s7-97","number":97,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿فتكونا من الظالمين﴾، دون أن يقال: فتظلما؟","answer":"يجعلهما في جملة الظالمين ويثبت اتصافهما بالظلم إن قرباها؛ وهو أبلغ من نسبة فعل عابر إليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص37–48.","url":""}]},{"id":"s7-98","number":98,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿فكلا من حيث شئتما﴾، وفي البقرة: ﴿وكلا منها رغدًا حيث شئتما﴾؟","answer":"في البقرة زيد ﴿رغدًا﴾ لأن المقام أوسع في تعداد النعم، وقدم متعلق المكان بعده؛ وفي الأعراف اختصر لأن السياق يتجه سريعًا إلى التحذير من إبليس والمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص350–361.","url":""}]},{"id":"s7-99","number":99,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"لماذا عُطف الأكل بالفاء ﴿فكلا﴾ في الأعراف، وبالواو ﴿وكلا﴾ في البقرة؟","answer":"الفاء في الأعراف تفيد ترتب الأكل مباشرة على السكن والإذن، والواو في البقرة لمطلق الجمع مع توسع السياق في ذكر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص350–361.","url":""}]},{"id":"s7-100","number":100,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"لماذا حُذفت ﴿رغدًا﴾ من آية الأعراف وذُكرت في البقرة؟","answer":"ذُكرت في البقرة لإبراز سعة النعمة ورخاء العيش في مقام الامتنان، وحُذفت في الأعراف اختصارًا لأن الغرض متجه إلى قصة المخالفة والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص350–361.","url":""}]},{"id":"s7-101","number":101,"surah":7,"verses":[19],"verseLabel":"الأعراف: 19","question":"لماذا تقدّم ﴿منها﴾ على ﴿حيث شئتما﴾ في البقرة، بينما جاء في الأعراف: ﴿من حيث شئتما﴾؟","answer":"في البقرة تعلق ﴿منها﴾ بالأكل أولًا لإبراز سعة نعيم الجنة، ثم جاء ﴿حيث شئتما﴾؛ أما الأعراف فالمقام مختصر، فجمع منشأ الأكل ومكانه في ﴿من حيث شئتما﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص350–361.","url":""}]},{"id":"s7-102","number":102,"surah":7,"verses":[20],"verseLabel":"الأعراف: 20","question":"لماذا عُدّيت الوسوسة باللام: ﴿فوسوس لهما الشيطان﴾؟","answer":"عُديت باللام لتضمن الوسوسة معنى القول الخفي الموجه إليهما أو إرادة الإغواء لهما؛ فاللام تبين من انتهت إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص48–57.","url":""}]},{"id":"s7-103","number":103,"surah":7,"verses":[20],"verseLabel":"الأعراف: 20","question":"لماذا عُلّلت الوسوسة بقوله: ﴿ليبدي لهما ما ووري عنهما من سوآتهما﴾؟","answer":"اللام للعاقبة والصيرورة على وجه؛ إذ لم يكن مقصوده المباشر كشف العورة، لكن وسوسته آلت إليه؛ ويجوز أن تكون للتعليل باعتبار قصده سلب النعمة وإيذاءهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص48–57.","url":""}]},{"id":"s7-104","number":104,"surah":7,"verses":[20],"verseLabel":"الأعراف: 20","question":"لماذا بُني ﴿ووري﴾ للمجهول وشُدد؟","answer":"بُني للمجهول لأن المقصود كون السوءات مستورة لا ذكر الساتر المعلوم، والتشديد في ﴿وُورِي﴾ للمبالغة في الستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص48–57.","url":""}]},{"id":"s7-105","number":105,"surah":7,"verses":[20],"verseLabel":"الأعراف: 20","question":"لماذا جُمعت ﴿سوآتهما﴾؟","answer":"جُمعت باعتبار سوأة كل واحد منهما وأجزاء العورة، فأضيف الجمع إلى ضمير التثنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص48–57.","url":""}]},{"id":"s7-106","number":106,"surah":7,"verses":[20],"verseLabel":"الأعراف: 20","question":"ما دلالة قصر الشيطان علة النهي في قوله: ﴿ما نهاكما ربكما عن هذه الشجرة إلا أن تكونا ملكين﴾؟","answer":"القصر كذب به إبليس ليصور النهي كأنه لا علة له إلا منع رتبة الملك أو الخلود، فيصرفهما عن حكمة الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص48–57.","url":""}]},{"id":"s7-107","number":107,"surah":7,"verses":[20],"verseLabel":"الأعراف: 20","question":"لماذا اختار فتنتين: الملك والخلود؟","answer":"اختار أشد ما تتطلع إليه النفس: الارتقاء إلى رتبة الملائكة والبقاء بلا موت؛ فجعلهما مدخلًا للغرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص48–57.","url":""}]},{"id":"s7-108","number":108,"surah":7,"verses":[20],"verseLabel":"الأعراف: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿من الخالدين﴾، دون أن يقال: خالدين؟","answer":"إدخالهما ﴿من الخالدين﴾ يصور الخلود رتبةً وجماعةً ينضمان إليها، وهو أقوى من مجرد وصفهما بخالدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص48–57.","url":""}]},{"id":"s7-109","number":109,"surah":7,"verses":[21],"verseLabel":"الأعراف: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وقاسمهما﴾ بصيغة المفاعلة مع أن المقسم هو إبليس؟","answer":"المفاعلة هنا للمبالغة في القسم وتكريره، أو لأنهما قابلا قسمه بالقبول والتصديق فكأن المشاركة حصلت من الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص57–61.","url":""}]},{"id":"s7-110","number":110,"surah":7,"verses":[21],"verseLabel":"الأعراف: 21","question":"لماذا أكد كذبه بـ﴿إني لكما لمن الناصحين﴾؟","answer":"جمع ﴿إن﴾ واللام ولام ﴿لمن﴾ والجملة الاسمية لتثبيت دعوى النصح الكاذبة؛ إذ لم يصدقا أن أحدًا يحلف بالله كاذبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص57–61.","url":""}]},{"id":"s7-111","number":111,"surah":7,"verses":[21],"verseLabel":"الأعراف: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿من الناصحين﴾، لا: ناصح؟","answer":"ادعى أنه واحد من جماعة عُرفت بالنصح، لا ناصح منفرد؛ ليقوي الثقة بقوله ويبالغ في التلبيس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص57–61.","url":""}]},{"id":"s7-112","number":112,"surah":7,"verses":[22],"verseLabel":"الأعراف: 22","question":"لماذا عبّر عن إهباطهما إلى المعصية بقوله: ﴿فدلاهما بغرور﴾؟","answer":"استعيرت التدلية لإنزالهما من مقام الطاعة والنعمة بالتدرج في الخداع؛ كمن يدلي غيره في بئر بحبل يغره ثم يقطعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص61–74.","url":""}]},{"id":"s7-113","number":113,"surah":7,"verses":[22],"verseLabel":"الأعراف: 22","question":"لماذا عُدّي التدلية بالباء في ﴿بغرور﴾؟","answer":"الباء للسببية أو الملابسة: أنزلهما بسبب غروره، أو مصاحبين لما كرره من الخداع والقسم الكاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص61–74.","url":""}]},{"id":"s7-114","number":114,"surah":7,"verses":[22],"verseLabel":"الأعراف: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما ذاقا الشجرة﴾، دون أن يقال: أكلا منها؟","answer":"الذوق أول الأكل وأقله؛ فالتعبير يبين أن أثر المخالفة ظهر بمجرد تناول يسير، ويعظم شأن النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص61–74.","url":""}]},{"id":"s7-115","number":115,"surah":7,"verses":[22],"verseLabel":"الأعراف: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿بدت لهما سوآتهما﴾ بعد أن كانت مواراة؟","answer":"قابل الظهور بالمواراة السابقة: سقط عنهما اللباس الذي كان يسترهما فظهرت عوراتهما لهما، فبادرا إلى الستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص61–74.","url":""}]},{"id":"s7-116","number":116,"surah":7,"verses":[22],"verseLabel":"الأعراف: 22","question":"لماذا اختير ﴿وطفقا يخصفان﴾، لا: أخذا يستران؟","answer":"﴿طفقا﴾ تفيد الشروع والمبادرة، و﴿يخصفان﴾ تصوير لإلصاق الورق بعضه فوق بعض؛ وهو أدق من «يستران».","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص61–74.","url":""}]},{"id":"s7-117","number":117,"surah":7,"verses":[22],"verseLabel":"الأعراف: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿عليهما من ورق الجنة﴾؟","answer":"تفيد ﴿عليهما﴾ وضع الورق مباشرة فوق الجسد للستر، و﴿من﴾ تبين أن مادة الستر بعض ورق الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص61–74.","url":""}]},{"id":"s7-118","number":118,"surah":7,"verses":[22],"verseLabel":"الأعراف: 22","question":"لماذا انتقل من الغيبة إلى نداء الرب: ﴿وناداهما ربهما﴾؟","answer":"النداء يشعر ببعد حالهما بعد المخالفة، وإضافة الرب إليهما تستبقي معنى التربية والرحمة في مقام العتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص61–74.","url":""}]}]);
